// 🔹 REDIRECIONA PARA LOGIN META
app.get("/auth/meta/login", async (c) => {
  try {

  const token = c.req.query("token");

  if (!token) {
    return c.text("Token não enviado");
  }

  const usuario =
    decodificarTokenUsuario(token);

  if (!usuario?.id) {
    return c.text("Token invalido ou expirado", 401);
  }

  const clientId = Bun.env.META_APP_ID;
  const redirectUri = Bun.env.META_REDIRECT_URI;

  if (!clientId || !redirectUri) {
    return c.text("Configuracao Meta incompleta", 500);
  }

  // State temporario de uso unico para o OAuth da Meta.
  const state = gerarMetaOAuthState();
  const stateHash = hashMetaOAuthState(state);

  await client.query(
    `
    DELETE FROM meta_oauth_states
    WHERE expira_em <= NOW()
    OR usado_em IS NOT NULL
    `
  );

  await client.query(
    `
    INSERT INTO meta_oauth_states (
      state_hash,
      usuario_id,
      expira_em
    )
    VALUES (
      $1,
      $2,
      NOW() + ($3 || ' minutes')::interval
    )
    `,
    [
      stateHash,
      usuario.id,
      META_OAUTH_STATE_TTL_MINUTES
    ]
  );

  const scopes = [

    "ads_management",
    "ads_read",
    "business_management",
    "leads_retrieval",
    "pages_show_list",
    "pages_read_engagement",
    "pages_manage_ads",
    // Sem estes dois, a Meta aceita destination_type=WHATSAPP no Ad Set mas
    // ignora silenciosamente promoted_object.whatsapp_phone_number (nao da
    // erro nenhum) - confirmado via /me/permissions retornando "declined"
    // pra ambos numa conexao real, mesmo com o numero certo sendo enviado.
    "whatsapp_business_management",
    "whatsapp_business_messaging"

  ].join(",");

  const params =
    new URLSearchParams({
      client_id: clientId,
      redirect_uri: redirectUri,
      scope: scopes,
      state,
      locale: "pt_BR"
    });

  const url =
    `https://www.facebook.com/v19.0/dialog/oauth?${params.toString()}`;

  return c.redirect(url);
  } catch (err) {
    console.error("ERRO LOGIN META:", err);
    return c.text("Erro ao iniciar conexao Meta", 500);
  }
});


// 🔹 CALLBACK (SALVA TOKEN)
app.get("/auth/meta/callback", async (c) => {
  try {
    const code = c.req.query("code");
    const state = c.req.query("state");

    if (!state) {
      return c.text("State nao recebido");
    }

    if (!code) {
      return c.text("Erro: code não recebido");
    }

    const clientId = Bun.env.META_APP_ID;
    const clientSecret = Bun.env.META_APP_SECRET;
    const redirectUri = Bun.env.META_REDIRECT_URI;

    if (!clientId || !clientSecret || !redirectUri) {
      return c.text("Configuracao Meta incompleta", 500);
    }

    // 🔥 troca code por token
    const stateHash = hashMetaOAuthState(state);
    const db = await client.connect();
    let usuarioId: number | null = null;

    try {
      await db.query("BEGIN");

      const stateResult = await db.query(
        `
        SELECT id, usuario_id
        FROM meta_oauth_states
        WHERE state_hash = $1
        AND usado_em IS NULL
        AND expira_em > NOW()
        LIMIT 1
        FOR UPDATE
        `,
        [stateHash]
      );

      if (stateResult.rows.length === 0) {
        await db.query("ROLLBACK");
        return c.text("State invalido ou expirado", 401);
      }

      usuarioId = Number(stateResult.rows[0].usuario_id);

      await db.query(
        `
        UPDATE meta_oauth_states
        SET usado_em = NOW()
        WHERE id = $1
        `,
        [stateResult.rows[0].id]
      );

      await db.query("COMMIT");
    } catch (err) {
      await db.query("ROLLBACK");
      throw err;
    } finally {
      db.release();
    }

    const params =
      new URLSearchParams({
        client_id: clientId,
        redirect_uri: redirectUri,
        client_secret: clientSecret,
        code
      });

    const tokenRes = await fetch(
      `https://graph.facebook.com/v19.0/oauth/access_token?${params.toString()}`
    );

    const tokenData = await tokenRes.json();
    const access_token = tokenData.access_token;

    if (!tokenRes.ok || !access_token) {
      console.error("ERRO TOKEN META:", tokenData);
      return c.text("Erro ao obter token Meta", 502);
    }

    console.log("META conectada com sucesso");

    if (!usuarioId) {
      return c.text("Usuário inválido", 401);
    }

    // 💾 substitui conexão existente (evita duplicata)
    await client.query(
      "DELETE FROM meta_conexoes WHERE usuario_id = $1",
      [usuarioId]
    );
    await client.query(
      "INSERT INTO meta_conexoes (usuario_id, access_token) VALUES ($1, $2)",
      [usuarioId, access_token]
    );

    // Espelha no hub genérico de conexões
    await client.query(
      `INSERT INTO plataforma_conexoes (usuario_id, plataforma, status, access_token, conectado_em, atualizado_em)
       VALUES ($1, 'meta', 'conectado', $2, NOW(), NOW())
       ON CONFLICT (usuario_id, plataforma)
       DO UPDATE SET status = 'conectado', access_token = $2, atualizado_em = NOW()`,
      [usuarioId, access_token]
    );

    return c.html(`
      <script>
        if (window.opener) {
          window.opener.postMessage({ type: "meta_conectado" }, "${obterFrontendUrl()}");
        }
        window.close();
      </script>
    `);

  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error("ERRO META CALLBACK:", msg, err);
    return c.text(`Erro ao conectar Meta: ${msg}`);
  }
});


/* =========================
   🔌 OAUTH GENÉRICO — demais plataformas de anúncio
   Google, TikTok, LinkedIn, Pinterest, Snapchat, Microsoft, Kwai.
   Aguardando credenciais aprovadas por cada rede. Quando o
   client_id/secret/redirect_uri de uma plataforma forem configurados
   nas envs (ver *_CLIENT_ID/*_CLIENT_SECRET/*_REDIRECT_URI abaixo),
   o fluxo de conexao passa a funcionar sem mais nenhuma mudanca aqui.
========================= */

const OAUTH_PROVEDORES: Record<string, {
  authUrl: string;
  tokenUrl: string;
  scope: string;
  clientIdEnv: string;
  clientSecretEnv: string;
  redirectUriEnv: string;
  extraAuthParams?: Record<string, string>;
}> = {
  google: {
    authUrl: "https://accounts.google.com/o/oauth2/v2/auth",
    tokenUrl: "https://oauth2.googleapis.com/token",
    scope: "https://www.googleapis.com/auth/adwords",
    clientIdEnv: "GOOGLE_ADS_CLIENT_ID",
    clientSecretEnv: "GOOGLE_ADS_CLIENT_SECRET",
    redirectUriEnv: "GOOGLE_ADS_REDIRECT_URI",
    extraAuthParams: { access_type: "offline", prompt: "consent" },
  },
  tiktok: {
    authUrl: "https://business-api.tiktok.com/portal/auth",
    tokenUrl: "https://business-api.tiktok.com/open_api/v1.3/oauth2/access_token/",
    scope: "",
    clientIdEnv: "TIKTOK_ADS_APP_ID",
    clientSecretEnv: "TIKTOK_ADS_APP_SECRET",
    redirectUriEnv: "TIKTOK_ADS_REDIRECT_URI",
  },
  linkedin: {
    authUrl: "https://www.linkedin.com/oauth/v2/authorization",
    tokenUrl: "https://www.linkedin.com/oauth/v2/accessToken",
    // r_marketing_leadgen_automation adicionado pra Lead Gen Forms API (ver
    // secao LINKEDIN ADS) — sem ele /linkedin/formulario e a sincronizacao de
    // respostas de formulario sao rejeitadas mesmo com rw_ads concedido.
    // w_organization_social adicionado pra /linkedin/anuncio: a criacao do
    // anuncio publica um Post em nome da organizacao (POST /posts) antes de
    // vira-lo Creative patrocinado — esse endpoint pertence a API de Posts/
    // Community Management, nao ao Marketing Developer Platform, e exige
    // esse escopo separado mesmo com rw_ads concedido (bug confirmado nesta
    // auditoria: campanha/adgroup/imagem/formulario podiam ser criados com
    // sucesso e só o anuncio final falhar com 403 por falta desse escopo).
    scope: "r_ads r_ads_reporting rw_ads r_marketing_leadgen_automation w_organization_social",
    clientIdEnv: "LINKEDIN_ADS_CLIENT_ID",
    clientSecretEnv: "LINKEDIN_ADS_CLIENT_SECRET",
    redirectUriEnv: "LINKEDIN_ADS_REDIRECT_URI",
  },
  pinterest: {
    authUrl: "https://www.pinterest.com/oauth/",
    tokenUrl: "https://api.pinterest.com/v5/oauth/token",
    scope: "ads:read,ads:write",
    clientIdEnv: "PINTEREST_ADS_APP_ID",
    clientSecretEnv: "PINTEREST_ADS_APP_SECRET",
    redirectUriEnv: "PINTEREST_ADS_REDIRECT_URI",
  },
  snapchat: {
    authUrl: "https://accounts.snapchat.com/login/oauth2/authorize",
    tokenUrl: "https://accounts.snapchat.com/login/oauth2/access_token",
    scope: "snapchat-marketing-api",
    clientIdEnv: "SNAPCHAT_ADS_CLIENT_ID",
    clientSecretEnv: "SNAPCHAT_ADS_CLIENT_SECRET",
    redirectUriEnv: "SNAPCHAT_ADS_REDIRECT_URI",
  },
  microsoft: {
    authUrl: "https://login.microsoftonline.com/common/oauth2/v2.0/authorize",
    tokenUrl: "https://login.microsoftonline.com/common/oauth2/v2.0/token",
    scope: "https://ads.microsoft.com/msads.manage offline_access",
    clientIdEnv: "MICROSOFT_ADS_CLIENT_ID",
    clientSecretEnv: "MICROSOFT_ADS_CLIENT_SECRET",
    redirectUriEnv: "MICROSOFT_ADS_REDIRECT_URI",
  },
  kwai: {
    // Kwai ainda nao publica um fluxo OAuth self-service documentado;
    // authUrl/tokenUrl ficam vazios de proposito ate isso existir.
    authUrl: "",
    tokenUrl: "",
    scope: "",
    clientIdEnv: "KWAI_ADS_CLIENT_ID",
    clientSecretEnv: "KWAI_ADS_CLIENT_SECRET",
    redirectUriEnv: "KWAI_ADS_REDIRECT_URI",
  },
};

function gerarOAuthStateGenerico() {
  return base64Url(randomBytes(32));
}
function hashOAuthStateGenerico(state: string) {
  return assinarPayload(`plataforma-oauth-state:${state}`);
}

app.get("/auth/:plataforma/login", async (c) => {
  const plataforma = c.req.param("plataforma");
  const cfg = OAUTH_PROVEDORES[plataforma];
  if (!cfg) return c.text("Plataforma nao suporta conexao OAuth", 404);

  try {
    const token = c.req.query("token");
    if (!token) return c.text("Token nao enviado", 400);

    const usuario = decodificarTokenUsuario(token);
    if (!usuario?.id) return c.text("Token invalido ou expirado", 401);

    const clientId    = Bun.env[cfg.clientIdEnv];
    const redirectUri = Bun.env[cfg.redirectUriEnv];

    if (!clientId || !redirectUri || !cfg.authUrl) {
      return c.text(
        `Integracao com ${plataforma} ainda nao configurada (credenciais pendentes de aprovacao da plataforma).`,
        503
      );
    }

    const state = gerarOAuthStateGenerico();
    const stateHash = hashOAuthStateGenerico(state);

    await client.query(
      `DELETE FROM plataforma_oauth_states WHERE expira_em <= NOW() OR usado_em IS NOT NULL`
    );
    await client.query(
      `INSERT INTO plataforma_oauth_states (state_hash, usuario_id, plataforma, expira_em)
       VALUES ($1, $2, $3, NOW() + ($4 || ' minutes')::interval)`,
      [stateHash, usuario.id, plataforma, META_OAUTH_STATE_TTL_MINUTES]
    );

    const params = new URLSearchParams({
      client_id: clientId,
      redirect_uri: redirectUri,
      response_type: "code",
      scope: cfg.scope,
      state,
      ...(cfg.extraAuthParams || {}),
    });

    return c.redirect(`${cfg.authUrl}?${params.toString()}`);
  } catch (err) {
    console.error(`ERRO /auth/${plataforma}/login:`, err);
    return c.text("Token invalido ou expirado", 401);
  }
});

app.get("/auth/:plataforma/callback", async (c) => {
  const plataforma = c.req.param("plataforma");
  const cfg = OAUTH_PROVEDORES[plataforma];
  if (!cfg) return c.text("Plataforma nao suporta conexao OAuth", 404);

  try {
    const code  = c.req.query("code");
    const state = c.req.query("state");
    if (!state) return c.text("State nao recebido", 400);
    if (!code)  return c.text("Erro: code nao recebido", 400);

    const clientId     = Bun.env[cfg.clientIdEnv];
    const clientSecret = Bun.env[cfg.clientSecretEnv];
    const redirectUri   = Bun.env[cfg.redirectUriEnv];

    if (!clientId || !clientSecret || !redirectUri) {
      return c.text(`Configuracao de ${plataforma} incompleta`, 500);
    }

    const stateHash = hashOAuthStateGenerico(state);
    const db = await client.connect();
    let usuarioId: number | null = null;

    try {
      await db.query("BEGIN");

      const stateResult = await db.query(
        `SELECT id, usuario_id FROM plataforma_oauth_states
         WHERE state_hash = $1 AND plataforma = $2 AND usado_em IS NULL AND expira_em > NOW()
         LIMIT 1 FOR UPDATE`,
        [stateHash, plataforma]
      );

      if (stateResult.rows.length === 0) {
        await db.query("ROLLBACK");
        return c.text("State invalido ou expirado", 401);
      }

      usuarioId = Number(stateResult.rows[0].usuario_id);

      await db.query(
        `UPDATE plataforma_oauth_states SET usado_em = NOW() WHERE id = $1`,
        [stateResult.rows[0].id]
      );

      await db.query("COMMIT");
    } catch (err) {
      await db.query("ROLLBACK");
      throw err;
    } finally {
      db.release();
    }

    // TikTok usa JSON body e estrutura de resposta diferente do padrão OAuth2
    // TODO(kwai): OAUTH_PROVEDORES.kwai ainda tem authUrl/tokenUrl vazios de
    // proposito (sem fluxo self-service documentado), entao /auth/kwai/login
    // ja retorna 503 antes de chegar aqui — nao da pra saber se o token
    // endpoint da Kuaishou tambem vai precisar de um branch especial como o
    // da TikTok acima ate termos a documentacao oficial de parceiro.
    let access_token: string;
    let refresh_token: string | null = null;
    let dadosConta: Record<string, any> = {};

    if (plataforma === "tiktok") {
      const tokenRes = await fetch(cfg.tokenUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          app_id: clientId,
          auth_code: code,
          secret: clientSecret,
        }),
      });
      const tokenData = await tokenRes.json() as any;
      if (tokenData.code !== 0 || !tokenData.data?.access_token) {
        console.error("ERRO TOKEN TIKTOK:", tokenData);
        return c.text("Erro ao obter token TikTok", 502);
      }
      access_token = tokenData.data.access_token;
      refresh_token = tokenData.data.refresh_token ?? null;
      const advertiserIds: string[] = tokenData.data.advertiser_ids ?? [];
      dadosConta = { advertiser_ids: advertiserIds };
    } else {
      const tokenRes = await fetch(cfg.tokenUrl, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          grant_type: "authorization_code",
          code,
          redirect_uri: redirectUri,
          client_id: clientId,
          client_secret: clientSecret,
        }),
      });
      const tokenData = await tokenRes.json() as any;
      if (!tokenRes.ok || !tokenData.access_token) {
        console.error(`ERRO TOKEN ${plataforma.toUpperCase()}:`, tokenData);
        return c.text(`Erro ao obter token de ${plataforma}`, 502);
      }
      access_token = tokenData.access_token;
      refresh_token = tokenData.refresh_token ?? null;
    }

    if (!usuarioId) {
      return c.text("Usuario invalido", 401);
    }

    await client.query(
      `INSERT INTO plataforma_conexoes
         (usuario_id, plataforma, status, access_token, refresh_token, dados_conta, conectado_em, atualizado_em)
       VALUES ($1, $2, 'conectado', $3, $4, $5, NOW(), NOW())
       ON CONFLICT (usuario_id, plataforma)
       DO UPDATE SET status = 'conectado', access_token = $3, refresh_token = $4,
                     dados_conta = $5, atualizado_em = NOW()`,
      [usuarioId, plataforma, access_token, refresh_token, JSON.stringify(dadosConta)]
    );

    return c.html(`
      <script>
        if (window.opener) {
          window.opener.postMessage({ type: "plataforma_conectada", plataforma: "${plataforma}" }, "${obterFrontendUrl()}");
        }
        window.close();
      </script>
    `);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`ERRO CALLBACK ${plataforma.toUpperCase()}:`, msg, err);
    return c.text(`Erro ao conectar ${plataforma}: ${msg}`);
  }
});

/* =========================
   🔴 GOOGLE ADS
   ATENCAO: GOOGLE_ADS_API_VERSION precisa ser conferida periodicamente —
   desde 2026 o Google lanca uma versao por mes (major.minor, ex: v24.1,
   v24.2), mas releases menores nao trocam o segmento de versao da URL
   REST — so o numero major (ex: "v24") importa aqui. O Google descontinua
   versoes major antigas cerca de 1 ano apos o lancamento.
   Ver https://developers.google.com/google-ads/api/docs/release-notes
========================= */

const googleSyncEmAndamento = new Set<number>();

const GOOGLE_ADS_API_VERSION = "v24";
const GOOGLE_ADS_API = `https://googleads.googleapis.com/${GOOGLE_ADS_API_VERSION}`;
const googleLoginCustomerIdPorToken = new Map<string, string>();

async function obterAccessTokenGoogle(refreshToken: string): Promise<string> {
  const res = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: Bun.env.GOOGLE_ADS_CLIENT_ID || "",
      client_secret: Bun.env.GOOGLE_ADS_CLIENT_SECRET || "",
      refresh_token: refreshToken,
      grant_type: "refresh_token",
    }),
  });
  const data = await res.json() as any;
  if (!res.ok || !data.access_token) {
    console.error("ERRO REFRESH TOKEN GOOGLE:", data);
    throw new Error(data.error_description || "Erro ao renovar token do Google Ads");
  }
  return data.access_token;
}

function googleAdsHeaders(accessToken: string, loginCustomerId?: string | null) {
  const loginId = loginCustomerId || googleLoginCustomerIdPorToken.get(accessToken) || null;
  return {
    Authorization: `Bearer ${accessToken}`,
    "developer-token": Bun.env.GOOGLE_ADS_DEVELOPER_TOKEN || "",
    ...(loginId ? { "login-customer-id": String(loginId).replace(/\D/g, "") } : {}),
    "Content-Type": "application/json",
  };
}

async function googleAdsQuery(customerId: string, accessToken: string, gaql: string, loginCustomerId?: string | null) {
  const res = await fetch(
    `${GOOGLE_ADS_API}/customers/${customerId}/googleAds:search`,
    {
      method: "POST",
      headers: googleAdsHeaders(accessToken, loginCustomerId),
      body: JSON.stringify({ query: gaql }),
    }
  );
  const data = await res.json() as any;
  if (!res.ok) {
    console.error("ERRO GOOGLE ADS QUERY:", customerId, JSON.stringify(data, null, 2));
    throw new Error(data?.error?.message || "Erro ao consultar Google Ads");
  }
  return data.results ?? [];
}

type ContaGoogleAds = {
  customer_id: string;
  nome: string;
  gerenciadora: boolean;
  login_customer_id: string | null;
};

async function listarContasGoogleAds(accessToken: string): Promise<{ contas: ContaGoogleAds[]; avisos: string[] }> {
  const listRes = await fetch(`${GOOGLE_ADS_API}/customers:listAccessibleCustomers`, {
    headers: googleAdsHeaders(accessToken),
  });
  const listData = await listRes.json() as any;
  if (!listRes.ok) {
    throw new Error(listData?.error?.message || "Erro ao buscar contas do Google Ads");
  }

  const contas = new Map<string, ContaGoogleAds>();
  const avisos: string[] = [];
  for (const resourceName of (listData.resourceNames ?? []) as string[]) {
    const customerId = resourceName.split("/")[1];
    try {
      const results = await googleAdsQuery(
        customerId, accessToken,
        "SELECT customer.id, customer.descriptive_name, customer.manager FROM customer LIMIT 1"
      );
      const info = (results[0] as any)?.customer;
      const gerenciadora = Boolean(info?.manager);
      contas.set(customerId, {
        customer_id: customerId,
        nome: info?.descriptiveName || customerId,
        gerenciadora,
        login_customer_id: null,
      });

      if (gerenciadora) {
        try {
          // Consulta recomendada pela documentação oficial para obter a hierarquia.
          // O nível 0 é a própria MCC; nível 1 são seus clientes diretos.
          const clientes = await googleAdsQuery(
            customerId, accessToken,
            `SELECT customer_client.client_customer, customer_client.id,
                    customer_client.descriptive_name, customer_client.manager,
                    customer_client.level
             FROM customer_client
             WHERE customer_client.level <= 1`,
            customerId
          );
          for (const row of clientes as any[]) {
            const cliente = row.customerClient || row.customer_client;
            const clienteId = String(
              cliente?.id || String(cliente?.clientCustomer || cliente?.client_customer || "").split("/")[1] || ""
            );
            if (!clienteId || Number(cliente.level) === 0) continue;
            contas.set(clienteId, {
              customer_id: clienteId,
              nome: cliente.descriptiveName || clienteId,
              gerenciadora: Boolean(cliente.manager),
              login_customer_id: customerId,
            });
          }
        } catch (errClientes: any) {
          const mensagem = errClientes?.message || "Não foi possível consultar as contas vinculadas";
          avisos.push(`MCC ${customerId}: ${mensagem}`);
          console.error("ERRO GOOGLE ADS AO EXPANDIR MCC:", customerId, mensagem);
        }
      }
    } catch (err: any) {
      console.warn("AVISO GOOGLE ADS AO LISTAR CONTA:", customerId, err?.message || err);
      if (!contas.has(customerId)) {
        contas.set(customerId, { customer_id: customerId, nome: customerId, gerenciadora: false, login_customer_id: null });
      }
    }
  }
  return { contas: [...contas.values()], avisos };
}

// Lista as contas do Google Ads acessiveis pelo usuario conectado
app.get("/google/contas", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    if (!Bun.env.GOOGLE_ADS_DEVELOPER_TOKEN) {
      return c.json({ error: "Developer token do Google Ads nao configurado" }, 500);
    }

    const conn = await client.query(
      `SELECT refresh_token FROM plataforma_conexoes
       WHERE usuario_id = $1 AND plataforma = 'google' LIMIT 1`,
      [user.id]
    );
    if (!conn.rows.length || !conn.rows[0].refresh_token) {
      return c.json({ error: "Google Ads nao conectado" }, 400);
    }

    const accessToken = await obterAccessTokenGoogle(conn.rows[0].refresh_token);

    const { contas, avisos } = await listarContasGoogleAds(accessToken);

    return c.json({ contas, avisos });
  } catch (err: any) {
    console.error("ERRO /google/contas:", err);
    return c.json({ error: err.message || "Erro interno" }, 500);
  }
});

// Salva a conta do Google Ads selecionada pelo usuario
app.post("/google/selecionar-conta", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    const { customer_id } = await c.req.json();
    const customerId = String(customer_id || "").replace(/\D/g, "");
    if (!customerId) return c.json({ error: "customer_id obrigatorio" }, 400);

    const conn = await client.query(
      `SELECT refresh_token FROM plataforma_conexoes
       WHERE usuario_id = $1 AND plataforma = 'google' LIMIT 1`,
      [user.id]
    );
    if (!conn.rows.length || !conn.rows[0].refresh_token) {
      return c.json({ error: "Google Ads nao conectado" }, 400);
    }
    const accessToken = await obterAccessTokenGoogle(conn.rows[0].refresh_token);
    const contasAcessiveis = (await listarContasGoogleAds(accessToken)).contas;
    let conta = contasAcessiveis.find(item => item.customer_id === customerId);

    // Fallback para contas recém-criadas/vinculadas que ainda não aparecem na
    // hierarquia customer_client. A conta só é aceita se uma MCC acessível
    // conseguir consultá-la explicitamente pela API do Google Ads.
    const errosConsultaDireta: string[] = [];
    if (!conta) {
      for (const mcc of contasAcessiveis.filter(item => item.gerenciadora)) {
        try {
          const results = await googleAdsQuery(
            customerId, accessToken,
            "SELECT customer.id, customer.descriptive_name, customer.manager FROM customer LIMIT 1",
            mcc.customer_id
          );
          const info = (results[0] as any)?.customer;
          if (info?.id) {
            conta = {
              customer_id: customerId,
              nome: info.descriptiveName || customerId,
              gerenciadora: Boolean(info.manager),
              login_customer_id: mcc.customer_id,
            };
            break;
          }
        } catch (errDireto: any) {
          errosConsultaDireta.push(`MCC ${mcc.customer_id}: ${errDireto?.message || "acesso negado"}`);
        }
      }
    }
    if (!conta) {
      return c.json({
        error: "A conta informada não está acessível por nenhuma MCC conectada",
        detalhe: errosConsultaDireta.join(" | ") || "O Google Ads não retornou a conta na hierarquia da MCC"
      }, 400);
    }

    await client.query(
      `UPDATE plataforma_conexoes
       SET dados_conta = COALESCE(dados_conta, '{}'::jsonb) || jsonb_build_object(
             'customer_id', $1::text,
             'login_customer_id', $2::text
           ),
           atualizado_em = NOW()
       WHERE usuario_id = $3 AND plataforma = 'google'`,
      [customerId, conta.login_customer_id, user.id]
    );
    return c.json({ sucesso: true });
  } catch (err: any) {
    console.error("ERRO /google/selecionar-conta:", err);
    return c.json({ error: "Erro interno" }, 500);
  }
});

// Resumo da conta conectada: dados da conta, gasto de hoje e contagens locais
app.get("/google/status-completo", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    const conn = await client.query(
      `SELECT refresh_token, dados_conta, conectado_em, atualizado_em FROM plataforma_conexoes
       WHERE usuario_id = $1 AND plataforma = 'google' LIMIT 1`,
      [user.id]
    );
    if (!conn.rows.length || !conn.rows[0].refresh_token) {
      return c.json({ conectado: false });
    }

    const dadosConta = conn.rows[0].dados_conta ?? {};
    const customerId = dadosConta.customer_id;
    const loginCustomerId = dadosConta.login_customer_id || null;

    const [campanhasCount, leadsHojeCount] = await Promise.all([
      client.query(
        `SELECT COUNT(*) FILTER (WHERE status = 'ENABLED') AS ativas, COUNT(*) AS total
         FROM campanhas WHERE usuario_id = $1 AND plataforma = 'google'`,
        [user.id]
      ),
      client.query(
        // criado_em é timestamp sem timezone armazenado em UTC — comparar direto com
        // CURRENT_DATE (também UTC) faz "hoje" virar "ontem" assim que passa das 21h em
        // Brasília (UTC-3), horário em que o dia UTC já virou mas o dia local não.
        `SELECT COUNT(*) AS total FROM leads
         WHERE usuario_id = $1 AND plataforma = 'google'
         AND (criado_em AT TIME ZONE 'UTC' AT TIME ZONE 'America/Sao_Paulo')::date = (NOW() AT TIME ZONE 'America/Sao_Paulo')::date`,
        [user.id]
      ),
    ]);

    const base = {
      conectado: true,
      conta_selecionada: Boolean(customerId),
      customer_id: customerId ? String(customerId) : null,
      ultimo_sync: conn.rows[0].atualizado_em ?? null,
      campanhas_ativas: Number(campanhasCount.rows[0]?.ativas ?? 0),
      campanhas_total: Number(campanhasCount.rows[0]?.total ?? 0),
      leads_hoje: Number(leadsHojeCount.rows[0]?.total ?? 0),
    };

    if (!customerId || !Bun.env.GOOGLE_ADS_DEVELOPER_TOKEN) {
      return c.json({ ...base, conta: null, gasto_hoje: null });
    }

    try {
      const accessToken = await obterAccessTokenGoogle(conn.rows[0].refresh_token);

      // Cada consulta é isolada em seu próprio try/catch — antes rodavam num único
      // Promise.all, e a conta/pagamento (que funcionam normalmente) ficavam null
      // sempre que só UMA das consultas falhava. Isso acontece sempre que a conta
      // selecionada é uma conta gerenciadora (MCC): a Google Ads API proíbe pedir
      // métricas (gasto) diretamente numa conta gerenciadora
      // (erro "REQUESTED_METRICS_FOR_MANAGER") — só contas de cliente têm gasto
      // próprio. Isso não é uma falha de verdade, é esperado para esse tipo de conta.
      let contaInfo: any = null;
      try {
        const contaResults = await googleAdsQuery(
          customerId, accessToken,
          "SELECT customer.descriptive_name, customer.currency_code, customer.time_zone, customer.status, customer.manager FROM customer LIMIT 1",
          loginCustomerId
        );
        contaInfo = (contaResults[0] as any)?.customer ?? null;
      } catch (errConta: any) {
        console.error("ERRO /google/status-completo (conta):", errConta.message);
      }

      let gastoMicros: number | null = null;
      if (!contaInfo?.manager) {
        try {
          const gastoResults = await googleAdsQuery(
            customerId, accessToken,
            "SELECT metrics.cost_micros FROM campaign WHERE segments.date DURING TODAY",
            loginCustomerId
          );
          gastoMicros = (gastoResults as any[]).reduce(
            (soma, row) => soma + Number(row.metrics?.costMicros ?? 0), 0
          );
        } catch (errGasto: any) {
          console.warn("AVISO /google/status-completo (gasto indisponivel):", errGasto.message);
        }
      }

      // Status de pagamento: consulta best-effort — nem toda conta expoe billing_setup
      // (ex: contas gerenciadas so pelo billing do MCC), entao falha aqui nao quebra o resto.
      let pagamento: { status: string | null; texto: string } = {
        status: null,
        texto: contaInfo?.manager ? "Não se aplica (conta gerenciadora)" : "Não identificado",
      };
      if (!contaInfo?.manager) {
        try {
          const billingResults = await googleAdsQuery(
            customerId, accessToken,
            "SELECT billing_setup.status FROM billing_setup",
            loginCustomerId
          );
          const statusBilling = (billingResults[0] as any)?.billingSetup?.status ?? null;
          pagamento = {
            status: statusBilling,
            texto: statusBilling === "APPROVED" ? "Aprovado"
              : statusBilling === "PENDING" ? "Pendente"
              : statusBilling === "CANCELLED" ? "Cancelado"
              : "Não identificado",
          };
        } catch (_) {}
      }

      return c.json({
        ...base,
        conta: contaInfo ? {
          nome: contaInfo.descriptiveName || customerId,
          moeda: contaInfo.currencyCode || null,
          fuso_horario: contaInfo.timeZone || null,
          status: contaInfo.status || null,
          gerenciadora: Boolean(contaInfo.manager),
        } : null,
        gasto_hoje: gastoMicros === null ? null : gastoMicros / 1_000_000,
        pagamento,
      });
    } catch (errApi: any) {
      console.error("ERRO /google/status-completo (API Google):", errApi.message);
      return c.json({ ...base, conta: null, gasto_hoje: null, pagamento: null, aviso: "Nao foi possivel consultar dados ao vivo do Google Ads" });
    }
  } catch (err: any) {
    console.error("ERRO /google/status-completo:", err);
    return c.json({ error: "Erro interno" }, 500);
  }
});

// Sincroniza campanhas e leads (Lead Form Extensions) do Google Ads. A mesma
// função é usada pelo botão manual e pelo ciclo automático.
async function sincronizarGoogleAdsUsuario(usuarioId: number) {
    if (!Bun.env.GOOGLE_ADS_DEVELOPER_TOKEN) {
      throw new Error("Developer token do Google Ads nao configurado");
    }

    const conn = await client.query(
      `SELECT refresh_token, dados_conta FROM plataforma_conexoes
       WHERE usuario_id = $1 AND plataforma = 'google' LIMIT 1`,
      [usuarioId]
    );
    if (!conn.rows.length || !conn.rows[0].refresh_token) {
      throw new Error("Google Ads nao conectado");
    }

    const dadosConta = conn.rows[0].dados_conta ?? {};
    const customerId = dadosConta.customer_id;
    const loginCustomerId = dadosConta.login_customer_id || null;
    if (!customerId) {
      throw new Error("Selecione a conta do Google Ads antes de sincronizar");
    }

    const accessToken = await obterAccessTokenGoogle(conn.rows[0].refresh_token);

    // 🔥 BUSCA CAMPANHAS
    const campanhasResults = await googleAdsQuery(
      customerId, accessToken,
      "SELECT campaign.id, campaign.name, campaign.status FROM campaign",
      loginCustomerId
    );

    for (const row of campanhasResults as any[]) {
      const campanha = row.campaign;
      const campaignId = String(campanha.id);

      const existe = await client.query(
        `SELECT id FROM campanhas WHERE campaign_id = $1 AND usuario_id = $2`,
        [campaignId, usuarioId]
      );

      if (existe.rows.length > 0) {
        await client.query(
          `UPDATE campanhas SET nome = $1, status = $2, atualizado_em = NOW()
           WHERE campaign_id = $3 AND usuario_id = $4`,
          [campanha.name, campanha.status, campaignId, usuarioId]
        );
      } else {
        await client.query(
          `INSERT INTO campanhas (usuario_id, campaign_id, conta_anuncios_id, nome, status, origem, plataforma, atualizado_em)
           VALUES ($1, $2, $3, $4, $5, 'google', 'google', NOW())`,
          [usuarioId, campaignId, String(customerId), campanha.name, campanha.status]
        );
      }
    }

    // 🔥 BUSCA LEADS (Lead Form Extensions, ultimos 30 dias)
    const trintaDiasAtras = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
    const formatarDataHoraGoogle = (d: Date) => d.toISOString().slice(0, 19).replace("T", " ");
    const inicio = formatarDataHoraGoogle(trintaDiasAtras);
    const fim = formatarDataHoraGoogle(new Date());

    const leadsResults = await googleAdsQuery(
      customerId, accessToken,
      `SELECT lead_form_submission_data.id, lead_form_submission_data.campaign,
              lead_form_submission_data.submission_date_time,
              lead_form_submission_data.lead_form_submission_fields,
              lead_form_submission_data.gclid
       FROM lead_form_submission_data
       WHERE lead_form_submission_data.submission_date_time BETWEEN '${inicio}' AND '${fim}'`,
      loginCustomerId
    );

    let totalLeads = 0;

    for (const row of leadsResults as any[]) {
      const dadosLead = row.leadFormSubmissionData;
      const leadId = String(dadosLead.id);

      const jaExiste = await client.query(
        `SELECT id FROM leads WHERE lead_id = $1 AND usuario_id = $2`,
        [leadId, usuarioId]
      );
      if (jaExiste.rows.length > 0) continue;

      let nomeCampanha = "Campanha Google Ads";
      let nichoId: number | null = null;
      // lead_form_submission_data.campaign vem como resource name
      // ("customers/123/campaigns/456"), nao como ID numerico direto.
      const campaignIdLead = String(dadosLead.campaign || "").split("/").pop() || "";
      if (campaignIdLead) {
        const campRow = await client.query(
          `SELECT nome, nicho_id FROM campanhas WHERE campaign_id = $1 AND usuario_id = $2 LIMIT 1`,
          [campaignIdLead, usuarioId]
        );
        if (campRow.rows.length) {
          nomeCampanha = campRow.rows[0].nome;
          nichoId = campRow.rows[0].nicho_id ?? null;
        }
      }

      let nome = "";
      let email = "";
      let telefone = "";
      const respostasQualificacao: any[] = [];

      for (const field of dadosLead.leadFormSubmissionFields ?? []) {
        const tipo = String(field.fieldType ?? "").toUpperCase();
        if (tipo === "FULL_NAME" || tipo === "FIRST_NAME") nome = field.fieldValue ?? "";
        else if (tipo === "EMAIL") email = field.fieldValue ?? "";
        else if (tipo === "PHONE_NUMBER") telefone = field.fieldValue ?? "";
        else respostasQualificacao.push({ pergunta: field.fieldType, resposta: field.fieldValue ?? "" });
      }

      const criadoEm = dadosLead.submissionDateTime
        ? new Date(String(dadosLead.submissionDateTime).replace(" ", "T") + "Z").toISOString()
        : null;

      const leadInseridoGoogle = await client.query(
        `INSERT INTO leads
           (usuario_id, lead_id, nome, email, telefone, campanha, conta_anuncios_id,
            origem, plataforma, status, respostas_qualificacao, nicho_id, criado_em, gclid)
         VALUES ($1,$2,$3,$4,$5,$6,$7,'google','google','novo',$8,$9,COALESCE($10::timestamptz, NOW()),$11)
         RETURNING id`,
        [
          usuarioId, leadId, nome || "Lead Google Ads", email, telefone,
          nomeCampanha, String(customerId),
          JSON.stringify(respostasQualificacao), nichoId, criadoEm,
          textoOpcional(dadosLead.gclid)
        ]
      );

      await notificarNovoLeadWhatsApp(usuarioId, { nome, telefone, email, campanha: nomeCampanha });

      avaliarEEnviarQualificacaoLead(
        {
          id: leadInseridoGoogle.rows[0]?.id,
          lead_id: leadId,
          plataforma: "google",
          status: "novo",
          gclid: textoOpcional(dadosLead.gclid),
          respostas_qualificacao: respostasQualificacao
        },
        usuarioId
      ).catch(err => console.error("ERRO avaliarEEnviarQualificacaoLead (sync google):", err));
      totalLeads++;
    }

    await client.query(
      `UPDATE plataforma_conexoes SET atualizado_em = NOW()
       WHERE usuario_id = $1 AND plataforma = 'google'`,
      [usuarioId]
    );

    return { sucesso: true, campanhas: campanhasResults.length, leads_novos: totalLeads };
}

app.post("/google/sincronizar-campanhas", authMiddleware, async (c) => {
  const user: any = c.get("user");

  if (googleSyncEmAndamento.has(user.id)) {
    return c.json({ error: "Sincronizacao Google Ads ja em andamento" }, 429);
  }
  googleSyncEmAndamento.add(user.id);

  try {
    return c.json(await sincronizarGoogleAdsUsuario(user.id));
  } catch (err: any) {
    console.error("ERRO GOOGLE SINCRONIZAR:", err);
    return c.json({ error: err.message || "Erro ao sincronizar Google Ads" }, 500);
  } finally {
    googleSyncEmAndamento.delete(user.id);
  }
});

/* =========================
   🔴 GOOGLE ADS — PUBLICACAO
   Pesquisa e Display com destino em Lead Form ou site; Pesquisa tambem pode
   receber Business Message Asset nativo do WhatsApp. O numero vem da conexao
   do WhatsApp Bot do proprio usuario, sem ser aceito livremente no payload.
========================= */

async function resolverConexaoGoogleAds(
  usuarioId: number
): Promise<{ erro: string } | { accessToken: string; customerId: string; loginCustomerId: string | null }> {
  const conn = await client.query(
    `SELECT refresh_token, dados_conta FROM plataforma_conexoes
     WHERE usuario_id = $1 AND plataforma = 'google' LIMIT 1`,
    [usuarioId]
  );
  if (!conn.rows.length || !conn.rows[0].refresh_token) {
    return { erro: "Google Ads não conectado" };
  }

  const customerId = (conn.rows[0].dados_conta ?? {}).customer_id;
  const loginCustomerId = (conn.rows[0].dados_conta ?? {}).login_customer_id || null;
  if (!customerId) {
    return { erro: "Selecione a conta do Google Ads antes de publicar" };
  }

  const accessToken = await obterAccessTokenGoogle(conn.rows[0].refresh_token);
  if (loginCustomerId) {
    googleLoginCustomerIdPorToken.set(accessToken, String(loginCustomerId));
    setTimeout(() => googleLoginCustomerIdPorToken.delete(accessToken), 60 * 60 * 1000);
  }
  return { accessToken, customerId: String(customerId), loginCustomerId: loginCustomerId ? String(loginCustomerId) : null };
}

type NumeroWhatsappGoogle = {
  countryCode: "BR";
  phoneNumber: string;
  comparavel: string;
};

// O numero usado pelo Google deve ser exatamente o mesmo conectado ao bot da
// plataforma. Isso evita que um usuario injete no payload um WhatsApp de terceiros
// e garante que as conversas novas cheguem ao fluxo de atendimento ja configurado.
async function resolverNumeroWhatsappGoogle(
  usuarioId: number
): Promise<{ erro: string } | NumeroWhatsappGoogle> {
  const conexao = await client.query(
    `SELECT dados_conta
     FROM plataforma_conexoes
     WHERE usuario_id = $1
       AND plataforma = 'whatsapp'
       AND status = 'conectado'
     LIMIT 1`,
    [usuarioId]
  );

  const dadosBrutos = conexao.rows[0]?.dados_conta;
  let dadosConta: any = dadosBrutos || {};
  if (typeof dadosBrutos === "string") {
    try { dadosConta = JSON.parse(dadosBrutos); } catch { dadosConta = {}; }
  }

  if (!dadosConta?.waba_id || !dadosConta?.phone_number_id) {
    return { erro: "Conecte e conclua a configuração do WhatsApp na aba WhatsApp Bot antes de publicar esta campanha." };
  }

  const digitosOriginais = String(dadosConta?.numero || "").replace(/\D/g, "");
  const numeroNacional =
    digitosOriginais.startsWith("55") && (digitosOriginais.length === 12 || digitosOriginais.length === 13)
      ? digitosOriginais.slice(2)
      : digitosOriginais;

  if (!/^\d{10,11}$/.test(numeroNacional)) {
    return {
      erro: "O WhatsApp Bot está conectado, mas o número salvo não está em um formato brasileiro válido. Reconecte o WhatsApp antes de publicar."
    };
  }

  return {
    countryCode: "BR",
    phoneNumber: numeroNacional,
    comparavel: `55${numeroNacional}`,
  };
}

// Cria (ou reaproveita) a Conversion Action do Google Ads usada como alvo do
// uploadClickConversions — equivalente ao dataset/pixel da Meta
// (obterOuCriarDatasetMetaUsuario), mas o Google exige uma Conversion Action
// dedicada por TIPO de evento, nao um nome de evento livre por chamada. O
// resource name criado fica salvo em plataforma_conexoes.dados_conta (chave
// "conversion_action_qualified_id"/"conversion_action_closed_id") pra nao
// recriar a cada envio.
async function obterOuCriarConversionActionGoogle(
  usuarioId: number,
  customerId: string,
  accessToken: string,
  loginCustomerId: string | null,
  chave: "qualified" | "closed",
  nomeEvento: string
): Promise<string | null> {
  const campoJson =
    chave === "qualified"
      ? "conversion_action_qualified_id"
      : "conversion_action_closed_id";

  try {
    const conexao = await client.query(
      `SELECT id, dados_conta FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'google' LIMIT 1`,
      [usuarioId]
    );

    if (!conexao.rows.length) return null;

    const dadosConta = conexao.rows[0].dados_conta ?? {};
    const existente = dadosConta[campoJson];

    if (existente) {
      return existente;
    }

    const resultados = await googleAdsMutate(
      customerId, accessToken, "conversionActions",
      [
        {
          create: {
            name: `Plataforma de Leads - ${nomeEvento}`,
            type: "UPLOAD_CLICKS",
            category: "LEAD",
            status: "ENABLED",
          },
        },
      ],
      loginCustomerId
    );

    const resourceName = resultados[0]?.resourceName;
    if (!resourceName) return null;

    await client.query(
      `UPDATE plataforma_conexoes SET dados_conta = $1 WHERE id = $2`,
      [JSON.stringify({ ...dadosConta, [campoJson]: resourceName }), conexao.rows[0].id]
    );

    return resourceName;
  } catch (err) {
    console.error("ERRO obterOuCriarConversionActionGoogle:", err);
    return null;
  }
}

// Equivalente Google Ads de enviarEventoMetaConversionLeads — reporta de
// volta pro Google Ads que um lead capturado por um Lead Form virou um lead
// qualificado ou fechado, usando o gclid capturado na sincronizacao (ver
// /google/sincronizar-campanhas). Sem gclid nao ha como casar o evento com
// o clique original — leads sincronizados antes desta mudanca nao tem esse
// campo preenchido e ficam sem poder mandar o evento.
// ⚠️ ASSUMPTION: uploadClickConversions e conversionDateTime no formato
// "yyyy-MM-dd HH:mm:ss+00:00" conferidos contra a documentacao oficial da
// Google Ads API em 14/08/2026, mas ainda nao testados contra um gclid real
// — mesmo padrao de risco que as outras integracoes Google Ads desta
// plataforma tiveram no inicio (erros especificos so aparecem com trafego
// real, corrigir conforme necessario).
async function enviarEventoGoogleAdsConversionLeads(
  usuarioId: number,
  lead: any,
  eventName: "Qualified Lead" | "Closed Won"
): Promise<{ ok: boolean; erro?: string }> {

  if (!lead?.gclid) {
    return { ok: false, erro: "Lead sem gclid do Google Ads" };
  }

  const conexao = await resolverConexaoGoogleAds(usuarioId);

  if ("erro" in conexao) {
    return { ok: false, erro: conexao.erro };
  }

  try {

    const chave = eventName === "Qualified Lead" ? "qualified" : "closed";

    const conversionActionResourceName =
      await obterOuCriarConversionActionGoogle(
        usuarioId, conexao.customerId, conexao.accessToken,
        conexao.loginCustomerId, chave, eventName
      );

    if (!conversionActionResourceName) {
      return { ok: false, erro: "Não foi possível criar a ação de conversão no Google Ads" };
    }

    const conversionDateTime =
      new Date().toISOString().slice(0, 19).replace("T", " ") + "+00:00";

    const res = await fetch(
      `${GOOGLE_ADS_API}/customers/${conexao.customerId}:uploadClickConversions`,
      {
        method: "POST",
        headers: googleAdsHeaders(conexao.accessToken, conexao.loginCustomerId),
        body: JSON.stringify({
          conversions: [
            {
              gclid: lead.gclid,
              conversionAction: conversionActionResourceName,
              conversionDateTime,
            },
          ],
          partialFailure: true,
        }),
      }
    );

    const data = await res.json() as any;

    if (!res.ok) {
      const erro = data?.error?.message || "Erro ao enviar conversão para o Google Ads";
      console.error(`CONVERSION LEADS GOOGLE (${eventName}) erro:`, JSON.stringify(data));
      return { ok: false, erro };
    }

    const falhaParcial = data?.partialFailureError;

    if (falhaParcial) {
      console.error(`CONVERSION LEADS GOOGLE (${eventName}) falha parcial:`, JSON.stringify(falhaParcial));
      return { ok: false, erro: falhaParcial.message || "Google Ads rejeitou a conversão" };
    }

    return { ok: true };

  } catch (err: any) {
    console.error(`CONVERSION LEADS GOOGLE (${eventName}) excecao:`, err);
    return { ok: false, erro: err?.message || "Erro ao enviar conversão para o Google Ads" };
  }
}

async function googleAdsMutate(
  customerId: string,
  accessToken: string,
  recurso: string,
  operations: any[],
  loginCustomerId?: string | null
) {
  const res = await fetch(
    `${GOOGLE_ADS_API}/customers/${customerId}/${recurso}:mutate`,
    {
      method: "POST",
      headers: googleAdsHeaders(accessToken, loginCustomerId),
      body: JSON.stringify({ operations }),
    }
  );
  const data = await res.json() as any;
  if (!res.ok) {
    console.error(`ERRO GOOGLE ADS MUTATE (${recurso}):`, customerId, JSON.stringify(data));
    const err: any = new Error(data?.error?.message || `Erro ao gravar em ${recurso} no Google Ads`);
    // Anexa o corpo bruto do erro (com os sub-erros em error.details[].errors[]) —
    // a mensagem top-level da Google e sempre generica ("Request contains an
    // invalid argument"), quem importa esta nos sub-erros aninhados.
    err.googleAdsError = data;
    throw err;
  }
  return data.results ?? [];
}

// Varre error.details[].errors[] (formato padrao de erro da Google Ads API) procurando
// um errorCode especifico (ex: "LEAD_FORM_MISSING_AGREEMENT", "INVALID_VALUE") em
// qualquer uma das categorias de erro (assetError, fieldError, etc — o nome da
// categoria varia conforme o tipo do erro, so o valor e fixo).
function googleAdsTemErroCode(err: any, codigo: string): boolean {
  const detalhes = err?.googleAdsError?.error?.details;
  if (!Array.isArray(detalhes)) return false;
  for (const detalhe of detalhes) {
    for (const erroItem of detalhe?.errors ?? []) {
      if (Object.values(erroItem?.errorCode ?? {}).includes(codigo)) return true;
    }
  }
  return false;
}

function googleAdsCodigosErro(err: any): string[] {
  const detalhes = err?.googleAdsError?.error?.details;
  if (!Array.isArray(detalhes)) return [];
  const codigos = new Set<string>();
  for (const detalhe of detalhes) {
    for (const erroItem of detalhe?.errors ?? []) {
      for (const valor of Object.values(erroItem?.errorCode ?? {})) {
        if (typeof valor === "string" && valor) codigos.add(valor);
      }
    }
  }
  return [...codigos];
}

function googleAdsPrimeiraMensagemDetalhada(err: any): string {
  const detalhes = err?.googleAdsError?.error?.details;
  if (!Array.isArray(detalhes)) return "";
  for (const detalhe of detalhes) {
    for (const erroItem of detalhe?.errors ?? []) {
      const mensagem = textoOpcional(erroItem?.message);
      if (mensagem) return mensagem;
    }
  }
  return "";
}

function mensagemErroBusinessMessageGoogle(err: any): string {
  if (googleAdsTemErroCode(err, "CUSTOMER_NOT_ALLOWLISTED_FOR_THIS_FEATURE")) {
    return "Esta conta do Google Ads ainda não foi liberada pelo Google para usar o botão nativo de WhatsApp. O recurso está em acesso restrito (allowlist); solicite a liberação ao gerente da conta Google Ads e tente novamente.";
  }
  if (googleAdsTemErroCode(err, "CUSTOMER_NOT_VERIFIED")) {
    return "O Google Ads exige que a verificação do anunciante esteja concluída antes de usar o botão de WhatsApp. Conclua a verificação da conta e tente novamente.";
  }

  const codigos = googleAdsCodigosErro(err);
  if (codigos.some(codigo => /PHONE|WHATSAPP|MESSAGE_PROVIDER/i.test(codigo))) {
    return "O Google Ads não aceitou o número do WhatsApp conectado. Confirme se esse número está ativo no WhatsApp Business e se os dados da conta estão verificados.";
  }

  const detalhe = googleAdsPrimeiraMensagemDetalhada(err);
  return detalhe
    ? `O Google Ads não conseguiu configurar o botão de WhatsApp: ${detalhe}`
    : "O Google Ads não conseguiu configurar o botão de WhatsApp nesta conta. Revise a elegibilidade da conta e tente novamente.";
}

function numeroWhatsappGoogleComparavel(countryCode: string, phoneNumber: string): string {
  const digitos = String(phoneNumber || "").replace(/\D/g, "");
  if (String(countryCode || "").toUpperCase() === "BR" && !digitos.startsWith("55")) {
    return `55${digitos}`;
  }
  return digitos;
}

async function obterOuCriarBusinessMessageWhatsappGoogle(
  customerId: string,
  accessToken: string,
  loginCustomerId: string | null,
  numero: NumeroWhatsappGoogle,
  mensagemInicial: string
): Promise<string> {
  const mensagem = truncarSemCortarPalavra(mensagemInicial, 200);

  // Assets sao imutaveis no Google Ads. Reutiliza o mesmo recurso quando numero e
  // mensagem coincidem, evitando acumular uma copia a cada tentativa de publicacao.
  try {
    const existentes = await googleAdsQuery(
      customerId,
      accessToken,
      `SELECT asset.resource_name,
              asset.business_message_asset.message_provider,
              asset.business_message_asset.starter_message,
              asset.business_message_asset.whatsapp_info.country_code,
              asset.business_message_asset.whatsapp_info.phone_number
       FROM asset
       WHERE asset.type = 'BUSINESS_MESSAGE'`,
      loginCustomerId
    );

    for (const row of existentes as any[]) {
      const asset = row?.asset ?? {};
      const info = asset?.businessMessageAsset ?? asset?.business_message_asset ?? {};
      const whatsapp = info?.whatsappInfo ?? info?.whatsapp_info ?? {};
      const mesmoNumero = numeroWhatsappGoogleComparavel(
        whatsapp?.countryCode ?? whatsapp?.country_code,
        whatsapp?.phoneNumber ?? whatsapp?.phone_number
      ) === numero.comparavel;
      const mesmaMensagem = String(info?.starterMessage ?? info?.starter_message ?? "").trim() === mensagem;
      if (asset?.resourceName && mesmoNumero && mesmaMensagem) return asset.resourceName;
      if (asset?.resource_name && mesmoNumero && mesmaMensagem) return asset.resource_name;
    }
  } catch (err: any) {
    // Consultar assets antigos e apenas uma otimizacao. A criacao abaixo ainda
    // devolve o erro completo e elegivel para traducao caso a conta nao tenha acesso.
    console.warn("AVISO GOOGLE BUSINESS MESSAGE: não foi possível consultar assets existentes:", err?.message);
  }

  const resultados = await googleAdsMutate(
    customerId,
    accessToken,
    "assets",
    [{
      create: {
        name: `WhatsApp Plataforma de Leads - ${Date.now()}`,
        type: "BUSINESS_MESSAGE",
        businessMessageAsset: {
          messageProvider: "WHATSAPP",
          starterMessage: mensagem,
          callToAction: {
            callToActionSelection: "CONTACT_US",
            callToActionDescription: "Converse com nossa equipe",
          },
          whatsappInfo: {
            countryCode: numero.countryCode,
            phoneNumber: numero.phoneNumber,
          },
        },
      },
    }],
    loginCustomerId
  );

  const resourceName = resultados[0]?.resourceName;
  if (!resourceName) throw new Error("O Google Ads não retornou o identificador do botão de WhatsApp criado.");
  return resourceName;
}

// Varre error.details[].errors[] procurando violacoes de politica marcadas como
// "isExemptible" (ex: HEALTH_IN_PERSONALIZED_ADS — comum em nichos como planos de
// saude, ja que o texto do titulo/palavra-chave pode soar como segmentacao por
// informacao de saude sensivel mesmo sem essa intencao). Cada violacao exemptivel
// pode ser "perdoada" numa nova tentativa anexando a mesma policyViolationKey
// (policyName + violatingText) na operacao correspondente, via campo
// exemptPolicyViolationKeys — padrao oficial documentado pela Google Ads API.
function googleAdsExtrairExencoesPolitica(
  err: any
): { operationIndex: number; key: { policyName: string; violatingText: string } }[] {
  const detalhes = err?.googleAdsError?.error?.details;
  if (!Array.isArray(detalhes)) return [];
  const exencoes: { operationIndex: number; key: { policyName: string; violatingText: string } }[] = [];
  for (const detalhe of detalhes) {
    for (const erroItem of detalhe?.errors ?? []) {
      const violacao = erroItem?.details?.policyViolationDetails;
      if (!violacao?.isExemptible || !violacao?.key) continue;
      const operationEl = (erroItem?.location?.fieldPathElements ?? []).find(
        (el: any) => el?.fieldName === "operations"
      );
      if (typeof operationEl?.index === "number") {
        exencoes.push({ operationIndex: operationEl.index, key: violacao.key });
      }
    }
  }
  return exencoes;
}

// Cria orcamento + campanha de Pesquisa (PAUSED) + targeting geo/idioma (nao bloqueante).
// Equivalente ao /meta/campanha e /tiktok/campanha.
app.post("/google/campanha", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { usuario_id, nome, orcamento, publicacao_grupo_id, tipo_campanha } = await c.req.json();

    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);
    if (!usuarioId) return negarAcessoConta(c);

    const tipoCampanhaGoogle = String(tipo_campanha || "").toLowerCase() === "display" ? "display" : "search";

    if (!Bun.env.GOOGLE_ADS_DEVELOPER_TOKEN) {
      return c.json({ error: "Developer token do Google Ads não configurado" }, 500);
    }

    const conexao = await resolverConexaoGoogleAds(usuarioId);
    if ("erro" in conexao) {
      return c.json({ error: conexao.erro }, 400);
    }

    // A Google Ads API não permite criar campanha diretamente numa conta gerenciadora
    // (MCC) — só numa conta de cliente vinculada a ela. Sem essa checagem, a Google
    // rejeita com um erro genérico ("Request contains an invalid argument" +
    // OPERATION_NOT_PERMITTED_FOR_CONTEXT) que não explica o motivo real.
    try {
      const contaResults = await googleAdsQuery(
        conexao.customerId, conexao.accessToken,
        "SELECT customer.manager FROM customer LIMIT 1"
      );
      if ((contaResults[0] as any)?.customer?.manager) {
        return c.json({
          error: "A conta selecionada é uma conta gerenciadora (MCC) — o Google Ads não permite criar campanhas diretamente nela. Crie ou selecione uma conta de cliente (que efetivamente veicula anúncios) dentro dessa conta gerenciadora, no Google Ads Manager."
        }, 400);
      }
    } catch (errCheck: any) {
      console.warn("AVISO /google/campanha: falha ao checar se a conta é gerenciadora:", errCheck.message);
    }

    const orcamentoNumero = numeroOpcional(orcamento);
    if (!orcamentoNumero || orcamentoNumero <= 0) {
      return c.json({ error: "Orçamento diário é obrigatório para a campanha Google Ads" }, 400);
    }

    const nomeCampanha = textoOpcional(nome) || `Campanha Leads ${Date.now()}`;
    // A Google Ads API rejeita criar uma campanha ATIVA/PAUSADA com o mesmo nome de
    // outra ja existente na conta (DUPLICATE_CAMPAIGN_NAME) — confirmado em producao
    // quando o nome da campanha (vindo do campo compartilhado "Nome da campanha") se
    // repetiu entre tentativas. O nome exibido na nossa plataforma (banco) continua
    // limpo; so o nome enviado pra Google ganha um sufixo unico.
    const nomeCampanhaGoogle = `${nomeCampanha} - ${Date.now()}`;

    const budgetResults = await googleAdsMutate(conexao.customerId, conexao.accessToken, "campaignBudgets", [
      {
        create: {
          name: `Orcamento - ${nomeCampanha} - ${Date.now()}`,
          amountMicros: String(Math.round(orcamentoNumero * 1_000_000)),
          deliveryMethod: "STANDARD",
          explicitlyShared: false,
        },
      },
    ]);
    const budgetResourceName = budgetResults[0]?.resourceName;
    if (!budgetResourceName) {
      return c.json({ error: "Erro ao criar orçamento no Google Ads" }, 502);
    }

    const campaignResults = await googleAdsMutate(conexao.customerId, conexao.accessToken, "campaigns", [
      {
        create: {
          name: nomeCampanhaGoogle,
          // Campanha pode ser de Pesquisa (texto) ou Display (imagem) — controlado pelo
          // campo tipo_campanha vindo do frontend. Display com Lead Form exige a conta
          // ja ter gasto historico (>US$1.000, confirmado via
          // CUSTOMER_NOT_ALLOWLISTED_FOR_THIS_FEATURE em producao e na documentacao
          // oficial do Google) e verificacao de identidade do anunciante — por isso, em
          // Display, o Lead Form e sempre uma tentativa opcional e best-effort feita em
          // /google/anuncio (degrada graciosamente se a conta nao for elegivel), nunca
          // bloqueante como em Pesquisa. A URL de destino sempre funciona em Display,
          // sem gate nenhum.
          advertisingChannelType: tipoCampanhaGoogle === "display" ? "DISPLAY" : "SEARCH",
          status: "PAUSED",
          campaignBudget: budgetResourceName,
          manualCpc: {},
          ...(tipoCampanhaGoogle === "search" ? {
            networkSettings: {
              targetGoogleSearch: true,
              targetSearchNetwork: true,
              targetContentNetwork: false,
              targetPartnerSearchNetwork: false,
            },
          } : {}),
          // Autodeclaração exigida pela Google Ads API em toda criação de campanha
          // (EU Political Advertising Regulation) — sem isso a API rejeita com
          // FieldError.REQUIRED. Plataforma é de leads no Brasil, sem qualquer
          // publicidade política voltada à UE.
          containsEuPoliticalAdvertising: "DOES_NOT_CONTAIN_EU_POLITICAL_ADVERTISING",
        },
      },
    ]);
    const campaignResourceName = campaignResults[0]?.resourceName;
    if (!campaignResourceName) {
      return c.json({ error: "Erro ao criar campanha no Google Ads" }, 502);
    }
    const campaignId = campaignResourceName.split("/").pop();

    // ASSUMPTION: geoTargetConstants/2076 (Brasil) e languageConstants/1014 (portugues)
    // fixos no MVP, sem UI de segmentacao — nao bloqueia a criacao da campanha se falhar.
    try {
      await googleAdsMutate(conexao.customerId, conexao.accessToken, "campaignCriteria", [
        { create: { campaign: campaignResourceName, location: { geoTargetConstant: "geoTargetConstants/2076" } } },
        { create: { campaign: campaignResourceName, language: { languageConstant: "languageConstants/1014" } } },
      ]);
    } catch (err) {
      console.warn("AVISO: falha ao aplicar targeting geo/idioma na campanha Google Ads (não bloqueante):", err);
    }

    await client.query(
      `INSERT INTO campanhas (
        usuario_id, campaign_id, conta_anuncios_id, nome, status, origem,
        configuracoes_avancadas, plataforma, publicacao_grupo_id
      )
      VALUES ($1,$2,$3,$4,'PAUSED','plataforma',$5,'google',$6)`,
      [
        usuarioId,
        campaignId,
        conexao.customerId,
        nomeCampanha,
        JSON.stringify({ campaign_budget_resource_name: budgetResourceName, tipo_campanha: tipoCampanhaGoogle }),
        textoOpcional(publicacao_grupo_id) || null,
      ]
    );

    return c.json({ id: campaignId, campaign_id: campaignId });
  } catch (err: any) {
    console.error("ERRO /google/campanha:", err);
    return c.json({ error: err.message || "Erro ao criar campanha Google Ads" }, 500);
  }
});

// Cria o Grupo de Anuncios, de Pesquisa ou Display conforme tipo_campanha (equivalente
// ao /meta/adset e /tiktok/adgroup)
app.post("/google/adgroup", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { usuario_id, campaign_id, orcamento, tipo_campanha } = await c.req.json();

    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);
    if (!usuarioId) return negarAcessoConta(c);

    if (!campaign_id) {
      return c.json({ error: "campaign_id não enviado" }, 400);
    }

    const tipoCampanhaGoogle = String(tipo_campanha || "").toLowerCase() === "display" ? "display" : "search";

    const conexao = await resolverConexaoGoogleAds(usuarioId);
    if ("erro" in conexao) {
      return c.json({ error: conexao.erro }, 400);
    }

    const campaignResourceName = `customers/${conexao.customerId}/campaigns/${campaign_id}`;
    const cpcBidMicros = Math.max(
      1_000_000,
      Math.round((numeroOpcional(orcamento) || 10) * 1_000_000 * 0.1)
    );

    const adGroupResults = await googleAdsMutate(conexao.customerId, conexao.accessToken, "adGroups", [
      {
        create: {
          name: `AdGroup Leads ${Date.now()}`,
          campaign: campaignResourceName,
          type: tipoCampanhaGoogle === "display" ? "DISPLAY_STANDARD" : "SEARCH_STANDARD",
          status: "ENABLED",
          cpcBidMicros: String(cpcBidMicros),
        },
      },
    ]);
    const adGroupResourceName = adGroupResults[0]?.resourceName;
    if (!adGroupResourceName) {
      return c.json({ error: "Erro ao criar grupo de anúncios no Google Ads" }, 502);
    }

    return c.json({ id: adGroupResourceName.split("/").pop(), adgroup_id: adGroupResourceName.split("/").pop() });
  } catch (err: any) {
    console.error("ERRO /google/adgroup:", err);
    return c.json({ error: err.message || "Erro ao criar grupo de anúncios Google Ads" }, 500);
  }
});

// Lista os Lead Form assets ja existentes na conta conectada — o Google, assim como a
// TikTok, nao cria o formulario via este fluxo (schema de Lead Form da API e mais
// complexo que o da Meta); o usuario escolhe um ja criado no Google Ads Manager.
app.get("/google/formularios", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    const conexao = await resolverConexaoGoogleAds(user.id);
    if ("erro" in conexao) {
      return c.json({ formularios: [], aviso: conexao.erro });
    }

    const results = await googleAdsQuery(
      conexao.customerId, conexao.accessToken,
      `SELECT asset.resource_name, asset.lead_form_asset.business_name, asset.lead_form_asset.headline
       FROM asset WHERE asset.type = 'LEAD_FORM'`
    );

    const formularios = (results as any[]).map(r => {
      const asset = r.asset ?? {};
      const leadForm = asset.leadFormAsset ?? {};
      return {
        resource_name: asset.resourceName,
        nome: leadForm.businessName || leadForm.headline || asset.resourceName,
      };
    });

    if (!formularios.length) {
      return c.json({
        formularios: [],
        aviso: "Nenhum Lead Form encontrado. Crie um no Google Ads Manager antes de publicar."
      });
    }

    return c.json({ formularios });
  } catch (err: any) {
    console.error("ERRO /google/formularios:", err);
    return c.json({
      formularios: [],
      aviso: "Não foi possível listar formulários existentes. Informe o resource name manualmente."
    });
  }
});

// Cria um Lead Form asset novo (equivalente ao /meta/formulario) — diferente da Meta,
// o schema do Google exige alguns campos fixos (política de privacidade, CTA, textos
// pós-envio); usamos o mesmo padrão de placeholder já usado nas rotas Meta quando o
// campo real não existe na UI (ex: privacidade_url cai em "https://google.com").
app.post("/google/formulario", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const {
      usuario_id, nome_negocio, headline, descricao,
      perguntas, obrigado_titulo, obrigado_texto, url_destino, privacidade_url
    } = await c.req.json();

    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);
    if (!usuarioId) return negarAcessoConta(c);

    const conexao = await resolverConexaoGoogleAds(usuarioId);
    if ("erro" in conexao) {
      return c.json({ error: conexao.erro }, 400);
    }

    const perguntasCustom = (Array.isArray(perguntas) ? perguntas : [])
      .map(textoOpcional)
      .filter(Boolean)
      .slice(0, 5);

    // Limites de caracteres do Google Ads para LeadFormAsset (confirmado via
    // documentacao oficial: nome do negocio 25, titulo 30, descricao 200 —
    // postSubmitHeadline/Description seguem o mesmo padrao dos campos irmaos
    // headline/description). Sem truncar, texto vindo da IA ou do usuario que
    // passe do limite derruba a criacao inteira com erro TOO_LONG.
    const leadFormAsset: any = {
      businessName: truncarSemCortarPalavra(textoOpcional(nome_negocio) || "Plataforma de Leads", 25),
      callToActionType: "GET_INFO",
      callToActionDescription: "Fale com um especialista",
      headline: truncarSemCortarPalavra(textoOpcional(headline) || "Receba mais informações", 30),
      description: truncarSemCortarPalavra(textoOpcional(descricao) || "Deixe seus dados e entraremos em contato.", 200),
      privacyPolicyUrl: urlOpcional(privacidade_url, "https://google.com"),
      postSubmitHeadline: truncarSemCortarPalavra(textoOpcional(obrigado_titulo) || "Obrigado!", 30),
      postSubmitDescription: truncarSemCortarPalavra(textoOpcional(obrigado_texto) || "Recebemos seus dados. Em breve entraremos em contato.", 200),
      postSubmitCallToActionType: "VISIT_SITE",
      fields: [
        { inputType: "FULL_NAME" },
        { inputType: "PHONE_NUMBER" },
        { inputType: "EMAIL" },
      ],
    };

    if (perguntasCustom.length) {
      leadFormAsset.customQuestionFields = perguntasCustom.map(pergunta => ({
        customQuestionText: pergunta,
      }));
    }

    const criarAsset = () =>
      googleAdsMutate(conexao.customerId, conexao.accessToken, "assets", [
        {
          create: {
            name: `Lead Form ${Date.now()}`,
            finalUrls: [urlOpcional(url_destino, "https://plataformadeleads.com.br")],
            leadFormAsset,
          },
        },
      ]);

    const mensagemFaltaTermos =
      "A conta do Google Ads ainda não aceitou os Termos de Serviço de Lead Forms — isso só pode ser feito uma vez, manualmente, na interface do Google Ads (não tem como aceitar pela API). No Google Ads, vá em Campanhas → Ativos → clique em \"+\" → \"Formulário de lead\", preencha um formulário de exemplo e aceite os Termos de Serviço na última etapa antes de salvar. Depois disso, tente publicar a campanha novamente.";

    let assetResults;
    try {
      assetResults = await criarAsset();
    } catch (err: any) {
      if (googleAdsTemErroCode(err, "LEAD_FORM_MISSING_AGREEMENT")) {
        return c.json({ error: mensagemFaltaTermos }, 400);
      }

      // Perguntas customizadas via API são um recurso instável na Google Ads API (a
      // própria Google já confirmou casos de INVALID_VALUE sem causa determinística).
      // Em vez de bloquear o formulário inteiro por causa delas, tenta de novo só com
      // os campos fixos (nome/telefone/email), que não passam por aprovação nenhuma.
      if (leadFormAsset.customQuestionFields && googleAdsTemErroCode(err, "INVALID_VALUE")) {
        console.warn("GOOGLE FORMULARIO: perguntas customizadas rejeitadas, tentando sem elas...");
        delete leadFormAsset.customQuestionFields;
        try {
          assetResults = await criarAsset();
        } catch (err2: any) {
          if (googleAdsTemErroCode(err2, "LEAD_FORM_MISSING_AGREEMENT")) {
            return c.json({ error: mensagemFaltaTermos }, 400);
          }
          throw err2;
        }
      } else {
        throw err;
      }
    }

    const resourceName = assetResults[0]?.resourceName;
    if (!resourceName) {
      return c.json({ error: "Erro ao criar formulário no Google Ads" }, 502);
    }

    return c.json({ resource_name: resourceName });
  } catch (err: any) {
    console.error("ERRO /google/formulario:", err);
    return c.json({ error: err.message || "Erro ao criar formulário no Google Ads" }, 500);
  }
});

// Upload de imagem como Asset (equivalente ao /meta/upload-imagem e /tiktok/upload-imagem) —
// cada imagem do Responsive Display Ad (paisagem 1.91:1 e quadrada 1:1) precisa de um
// Asset proprio no Google Ads, referenciado depois em /google/anuncio. Pedir pro usuario
// subir imagens ja exatamente nessas proporcoes nao e realista, entao cortamos server-side
// pra sempre gerar o formato certo, seja qual for a imagem/proporcao original. position:
// "attention" usa deteccao de saliencia do sharp (bordas/contraste/rostos) pra centralizar
// o corte na parte mais relevante da imagem em vez de cortar no meio cego.
const DIMENSOES_GOOGLE_DISPLAY = {
  paisagem: { width: 1200, height: 628 },
  quadrada: { width: 1200, height: 1200 },
} as const;

async function cortarImagemGoogleDisplay(bytes: ArrayBuffer, tipo: string) {
  const dimensoes =
    DIMENSOES_GOOGLE_DISPLAY[tipo as keyof typeof DIMENSOES_GOOGLE_DISPLAY] ||
    DIMENSOES_GOOGLE_DISPLAY.paisagem;

  const buffer = await sharp(Buffer.from(bytes))
    .resize(dimensoes.width, dimensoes.height, { fit: "cover", position: "attention" })
    .jpeg({ quality: 88 })
    .toBuffer();

  return buffer;
}

app.post("/google/upload-imagem", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const body = await c.req.formData();

    const imagem = body.get("imagem") as File;
    const usuario_id = body.get("usuario_id");
    const tipo = String(body.get("tipo") || "paisagem");

    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);
    if (!usuarioId) return negarAcessoConta(c);
    if (!imagem) return c.json({ error: "Imagem não enviada" }, 400);

    const conexao = await resolverConexaoGoogleAds(usuarioId);
    if ("erro" in conexao) {
      return c.json({ error: conexao.erro }, 400);
    }

    const bytesOriginais = await imagem.arrayBuffer();
    const bytesCortados = await cortarImagemGoogleDisplay(bytesOriginais, tipo);
    const base64 = bytesCortados.toString("base64");
    const mimeType = "IMAGE_JPEG";

    const assetResults = await googleAdsMutate(conexao.customerId, conexao.accessToken, "assets", [
      {
        create: {
          name: `Imagem ${tipo} - ${Date.now()}`,
          type: "IMAGE",
          imageAsset: { data: base64, mimeType },
        },
      },
    ]);
    const resourceName = assetResults[0]?.resourceName;
    if (!resourceName) {
      return c.json({ error: "Erro ao enviar imagem para o Google Ads" }, 502);
    }

    return c.json({ resource_name: resourceName });
  } catch (err: any) {
    console.error("ERRO /google/upload-imagem:", err);
    return c.json({ error: err.message || "Erro ao enviar imagem para o Google Ads" }, 500);
  }
});

async function salvarEstruturaNichoCampanhaGoogle(
  campanhaId: number,
  nichoSlug: string,
  dados: Record<string, any>
) {
  if (nichoSlug === "imoveis") {
    await client.query(
      `INSERT INTO campanhas_imoveis
         (campanha_id, tipo_imovel, finalidade, valor_min, valor_max, regiao)
       VALUES ($1,$2,$3,$4,$5,$6)
       ON CONFLICT (campanha_id) DO UPDATE SET
         tipo_imovel = EXCLUDED.tipo_imovel,
         finalidade = EXCLUDED.finalidade,
         valor_min = EXCLUDED.valor_min,
         valor_max = EXCLUDED.valor_max,
         regiao = EXCLUDED.regiao`,
      [campanhaId, dados.tipo_imovel ?? null, dados.finalidade ?? null,
       numeroOpcional(dados.valor_min), numeroOpcional(dados.valor_max),
       textoOpcional(dados.regiao) || null]
    );
  } else if (nichoSlug === "saude") {
    await client.query(
      `INSERT INTO campanhas_saude
         (campanha_id, operadora, tipo_plano, faixa_etaria_min,
          faixa_etaria_max, cobertura, acomodacao)
       VALUES ($1,$2,$3,$4,$5,$6,$7)
       ON CONFLICT (campanha_id) DO UPDATE SET
         operadora = EXCLUDED.operadora,
         tipo_plano = EXCLUDED.tipo_plano,
         faixa_etaria_min = EXCLUDED.faixa_etaria_min,
         faixa_etaria_max = EXCLUDED.faixa_etaria_max,
         cobertura = EXCLUDED.cobertura,
         acomodacao = EXCLUDED.acomodacao`,
      [campanhaId, textoOpcional(dados.operadora) || null,
       textoOpcional(dados.tipo_plano) || null,
       numeroOpcional(dados.faixa_etaria_min), numeroOpcional(dados.faixa_etaria_max),
       textoOpcional(dados.cobertura) || null, textoOpcional(dados.acomodacao) || null]
    );
  } else if (nichoSlug === "suplementos") {
    await client.query(
      `INSERT INTO campanhas_suplementos
         (campanha_id, produto, objetivo, marca, publico_alvo)
       VALUES ($1,$2,$3,$4,$5)
       ON CONFLICT (campanha_id) DO UPDATE SET
         produto = EXCLUDED.produto,
         objetivo = EXCLUDED.objetivo,
         marca = EXCLUDED.marca,
         publico_alvo = EXCLUDED.publico_alvo`,
      [campanhaId, textoOpcional(dados.produto) || null,
       textoOpcional(dados.objetivo) || null, textoOpcional(dados.marca) || null,
       textoOpcional(dados.publico_alvo) || null]
    );
  } else if (nichoSlug === "higienizacao") {
    await client.query(
      `INSERT INTO campanhas_higienizacao
         (campanha_id, tipo_servico, frequencia, area_atendida, publico_alvo)
       VALUES ($1,$2,$3,$4,$5)
       ON CONFLICT (campanha_id) DO UPDATE SET
         tipo_servico = EXCLUDED.tipo_servico,
         frequencia = EXCLUDED.frequencia,
         area_atendida = EXCLUDED.area_atendida,
         publico_alvo = EXCLUDED.publico_alvo`,
      [campanhaId, textoOpcional(dados.tipo_servico) || null,
       textoOpcional(dados.frequencia) || null, textoOpcional(dados.area_atendida) || null,
       textoOpcional(dados.publico_alvo) || null]
    );
  } else if (nichoSlug === "telecom") {
    await client.query(
      `INSERT INTO campanhas_telecom
         (campanha_id, tipo_servico, porte_empresa, situacao_atual, area_atendida)
       VALUES ($1,$2,$3,$4,$5)
       ON CONFLICT (campanha_id) DO UPDATE SET
         tipo_servico = EXCLUDED.tipo_servico,
         porte_empresa = EXCLUDED.porte_empresa,
         situacao_atual = EXCLUDED.situacao_atual,
         area_atendida = EXCLUDED.area_atendida`,
      [campanhaId, textoOpcional(dados.tipo_servico) || null,
       textoOpcional(dados.porte_empresa) || null,
       textoOpcional(dados.situacao_atual) || null,
       textoOpcional(dados.area_atendida) || null]
    );
  }
}

// Cria o Responsive Search Ad (texto, sem imagem) + palavras-chave e vincula o Lead
// Form escolhido a campanha (equivalente ao /meta/anuncio e /tiktok/anuncio) — aqui a
// linha de campanhas recebe adset_id/ad_id/form_id, mesmo padrao das outras plataformas.
app.post("/google/anuncio", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const {
      usuario_id, campaign_id, adgroup_id, form_id,
      titulos, descricoes, nome_anunciante, url_destino,
      daily_budget, configuracoes_avancadas,
      tipo_campanha, titulo_longo, destino, mensagem_whatsapp,
      imagem_paisagem_asset, imagem_quadrada_asset
    } = await c.req.json();

    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);
    if (!usuarioId) return negarAcessoConta(c);

    const nichoIdInformado = Number(configuracoes_avancadas?.nicho_id);
    let nichoCampanhaGoogle: { id: number; slug: string } | null = null;
    if (Number.isInteger(nichoIdInformado) && nichoIdInformado > 0) {
      const nichoPermitido = await client.query(
        `SELECT n.id, n.slug
         FROM usuario_nichos un
         INNER JOIN nichos n ON n.id = un.nicho_id
         WHERE un.usuario_id = $1 AND n.id = $2
         LIMIT 1`,
        [usuarioId, nichoIdInformado]
      );
      if (!nichoPermitido.rows.length) {
        return c.json({ error: "O nicho selecionado não está habilitado para este usuário" }, 403);
      }
      nichoCampanhaGoogle = nichoPermitido.rows[0];
    }

    const tipoCampanha = String(tipo_campanha || "").toLowerCase() === "display" ? "display" : "search";
    const destinoInformado = String(destino || "").toLowerCase();
    const destinoGoogle = ["lead_ads", "site", "whatsapp"].includes(destinoInformado)
      ? destinoInformado
      : (form_id ? "lead_ads" : "site");
    const mensagemWhatsapp = textoOpcional(mensagem_whatsapp);

    if (!campaign_id) return c.json({ error: "campaign_id não enviado" }, 400);
    if (!adgroup_id) return c.json({ error: "adgroup_id não enviado" }, 400);
    if (destinoGoogle === "lead_ads" && !form_id) {
      return c.json({ error: "Selecione um Lead Form antes de publicar" }, 400);
    }
    if (destinoGoogle === "whatsapp" && tipoCampanha !== "search") {
      return c.json({ error: "O destino WhatsApp está disponível somente em campanhas de Pesquisa do Google Ads" }, 400);
    }
    if (destinoGoogle === "whatsapp" && !mensagemWhatsapp) {
      return c.json({ error: "Informe a mensagem inicial do WhatsApp" }, 400);
    }

    const listaTitulos = (Array.isArray(titulos) ? titulos : []).map(textoOpcional).filter(Boolean);
    const listaDescricoes = (Array.isArray(descricoes) ? descricoes : []).map(textoOpcional).filter(Boolean);
    const nomeAnunciante = textoOpcional(nome_anunciante);
    const url = textoOpcional(url_destino) || "https://plataformadeleads.com.br";
    const tituloLongo = textoOpcional(titulo_longo);
    const imagemPaisagem = textoOpcional(imagem_paisagem_asset);
    const imagemQuadrada = textoOpcional(imagem_quadrada_asset);

    if (tipoCampanha === "search") {
      // O Responsive Search Ad exige no minimo 3 titulos e 2 descricoes (regra fixa da
      // Google Ads API) — sem esse minimo a criacao do anuncio e rejeitada.
      if (listaTitulos.length < 3) return c.json({ error: "Informe ao menos 3 títulos para o anúncio Google" }, 400);
      if (listaDescricoes.length < 2) return c.json({ error: "Informe ao menos 2 descrições para o anúncio Google" }, 400);
    } else {
      // Responsive Display Ad exige no minimo 1 titulo, 1 titulo longo, 1 descricao,
      // e as duas imagens (paisagem 1.91:1 e quadrada 1:1) ja enviadas via
      // /google/upload-imagem (ver responsiveDisplayAd abaixo).
      if (listaTitulos.length < 1) return c.json({ error: "Informe ao menos 1 título para o anúncio de Display" }, 400);
      if (!tituloLongo) return c.json({ error: "Informe o título longo para o anúncio de Display" }, 400);
      if (listaDescricoes.length < 1) return c.json({ error: "Informe ao menos 1 descrição para o anúncio de Display" }, 400);
      if (!imagemPaisagem || !imagemQuadrada) {
        return c.json({ error: "Envie a imagem do anúncio de Display antes de publicar" }, 400);
      }
    }

    const conexao = await resolverConexaoGoogleAds(usuarioId);
    if ("erro" in conexao) {
      return c.json({ error: conexao.erro }, 400);
    }

    const campaignResourceName = `customers/${conexao.customerId}/campaigns/${campaign_id}`;
    const adGroupResourceName = `customers/${conexao.customerId}/adGroups/${adgroup_id}`;
    let businessMessageAssetResourceName: string | null = null;

    if (destinoGoogle === "whatsapp") {
      const numeroWhatsapp = await resolverNumeroWhatsappGoogle(usuarioId);
      if ("erro" in numeroWhatsapp) {
        return c.json({ error: numeroWhatsapp.erro }, 400);
      }
      try {
        businessMessageAssetResourceName = await obterOuCriarBusinessMessageWhatsappGoogle(
          conexao.customerId,
          conexao.accessToken,
          conexao.loginCustomerId,
          numeroWhatsapp,
          mensagemWhatsapp
        );
      } catch (errBusinessMessage: any) {
        console.error("ERRO /google/anuncio (Business Message WhatsApp):", errBusinessMessage);
        return c.json({ error: mensagemErroBusinessMessageGoogle(errBusinessMessage) }, 400);
      }
    }

    const adCreate: any = tipoCampanha === "search"
      ? {
          finalUrls: [url],
          responsiveSearchAd: {
            // Trunca no limite real da Google (30/90 chars) antes de enviar —
            // reforço de segurança independente da validação do frontend
            // (se ela for contornada, a Google rejeitaria com TOO_LONG em
            // vez de simplesmente aceitar um texto cortado sem querer).
            headlines: listaTitulos.slice(0, 15).map(text => ({ text: truncarSemCortarPalavra(text, 30) })),
            descriptions: listaDescricoes.slice(0, 4).map(text => ({ text: truncarSemCortarPalavra(text, 90) })),
          },
        }
      : {
          finalUrls: [url],
          responsiveDisplayAd: {
            marketingImages: [{ asset: imagemPaisagem }],
            squareMarketingImages: [{ asset: imagemQuadrada }],
            headlines: listaTitulos.slice(0, 5).map(text => ({ text: truncarSemCortarPalavra(text, 30) })),
            longHeadline: { text: truncarSemCortarPalavra(tituloLongo, 90) },
            descriptions: listaDescricoes.slice(0, 5).map(text => ({ text: truncarSemCortarPalavra(text, 90) })),
            ...(nomeAnunciante ? { businessName: truncarSemCortarPalavra(nomeAnunciante, 25) } : {}),
          },
        };

    const adResults = await googleAdsMutate(conexao.customerId, conexao.accessToken, "adGroupAds", [
      { create: { adGroup: adGroupResourceName, status: "PAUSED", ad: adCreate } },
    ]);

    const adResourceName = adResults[0]?.resourceName;
    if (!adResourceName) {
      return c.json({ error: "Erro ao criar anúncio no Google Ads" }, 502);
    }
    // adGroupAds usa chave composta "adGroupId~adId" no resourceName.
    const adId = adResourceName.includes("~")
      ? adResourceName.split("~")[1]
      : adResourceName.split("/").pop();

    if (tipoCampanha === "search") {
      // Campanha de Pesquisa exige palavras-chave pra veicular (sem elas o anuncio nunca
      // aparece) — reaproveita os proprios titulos do anuncio como palavras-chave em
      // correspondencia ampla, ja que sao textos curtos e relevantes ao nicho gerados
      // pela IA/usuario, sem precisar de um campo novo so pra isso. Sanitiza pontuacao
      // de chamada (!, ?, etc — valida num titulo de anuncio, invalida numa keyword).
      // Display nao usa palavras-chave (segmentacao e por audiencia/publico, nao existe
      // esse conceito no formulario atual, entao esta etapa e pulada inteira).
      const keywordOps: any[] = listaTitulos
        .map(sanitizarPalavraChaveGoogle)
        .filter(Boolean)
        .slice(0, 10)
        .map(texto => ({
          create: {
            adGroup: adGroupResourceName,
            status: "ENABLED",
            keyword: { text: texto, matchType: "BROAD" },
          },
        }));

      try {
        await googleAdsMutate(conexao.customerId, conexao.accessToken, "adGroupCriteria", keywordOps);
      } catch (err: any) {
        // Nichos sensiveis (saude, financas etc.) fazem o texto do titulo/palavra-chave
        // esbarrar em politicas de "publicidade personalizada" mesmo sem intencao de
        // segmentar por essa categoria — quando a Google marca a violacao como
        // "isExemptible", da pra pedir isencao reenviando a mesma policyViolationKey.
        const exencoes = googleAdsExtrairExencoesPolitica(err);
        if (!exencoes.length) throw err;

        for (const { operationIndex, key } of exencoes) {
          const operacao = keywordOps[operationIndex];
          if (!operacao) continue;
          operacao.exemptPolicyViolationKeys = [
            ...(operacao.exemptPolicyViolationKeys || []),
            key,
          ];
        }

        await googleAdsMutate(conexao.customerId, conexao.accessToken, "adGroupCriteria", keywordOps);
      }
    }

    const formIdFinal = destinoGoogle === "lead_ads" ? textoOpcional(form_id) : "";

    if (destinoGoogle === "lead_ads") {
      await googleAdsMutate(conexao.customerId, conexao.accessToken, "campaignAssets", [
        { create: { campaign: campaignResourceName, asset: formIdFinal, fieldType: "LEAD_FORM" } },
      ], conexao.loginCustomerId);
    }

    if (destinoGoogle === "whatsapp" && businessMessageAssetResourceName) {
      try {
        await googleAdsMutate(conexao.customerId, conexao.accessToken, "campaignAssets", [
          {
            create: {
              campaign: campaignResourceName,
              asset: businessMessageAssetResourceName,
              fieldType: "BUSINESS_MESSAGE",
              status: "ENABLED",
            },
          },
        ], conexao.loginCustomerId);
      } catch (errBusinessMessage: any) {
        console.error("ERRO /google/anuncio (vínculo Business Message WhatsApp):", errBusinessMessage);
        return c.json({ error: mensagemErroBusinessMessageGoogle(errBusinessMessage) }, 400);
      }
    }

    const configuracoesPersistidas = {
      ...(configuracoes_avancadas || {}),
      plataformas: ["google"],
      tipo_campanha: tipoCampanha,
      titulos: listaTitulos,
      descricoes: listaDescricoes,
      nome_anunciante: nomeAnunciante,
      url_destino: url,
      destino: destinoGoogle,
      ...(destinoGoogle === "whatsapp" ? {
        mensagem_whatsapp: mensagemWhatsapp,
        business_message_asset: businessMessageAssetResourceName,
      } : {}),
      ...(tipoCampanha === "display" ? { titulo_longo: tituloLongo } : {}),
    };

    const campanhaAtualizada = await client.query(
      `UPDATE campanhas
       SET adset_id = $1,
           ad_id = $2,
           form_id = $3,
           daily_budget = $4,
           nicho_id = COALESCE($5, nicho_id),
           configuracoes_avancadas = COALESCE(configuracoes_avancadas, '{}'::jsonb) || $6::jsonb,
           atualizado_em = NOW()
       WHERE campaign_id = $7 AND usuario_id = $8 AND plataforma = 'google'
       RETURNING id`,
      [
        String(adgroup_id),
        String(adId),
        formIdFinal || null,
        numeroOpcional(daily_budget),
        nichoCampanhaGoogle?.id ?? null,
        JSON.stringify(configuracoesPersistidas),
        String(campaign_id),
        usuarioId
      ]
    );

    if (campanhaAtualizada.rows[0]?.id && nichoCampanhaGoogle) {
      await salvarEstruturaNichoCampanhaGoogle(
        Number(campanhaAtualizada.rows[0].id),
        nichoCampanhaGoogle.slug,
        configuracoesPersistidas
      );
    }

    return c.json({
      id: String(adId),
      ad_id: String(adId),
      ...(businessMessageAssetResourceName ? { business_message_asset: businessMessageAssetResourceName } : {})
    });
  } catch (err: any) {
    console.error("ERRO /google/anuncio:", err);
    return c.json({ error: err.message || "Erro ao criar anúncio Google Ads" }, 500);
  }
});

// Exclui (soft-delete) uma campanha Google Ads criada pela plataforma via operacao
// "remove" no mutate — a Google Ads API resulta no mesmo status=REMOVED internamente,
// mas nao aceita mais chegar la via update de status (mesma ideia do /tiktok/excluir-campanha,
// so que a forma de acionar difere entre as duas APIs).
app.post("/google/excluir-campanha", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { campaign_id } = await c.req.json();

    if (!campaign_id) {
      return c.json({ error: "campaign_id obrigatorio" }, 400);
    }

    const campanha = await client.query(
      `SELECT id FROM campanhas
       WHERE campaign_id = $1 AND usuario_id = $2 AND plataforma = 'google'
       LIMIT 1`,
      [campaign_id, user.id]
    );

    if (!campanha.rows.length) {
      return c.json({ error: "Apenas o dono da campanha pode excluí-la" }, 403);
    }

    const conexao = await resolverConexaoGoogleAds(user.id);

    if (!("erro" in conexao)) {
      const campaignResourceName = `customers/${conexao.customerId}/campaigns/${campaign_id}`;
      try {
        // A API do Google Ads nao aceita mais setar status:"REMOVED" via update
        // ("Enum value 'REMOVED' cannot be used", confirmado em producao) — o jeito
        // correto de excluir um recurso via mutate e a operacao "remove", que leva
        // so o resourceName (sem updateMask).
        await googleAdsMutate(conexao.customerId, conexao.accessToken, "campaigns", [
          { remove: campaignResourceName },
        ]);
      } catch (err: any) {
        // Tolera campanha ja removida/inexistente no Google Ads — mesmo espirito do Meta/TikTok:
        // nao trava o usuario por causa de um objeto que ja sumiu do lado de la.
        const msg = String(err?.message || "").toLowerCase();
        const naoPertenceMaisGoogle =
          msg.includes("not found") ||
          msg.includes("does not exist") ||
          msg.includes("invalid resource") ||
          msg.includes("resource was not found");

        if (!naoPertenceMaisGoogle) {
          return c.json({ error: err.message || "Erro ao excluir no Google Ads" }, 400);
        }
        console.log("EXCLUIR GOOGLE: campanha não encontrada no Google Ads, removendo localmente:", campaign_id);
      }
    }

    await client.query(
      `UPDATE campanhas SET status = 'DELETED', atualizado_em = NOW() WHERE id = $1`,
      [campanha.rows[0].id]
    );

    return c.json({ sucesso: true });
  } catch (err: any) {
    console.error("ERRO /google/excluir-campanha:", err);
    return c.json({ error: "Erro ao excluir campanha" }, 500);
  }
});

// Consulta o que já existe no Google Ads para uma campanha (grupo de anúncios, anúncio,
// palavras-chave, orçamento e formulário de lead vinculado) — usado antes de completar a
// publicação de campanhas que chegaram por sincronização externa (ex: "AgenteSmart"), que
// não têm nenhuma configuração salva localmente (configuracoes_avancadas é NULL). Só
// consulta, nunca cria nem altera nada no Google Ads.
// ASSUMPTION: assume no máximo 1 grupo de anúncios não removido por campanha — é o que o
// próprio /google/adgroup sempre produz e o que se espera de campanhas simples de Pesquisa.
app.get("/google/campanha-status/:campaign_id", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const campaignIdParam = c.req.param("campaign_id");
    const campaignId = Number(campaignIdParam);

    if (!Number.isFinite(campaignId) || campaignId <= 0) {
      return c.json({ error: "campaign_id inválido" }, 400);
    }

    const campanhaBanco = await client.query(
      `SELECT id FROM campanhas
       WHERE campaign_id = $1 AND usuario_id = $2 AND plataforma = 'google'
       LIMIT 1`,
      [String(campaignId), user.id]
    );
    if (!campanhaBanco.rows.length) {
      return c.json({ error: "Campanha não disponível para este usuário" }, 404);
    }

    const conexao = await resolverConexaoGoogleAds(user.id);
    if ("erro" in conexao) {
      return c.json({ error: conexao.erro }, 400);
    }

    let campanhaGoogleResults: any[];
    try {
      campanhaGoogleResults = await googleAdsQuery(
        conexao.customerId, conexao.accessToken,
        `SELECT campaign.id, campaign.status, campaign_budget.amount_micros
         FROM campaign
         WHERE campaign.id = ${campaignId}`,
        conexao.loginCustomerId
      );
    } catch (errCampanha: any) {
      console.error("ERRO /google/campanha-status (campanha):", errCampanha.message);
      return c.json({ error: "Não foi possível consultar esta campanha no Google Ads" }, 502);
    }

    if (!campanhaGoogleResults.length) {
      return c.json({
        error: "Esta campanha não existe mais nesta conta do Google Ads conectada. Sincronize novamente para atualizar sua lista de campanhas."
      }, 404);
    }

    const campanhaGoogle = (campanhaGoogleResults[0] as any).campaign;
    if (String(campanhaGoogle?.status).toUpperCase() === "REMOVED") {
      return c.json({
        error: "Esta campanha foi removida no Google Ads. Sincronize novamente para atualizar sua lista de campanhas."
      }, 404);
    }
    const orcamentoMicros = Number((campanhaGoogleResults[0] as any).campaignBudget?.amountMicros ?? 0) || null;

    // Grupo de anúncios já existente (se houver, é sempre reaproveitado — nunca criamos
    // um segundo grupo na mesma campanha).
    let adGroup: any = null;
    try {
      const adGroupResults = await googleAdsQuery(
        conexao.customerId, conexao.accessToken,
        `SELECT ad_group.id, ad_group.name, ad_group.status
         FROM ad_group
         WHERE campaign.id = ${campaignId} AND ad_group.status != 'REMOVED'
         LIMIT 1`,
        conexao.loginCustomerId
      );
      adGroup = (adGroupResults[0] as any)?.adGroup ?? null;
    } catch (errAdGroup: any) {
      console.warn("AVISO /google/campanha-status (ad_group):", errAdGroup.message);
    }

    let temAnuncio = false;
    let temPalavrasChave = false;
    if (adGroup?.id) {
      try {
        const adResults = await googleAdsQuery(
          conexao.customerId, conexao.accessToken,
          `SELECT ad_group_ad.ad.id, ad_group_ad.status
           FROM ad_group_ad
           WHERE ad_group.id = ${adGroup.id} AND ad_group_ad.status != 'REMOVED'
           LIMIT 1`,
          conexao.loginCustomerId
        );
        temAnuncio = adResults.length > 0;
      } catch (errAd: any) {
        console.warn("AVISO /google/campanha-status (ad_group_ad):", errAd.message);
      }

      try {
        const keywordResults = await googleAdsQuery(
          conexao.customerId, conexao.accessToken,
          `SELECT ad_group_criterion.criterion_id
           FROM ad_group_criterion
           WHERE ad_group.id = ${adGroup.id}
             AND ad_group_criterion.type = 'KEYWORD'
             AND ad_group_criterion.status != 'REMOVED'
           LIMIT 1`,
          conexao.loginCustomerId
        );
        temPalavrasChave = keywordResults.length > 0;
      } catch (errKeyword: any) {
        console.warn("AVISO /google/campanha-status (ad_group_criterion):", errKeyword.message);
      }
    }

    let formResourceName: string | null = null;
    try {
      const formResults = await googleAdsQuery(
        conexao.customerId, conexao.accessToken,
        `SELECT campaign_asset.asset
         FROM campaign_asset
         WHERE campaign.id = ${campaignId}
           AND campaign_asset.field_type = 'LEAD_FORM'
           AND campaign_asset.status != 'REMOVED'
         LIMIT 1`,
        conexao.loginCustomerId
      );
      formResourceName = (formResults[0] as any)?.campaignAsset?.asset ?? null;
    } catch (errForm: any) {
      console.warn("AVISO /google/campanha-status (campaign_asset):", errForm.message);
    }

    return c.json({
      tem_grupo_anuncios: Boolean(adGroup?.id),
      adgroup_id: adGroup?.id ? String(adGroup.id) : null,
      adgroup_nome: adGroup?.name ?? null,
      tem_anuncio: temAnuncio,
      tem_palavras_chave: temPalavrasChave,
      orcamento_diario_atual: orcamentoMicros ? orcamentoMicros / 1_000_000 : null,
      tem_formulario_vinculado: Boolean(formResourceName),
      form_resource_name: formResourceName,
    });
  } catch (err: any) {
    console.error("ERRO /google/campanha-status:", err);
    return c.json({ error: err.message || "Erro ao consultar status da campanha no Google Ads" }, 500);
  }
});

// Remove um Grupo de Anúncios específico (limpeza pontual quando um passo posterior desta
// mesma tentativa de completar uma campanha existente falha) — não usar para excluir toda
// uma campanha, isso é o /google/excluir-campanha.
app.post("/google/excluir-adgroup", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { campaign_id, adgroup_id } = await c.req.json();
    if (!campaign_id || !adgroup_id) {
      return c.json({ error: "campaign_id e adgroup_id obrigatórios" }, 400);
    }

    const campanha = await client.query(
      `SELECT id FROM campanhas WHERE campaign_id = $1 AND usuario_id = $2 AND plataforma = 'google' LIMIT 1`,
      [campaign_id, user.id]
    );
    if (!campanha.rows.length) {
      return c.json({ error: "Campanha não disponível para este usuário" }, 404);
    }

    const conexao = await resolverConexaoGoogleAds(user.id);
    if ("erro" in conexao) return c.json({ error: conexao.erro }, 400);

    const adGroupResourceName = `customers/${conexao.customerId}/adGroups/${adgroup_id}`;
    try {
      await googleAdsMutate(conexao.customerId, conexao.accessToken, "adGroups", [
        { remove: adGroupResourceName },
      ]);
    } catch (err: any) {
      const msg = String(err?.message || "").toLowerCase();
      if (!msg.includes("not found") && !msg.includes("does not exist") && !msg.includes("invalid resource")) {
        return c.json({ error: err.message || "Erro ao remover grupo de anúncios" }, 400);
      }
    }

    return c.json({ sucesso: true });
  } catch (err: any) {
    console.error("ERRO /google/excluir-adgroup:", err);
    return c.json({ error: "Erro ao remover grupo de anúncios" }, 500);
  }
});

// Ativa/pausa uma campanha Google Ads (equivalente ao /meta/toggle-campanha e
// /tiktok/toggle-campanha) — campanhas de Pesquisa sao sempre criadas PAUSED pela
// API (nao ha como criar ja ENABLED), entao esta e a unica forma de comecar a
// veicular depois da criacao. A Google Ads API usa o enum ENABLED (nao ACTIVE
// como Meta/TikTok) e exige updateMask explicito em toda operacao "update".
app.post("/google/toggle-campanha", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { campaign_id, status } = await c.req.json();

    if (!campaign_id || !["ACTIVE", "PAUSED"].includes(status)) {
      return c.json({ error: "campaign_id e status (ACTIVE/PAUSED) obrigatorios" }, 400);
    }

    const campanhaBanco = await client.query(
      `SELECT id, adset_id, ad_id
       FROM campanhas
       WHERE campaign_id = $1 AND usuario_id = $2 AND plataforma = 'google'
       LIMIT 1`,
      [campaign_id, user.id]
    );

    if (!campanhaBanco.rows.length) {
      return c.json({ error: "Campanha não disponível para este usuário" }, 404);
    }

    const { adset_id, ad_id } = campanhaBanco.rows[0];

    const conexao = await resolverConexaoGoogleAds(user.id);
    if ("erro" in conexao) {
      return c.json({ error: conexao.erro }, 400);
    }

    const googleStatus = status === "ACTIVE" ? "ENABLED" : "PAUSED";
    const campaignResourceName = `customers/${conexao.customerId}/campaigns/${campaign_id}`;

    await googleAdsMutate(conexao.customerId, conexao.accessToken, "campaigns", [
      { update: { resourceName: campaignResourceName, status: googleStatus }, updateMask: "status" },
    ]);

    // Adgroup/anuncio sao best-effort (mesmo espirito do toggle da Meta): a
    // campanha ja mudou de status no Google, nao vale travar o usuario por uma
    // falha secundaria aqui — só loga.
    if (adset_id) {
      const adGroupResourceName = `customers/${conexao.customerId}/adGroups/${adset_id}`;
      await googleAdsMutate(conexao.customerId, conexao.accessToken, "adGroups", [
        { update: { resourceName: adGroupResourceName, status: googleStatus }, updateMask: "status" },
      ]).catch((err: any) => console.warn("AVISO /google/toggle-campanha (adgroup):", err.message));
    }

    if (ad_id && adset_id) {
      const adGroupAdResourceName = `customers/${conexao.customerId}/adGroupAds/${adset_id}~${ad_id}`;
      await googleAdsMutate(conexao.customerId, conexao.accessToken, "adGroupAds", [
        { update: { resourceName: adGroupAdResourceName, status: googleStatus }, updateMask: "status" },
      ]).catch((err: any) => console.warn("AVISO /google/toggle-campanha (ad):", err.message));
    }

    await client.query(
      `UPDATE campanhas SET status = $1, atualizado_em = NOW() WHERE id = $2`,
      [status, campanhaBanco.rows[0].id]
    );

    return c.json({ sucesso: true });
  } catch (err: any) {
    console.error("ERRO /google/toggle-campanha:", err);
    return c.json({ error: err.message || "Erro ao alterar campanha Google Ads" }, 500);
  }
});

/* =========================
   🎵 TIKTOK ADS
========================= */

const tiktokSyncEmAndamento = new Set<number>();

const TIKTOK_API = "https://business-api.tiktok.com/open_api/v1.3";

function tiktokHeaders(token: string) {
  return { "Access-Token": token, "Content-Type": "application/json" };
}

// Wrapper fino que já trata o envelope {code, message, data} uniforme da TikTok Business API
async function tiktokFetch(
  endpoint: string,
  token: string,
  opts: { method?: string; body?: any } = {}
): Promise<{ ok: boolean; data: any; error: string | null }> {
  try {
    const res = await fetch(`${TIKTOK_API}${endpoint}`, {
      method: opts.method || "GET",
      headers: tiktokHeaders(token),
      body: opts.body ? JSON.stringify(opts.body) : undefined
    });
    const data = await res.json() as any;
    if (data.code !== 0) {
      return { ok: false, data, error: data.message || "Erro na API do TikTok" };
    }
    return { ok: true, data, error: null };
  } catch (err: any) {
    return { ok: false, data: null, error: err?.message || "Erro de rede ao chamar a API do TikTok" };
  }
}

// Busca token + conta de anúncios (advertiser_id) + identidade já selecionadas pelo usuário
async function obterConexaoTikTok(
  usuarioId: number
): Promise<{
  token: string;
  advertiserId: string | null;
  identityId: string | null;
  identityType: string | null;
} | null> {
  const conn = await client.query(
    `SELECT access_token, dados_conta FROM plataforma_conexoes
     WHERE usuario_id = $1 AND plataforma = 'tiktok' LIMIT 1`,
    [usuarioId]
  );
  if (!conn.rows.length) return null;
  const dadosConta = conn.rows[0].dados_conta ?? {};
  return {
    token: conn.rows[0].access_token,
    advertiserId: dadosConta.advertiser_id ?? null,
    identityId: dadosConta.identity_id ?? null,
    identityType: dadosConta.identity_type ?? null
  };
}

// Mesmo formato de /google/status-completo — usado pelo card "Status TikTok"
// do Dashboard (campanhas, gasto e leads de hoje, com sincronizacao manual).
app.get("/tiktok/status-completo", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    const conexao = await obterConexaoTikTok(user.id);
    if (!conexao || !conexao.token) {
      return c.json({ conectado: false });
    }

    const [conn, campanhasCount, leadsHojeCount] = await Promise.all([
      client.query(
        `SELECT atualizado_em FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'tiktok' LIMIT 1`,
        [user.id]
      ),
      client.query(
        `SELECT COUNT(*) FILTER (WHERE UPPER(status) = 'ACTIVE') AS ativas, COUNT(*) AS total
         FROM campanhas WHERE usuario_id = $1 AND plataforma = 'tiktok'`,
        [user.id]
      ),
      client.query(
        // Mesmo cuidado de timezone dos outros /status-completo: criado_em é
        // UTC sem timezone, comparar direto com CURRENT_DATE vira "ontem" ~21h Brasília.
        `SELECT COUNT(*) AS total FROM leads
         WHERE usuario_id = $1 AND plataforma = 'tiktok'
         AND (criado_em AT TIME ZONE 'UTC' AT TIME ZONE 'America/Sao_Paulo')::date = (NOW() AT TIME ZONE 'America/Sao_Paulo')::date`,
        [user.id]
      ),
    ]);

    const base = {
      conectado: true,
      conta_selecionada: Boolean(conexao.advertiserId),
      advertiser_id: conexao.advertiserId,
      ultimo_sync: conn.rows[0]?.atualizado_em ?? null,
      campanhas_ativas: Number(campanhasCount.rows[0]?.ativas ?? 0),
      campanhas_total: Number(campanhasCount.rows[0]?.total ?? 0),
      leads_hoje: Number(leadsHojeCount.rows[0]?.total ?? 0),
    };

    if (!conexao.advertiserId) {
      return c.json({ ...base, gasto_hoje: null });
    }

    try {
      const hojeStr = new Date().toISOString().slice(0, 10);
      const relatorioHoje = await relatorioTikTokCampanhas(
        conexao.token, conexao.advertiserId, hojeStr, hojeStr, ["advertiser_id"]
      );
      const gastoHoje = relatorioHoje.reduce(
        (soma, item) => soma + Number(item.metrics?.spend || 0), 0
      );
      return c.json({ ...base, gasto_hoje: gastoHoje });
    } catch (errApi: any) {
      console.error("ERRO /tiktok/status-completo (API TikTok):", errApi.message);
      return c.json({ ...base, gasto_hoje: null, aviso: "Nao foi possivel consultar dados ao vivo do TikTok Ads" });
    }
  } catch (err: any) {
    console.error("ERRO /tiktok/status-completo:", err);
    return c.json({ error: "Erro interno" }, 500);
  }
});

function hashSha256(valor: string): string {
  return require("crypto")
    .createHash("sha256")
    .update(valor.trim().toLowerCase())
    .digest("hex");
}

// Cria (ou reaproveita) o Pixel TikTok usado como event_source_id no envio
// de eventos de qualificacao de lead — equivalente ao dataset da Meta
// (obterOuCriarDatasetMetaUsuario) e a Conversion Action do Google
// (obterOuCriarConversionActionGoogle). Guardado em
// plataforma_conexoes.dados_conta.pixel_code pra nao recriar a cada envio.
async function obterOuCriarPixelTikTok(
  usuarioId: number,
  advertiserId: string,
  token: string
): Promise<string | null> {
  try {
    const conexao = await client.query(
      `SELECT id, dados_conta FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'tiktok' LIMIT 1`,
      [usuarioId]
    );

    if (!conexao.rows.length) return null;

    const dadosConta = conexao.rows[0].dados_conta ?? {};
    const existente = dadosConta.pixel_code;

    if (existente) {
      return existente;
    }

    const criado = await tiktokFetch("/pixel/create/", token, {
      method: "POST",
      body: {
        advertiser_id: advertiserId,
        pixel_name: "Plataforma de Leads",
      },
    });

    const pixelCode = criado.data?.pixel_code || criado.data?.data?.pixel_code;

    if (!criado.ok || !pixelCode) {
      console.error("ERRO obterOuCriarPixelTikTok:", criado.error, criado.data);
      return null;
    }

    await client.query(
      `UPDATE plataforma_conexoes SET dados_conta = $1 WHERE id = $2`,
      [JSON.stringify({ ...dadosConta, pixel_code: pixelCode }), conexao.rows[0].id]
    );

    return pixelCode;
  } catch (err) {
    console.error("ERRO obterOuCriarPixelTikTok:", err);
    return null;
  }
}

// Equivalente TikTok de enviarEventoMetaConversionLeads. Diferente da Meta
// (que casa pelo lead_id nativo) e do Google (que casa pelo gclid), o lead
// sincronizado do TikTok (/lead/get/) nao expõe nenhum click id — o
// casamento aqui usa Advanced Matching por telefone/email hasheados
// (SHA-256), que e o mecanismo padrao da TikTok Events API quando nao ha
// ttclid disponivel.
// ⚠️ ASSUMPTION: endpoint /event/track/ (Events API v2), event_source "web"
// + event_source_id do Pixel, conferidos contra a documentacao oficial da
// TikTok Business API em 14/08/2026, mas ainda nao testados contra tráfego
// real — essa e a integracao com menos certeza das duas construidas agora
// (o mecanismo de conversao offline/CRM da TikTok tem mais de uma variante
// documentada); se o envio falhar consistentemente, o primeiro lugar a
// conferir e se a conta precisa de um "Offline Event Set" dedicado em vez
// de reaproveitar um Pixel comum.
async function enviarEventoTikTokConversionLeads(
  usuarioId: number,
  lead: any,
  eventName: "Qualified Lead" | "Closed Won"
): Promise<{ ok: boolean; erro?: string }> {

  if (!lead?.email && !lead?.telefone) {
    return { ok: false, erro: "Lead sem email ou telefone para casar com o TikTok" };
  }

  const conexao = await obterConexaoTikTok(usuarioId);

  if (!conexao?.advertiserId) {
    return { ok: false, erro: "TikTok não conectado" };
  }

  try {

    const pixelCode =
      await obterOuCriarPixelTikTok(usuarioId, conexao.advertiserId, conexao.token);

    if (!pixelCode) {
      return { ok: false, erro: "Não foi possível criar o pixel do TikTok" };
    }

    const eventoTikTok =
      eventName === "Qualified Lead" ? "QualifiedLead" : "ClosedWon";

    const telefoneDigitos = String(lead.telefone || "").replace(/\D/g, "");

    const resultado = await tiktokFetch("/event/track/", conexao.token, {
      method: "POST",
      body: {
        event_source: "web",
        event_source_id: pixelCode,
        data: [
          {
            event: eventoTikTok,
            event_time: Math.floor(Date.now() / 1000),
            user: {
              email: lead.email ? hashSha256(lead.email) : undefined,
              phone_number: telefoneDigitos ? hashSha256(telefoneDigitos) : undefined,
            },
          },
        ],
      },
    });

    if (!resultado.ok) {
      console.error(`CONVERSION LEADS TIKTOK (${eventName}) erro:`, resultado.error, resultado.data);
      return { ok: false, erro: resultado.error || "Erro ao enviar evento para o TikTok" };
    }

    return { ok: true };

  } catch (err: any) {
    console.error(`CONVERSION LEADS TIKTOK (${eventName}) excecao:`, err);
    return { ok: false, erro: err?.message || "Erro ao enviar evento para o TikTok" };
  }
}

// Lista contas de anunciante vinculadas ao token
app.get("/tiktok/anunciantes", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    const conn = await client.query(
      `SELECT access_token, dados_conta FROM plataforma_conexoes
       WHERE usuario_id = $1 AND plataforma = 'tiktok' LIMIT 1`,
      [user.id]
    );
    if (!conn.rows.length) return c.json({ error: "TikTok nao conectado" }, 400);

    const token = conn.rows[0].access_token;
    const dadosConta = conn.rows[0].dados_conta ?? {};
    const advertiserIds: string[] = dadosConta.advertiser_ids ?? [];

    if (!advertiserIds.length) {
      return c.json({ error: "Nenhuma conta de anunciante encontrada" }, 400);
    }

    const clientId = Bun.env.TIKTOK_ADS_APP_ID;
    const clientSecret = Bun.env.TIKTOK_ADS_APP_SECRET;
    if (!clientId || !clientSecret) return c.json({ error: "Credenciais TikTok nao configuradas" }, 500);

    const params = new URLSearchParams({
      app_id: clientId,
      secret: clientSecret,
      access_token: token,
    });
    const res = await fetch(`${TIKTOK_API}/oauth2/advertiser/get/?${params}`);
    const data = await res.json() as any;

    if (data.code !== 0) {
      console.error("ERRO TIKTOK ANUNCIANTES:", data);
      return c.json({ error: "Erro ao buscar anunciantes TikTok" }, 502);
    }

    return c.json({ anunciantes: data.data?.list ?? [] });
  } catch (err: any) {
    console.error("ERRO /tiktok/anunciantes:", err);
    return c.json({ error: "Erro interno" }, 500);
  }
});

