// Sincroniza campanhas e leads do TikTok Ads. Compartilhada entre o botão
// manual e o ciclo automático.
async function sincronizarTikTokAdsUsuario(usuarioId: number) {
    const conn = await client.query(
      `SELECT access_token, dados_conta FROM plataforma_conexoes
       WHERE usuario_id = $1 AND plataforma = 'tiktok' LIMIT 1`,
      [usuarioId]
    );
    if (!conn.rows.length) throw new Error("TikTok nao conectado");

    const token = conn.rows[0].access_token;
    const dadosConta = conn.rows[0].dados_conta ?? {};
    const advertiserId = dadosConta.advertiser_id;

    if (!advertiserId) {
      throw new Error("Selecione a conta de anunciante TikTok antes de sincronizar");
    }

    // 🔥 BUSCA CAMPANHAS
    const campanhasRes = await fetch(
      `${TIKTOK_API}/campaign/get/?advertiser_id=${advertiserId}&fields=["campaign_id","campaign_name","status","objective_type"]&page_size=100`,
      { headers: tiktokHeaders(token) }
    );
    const campanhasData = await campanhasRes.json() as any;

    if (campanhasData.code !== 0) {
      console.error("ERRO CAMPANHAS TIKTOK:", campanhasData);
      throw new Error(campanhasData.message || "Erro ao buscar campanhas TikTok");
    }

    const campanhas = campanhasData.data?.list ?? [];
    console.log("TIKTOK CAMPANHAS:", campanhas.length);

    for (const campanha of campanhas) {
      const existe = await client.query(
        `SELECT id FROM campanhas WHERE campaign_id = $1 AND usuario_id = $2`,
        [String(campanha.campaign_id), usuarioId]
      );

      if (existe.rows.length > 0) {
        await client.query(
          `UPDATE campanhas SET nome = $1, status = $2, atualizado_em = NOW()
           WHERE campaign_id = $3 AND usuario_id = $4`,
          [campanha.campaign_name, campanha.status, String(campanha.campaign_id), usuarioId]
        );
      } else {
        await client.query(
          `INSERT INTO campanhas (usuario_id, campaign_id, conta_anuncios_id, nome, status, origem, plataforma, atualizado_em)
           VALUES ($1, $2, $3, $4, $5, 'tiktok', 'tiktok', NOW())`,
          [usuarioId, String(campanha.campaign_id), String(advertiserId), campanha.campaign_name, campanha.status]
        );
      }
    }

    // 🔥 BUSCA LEADS (últimos 30 dias)
    const trintaDiasAtras = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
    const startTime = Math.floor(trintaDiasAtras.getTime() / 1000);

    let page = 1;
    let totalLeads = 0;
    let hasMore = true;

    while (hasMore) {
      const leadsRes = await fetch(
        `${TIKTOK_API}/lead/get/?advertiser_id=${advertiserId}&start_time=${startTime}&page=${page}&page_size=100`,
        { headers: tiktokHeaders(token) }
      );
      const leadsData = await leadsRes.json() as any;

      if (leadsData.code !== 0) {
        console.error("ERRO LEADS TIKTOK:", leadsData);
        break;
      }

      const leadsList = leadsData.data?.list ?? [];
      const pageInfo = leadsData.data?.page_info ?? {};
      hasMore = page < Math.ceil((pageInfo.total_number ?? 0) / 100);
      page++;

      for (const lead of leadsList) {
        const leadId = String(lead.lead_id);
        const formId = String(lead.form_id ?? "");

        const jaExiste = await client.query(
          `SELECT id FROM leads WHERE lead_id = $1 AND usuario_id = $2`,
          [leadId, usuarioId]
        );
        if (jaExiste.rows.length > 0) continue;

        // Identifica campanha pelo form_id, se disponível
        let nomeCampanha = "Campanha TikTok";
        let nichoId: number | null = null;
        if (formId) {
          const campRow = await client.query(
            `SELECT nome, nicho_id FROM campanhas WHERE form_id = $1 AND usuario_id = $2 LIMIT 1`,
            [formId, usuarioId]
          );
          if (campRow.rows.length) {
            nomeCampanha = campRow.rows[0].nome;
            nichoId = campRow.rows[0].nicho_id ?? null;
          }
        }

        let nome = "";
        let email = "";
        let telefone = "";
        const respostasQualificacao: any[] = [];

        for (const field of lead.fields ?? []) {
          const key = (field.name ?? "").toUpperCase();
          if (key === "FULL_NAME" || key === "FIRST_NAME") nome = field.value ?? "";
          else if (key === "EMAIL") email = field.value ?? "";
          else if (key === "PHONE_NUMBER") telefone = field.value ?? "";
          else respostasQualificacao.push({ pergunta: field.name, resposta: field.value ?? "" });
        }

        const criadoEm = lead.submit_time
          ? new Date(Number(lead.submit_time) * 1000).toISOString()
          : null;

        const leadInseridoTikTok = await client.query(
          `INSERT INTO leads
             (usuario_id, lead_id, nome, email, telefone, campanha, conta_anuncios_id,
              origem, plataforma, status, respostas_qualificacao, nicho_id, criado_em)
           VALUES ($1,$2,$3,$4,$5,$6,$7,'tiktok','tiktok','novo',$8,$9,COALESCE($10::timestamptz, NOW()))
           RETURNING id`,
          [
            usuarioId, leadId, nome || "Lead TikTok", email, telefone,
            nomeCampanha, String(advertiserId),
            JSON.stringify(respostasQualificacao), nichoId, criadoEm
          ]
        );

        await notificarNovoLeadWhatsApp(usuarioId, { nome, telefone, email, campanha: nomeCampanha });

        avaliarEEnviarQualificacaoLead(
          {
            id: leadInseridoTikTok.rows[0]?.id,
            lead_id: leadId,
            plataforma: "tiktok",
            status: "novo",
            email,
            telefone,
            respostas_qualificacao: respostasQualificacao
          },
          usuarioId
        ).catch(err => console.error("ERRO avaliarEEnviarQualificacaoLead (sync tiktok):", err));

        totalLeads++;
      }
    }

    await client.query(
      `UPDATE plataforma_conexoes SET atualizado_em = NOW()
       WHERE usuario_id = $1 AND plataforma = 'tiktok'`,
      [usuarioId]
    );

    return { sucesso: true, campanhas: campanhas.length, leads_novos: totalLeads };
}

app.post("/tiktok/sincronizar-campanhas", authMiddleware, async (c) => {
  const user: any = c.get("user");

  if (tiktokSyncEmAndamento.has(user.id)) {
    return c.json({ error: "Sincronizacao TikTok ja em andamento" }, 429);
  }
  tiktokSyncEmAndamento.add(user.id);

  try {
    return c.json(await sincronizarTikTokAdsUsuario(user.id));
  } catch (err: any) {
    console.error("ERRO TIKTOK SINCRONIZAR:", err);
    return c.json({ error: err?.message || "Erro ao sincronizar TikTok" }, 500);
  } finally {
    tiktokSyncEmAndamento.delete(user.id);
  }
});

// Pausa/ativa uma campanha TikTok (cascata: campanha + adgroup + anúncio)
app.post("/tiktok/toggle-campanha", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { campaign_id, status } = await c.req.json();

    if (!campaign_id || !["ACTIVE", "PAUSED"].includes(status)) {
      return c.json({ error: "campaign_id e status (ACTIVE/PAUSED) obrigatorios" }, 400);
    }

    const campanhaBanco = await client.query(
      `SELECT id, adset_id, ad_id
       FROM campanhas
       WHERE campaign_id = $1 AND usuario_id = $2 AND plataforma = 'tiktok'
       LIMIT 1`,
      [campaign_id, user.id]
    );

    if (!campanhaBanco.rows.length) {
      return c.json({ error: "Campanha não disponível para este usuário" }, 404);
    }

    const { adset_id, ad_id } = campanhaBanco.rows[0];

    const conexao = await obterConexaoTikTok(user.id);
    if (!conexao) {
      return c.json({ error: "TikTok não conectada" }, 400);
    }
    if (!conexao.advertiserId) {
      return c.json({ error: "Conta de anúncios TikTok não selecionada" }, 400);
    }

    // ASSUMPTION: enum operation_status "ENABLE"/"DISABLE" e endpoints separados
    // por tipo de objeto — confirmar contra o SDK oficial na Fase 2B.
    const operationStatus = status === "ACTIVE" ? "ENABLE" : "DISABLE";

    const campanhaRes = await tiktokFetch("/campaign/update/status/", conexao.token, {
      method: "POST",
      body: {
        advertiser_id: conexao.advertiserId,
        campaign_ids: [String(campaign_id)],
        operation_status: operationStatus
      }
    });

    if (!campanhaRes.ok) {
      return c.json({ error: campanhaRes.error || "Erro ao alterar campanha no TikTok" }, 400);
    }

    if (adset_id) {
      const adgroupRes = await tiktokFetch("/adgroup/update/status/", conexao.token, {
        method: "POST",
        body: {
          advertiser_id: conexao.advertiserId,
          adgroup_ids: [String(adset_id)],
          operation_status: operationStatus
        }
      });
      console.log("TOGGLE ADGROUP TIKTOK:", adgroupRes);
    }

    if (ad_id) {
      const adRes = await tiktokFetch("/ad/update/status/", conexao.token, {
        method: "POST",
        body: {
          advertiser_id: conexao.advertiserId,
          ad_ids: [String(ad_id)],
          operation_status: operationStatus
        }
      });
      console.log("TOGGLE AD TIKTOK:", adRes);
    }

    await client.query(
      `UPDATE campanhas SET status = $1, atualizado_em = NOW() WHERE id = $2`,
      [status, campanhaBanco.rows[0].id]
    );

    return c.json({ sucesso: true });
  } catch (err: any) {
    console.error("ERRO /tiktok/toggle-campanha:", err);
    return c.json({ error: "Erro ao alterar campanha" }, 500);
  }
});

// Exclui (marca como DELETED) uma campanha TikTok — tolera campanha já sumida na TikTok
app.post("/tiktok/excluir-campanha", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { campaign_id } = await c.req.json();

    if (!campaign_id) {
      return c.json({ error: "campaign_id obrigatorio" }, 400);
    }

    const campanha = await client.query(
      `SELECT id FROM campanhas
       WHERE campaign_id = $1 AND usuario_id = $2 AND plataforma = 'tiktok'
       LIMIT 1`,
      [campaign_id, user.id]
    );

    if (!campanha.rows.length) {
      return c.json({ error: "Apenas o dono da campanha pode excluí-la" }, 403);
    }

    const conexao = await obterConexaoTikTok(user.id);

    if (conexao?.advertiserId) {
      const del = await tiktokFetch("/campaign/update/status/", conexao.token, {
        method: "POST",
        body: {
          advertiser_id: conexao.advertiserId,
          campaign_ids: [String(campaign_id)],
          operation_status: "DELETE"
        }
      });

      if (!del.ok) {
        // Tolera campanha já removida/inexistente na TikTok — mesmo espírito do
        // Meta: não trava o usuário por causa de um objeto que já sumiu do lado de lá.
        const msg = (del.error || "").toLowerCase();
        const naoPertenceMaisTikTok =
          msg.includes("not exist") ||
          msg.includes("not found") ||
          msg.includes("invalid campaign") ||
          msg.includes("does not exist");

        if (!naoPertenceMaisTikTok) {
          return c.json({ error: del.error || "Erro ao excluir no TikTok" }, 400);
        }
        console.log("EXCLUIR TIKTOK: campanha não encontrada na TikTok, removendo localmente:", campaign_id);
      }
    }

    await client.query(
      `UPDATE campanhas SET status = 'DELETED', atualizado_em = NOW() WHERE id = $1`,
      [campanha.rows[0].id]
    );

    return c.json({ sucesso: true });
  } catch (err: any) {
    console.error("ERRO /tiktok/excluir-campanha:", err);
    return c.json({ error: "Erro ao excluir campanha" }, 500);
  }
});

// Restaura (volta pra PAUSED) uma campanha TikTok excluída no histórico local
app.post("/tiktok/restaurar-campanha", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { campaign_id } = await c.req.json();

    if (!campaign_id) {
      return c.json({ error: "campaign_id obrigatorio" }, 400);
    }

    const campanha = await client.query(
      `SELECT id, adset_id, ad_id FROM campanhas
       WHERE campaign_id = $1 AND usuario_id = $2 AND plataforma = 'tiktok' AND UPPER(status) = 'DELETED'
       LIMIT 1`,
      [campaign_id, user.id]
    );

    if (!campanha.rows.length) {
      return c.json({ error: "Campanha excluída não encontrada para este usuário" }, 404);
    }

    const conexao = await obterConexaoTikTok(user.id);
    let aviso: string | null = null;

    if (conexao?.advertiserId) {
      // Reaplica status "pausado" (nunca ativo direto) em campanha + adgroup + anúncio,
      // mesma cautela que o restaurar do Meta.
      const alvos: Array<{ endpoint: string; campo: string; id: string | null }> = [
        { endpoint: "/campaign/update/status/", campo: "campaign_ids", id: String(campaign_id) },
        { endpoint: "/adgroup/update/status/", campo: "adgroup_ids", id: campanha.rows[0].adset_id },
        { endpoint: "/ad/update/status/", campo: "ad_ids", id: campanha.rows[0].ad_id }
      ];

      for (const alvo of alvos) {
        if (!alvo.id) continue;
        const res = await tiktokFetch(alvo.endpoint, conexao.token, {
          method: "POST",
          body: {
            advertiser_id: conexao.advertiserId,
            [alvo.campo]: [alvo.id],
            operation_status: "DISABLE"
          }
        });
        if (!res.ok && !aviso) {
          aviso = "O TikTok não permitiu recuperar a campanha original. Ela ficou restaurada apenas na plataforma.";
        }
      }
    } else {
      aviso = "TikTok não conectada. A campanha foi restaurada apenas no histórico local.";
    }

    await client.query(
      `UPDATE campanhas SET status = 'PAUSED', atualizado_em = NOW() WHERE id = $1`,
      [campanha.rows[0].id]
    );

    return c.json({ sucesso: true, aviso });
  } catch (err: any) {
    console.error("ERRO /tiktok/restaurar-campanha:", err);
    return c.json({ error: "Erro ao restaurar campanha" }, 500);
  }
});

// Upload de imagem de criativo para a TikTok Ads (equivalente ao /meta/upload-imagem)
app.post("/tiktok/upload-imagem", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const body = await c.req.formData();

    const imagem = body.get("imagem") as File;
    const usuario_id = body.get("usuario_id");
    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);

    if (!usuarioId) {
      return negarAcessoConta(c);
    }
    if (!imagem) {
      return c.json({ error: "Imagem não enviada" }, 400);
    }

    const conexao = await obterConexaoTikTok(usuarioId);
    if (!conexao) {
      return c.json({ error: "TikTok não conectada" }, 400);
    }
    if (!conexao.advertiserId) {
      return c.json({ error: "Conta de anúncios TikTok não selecionada" }, 400);
    }

    // ASSUMPTION: endpoint/campos de multipart conforme documentação pública —
    // confirmar contra o SDK oficial (github.com/tiktok/tiktok-business-api-sdk) na Fase 2B.
    const tiktokForm = new FormData();
    tiktokForm.append("advertiser_id", conexao.advertiserId);
    tiktokForm.append("upload_type", "UPLOAD_BY_FILE");
    tiktokForm.append("image_file", imagem, imagem.name);

    const response = await fetch(`${TIKTOK_API}/file/image/ad/upload/`, {
      method: "POST",
      headers: { "Access-Token": conexao.token },
      body: tiktokForm
    });

    const texto = await response.text();
    let upload: any = {};
    try { upload = JSON.parse(texto); } catch (_) { upload = { raw: texto }; }

    if (upload.code !== 0 || !upload.data?.image_id) {
      console.error("ERRO UPLOAD IMAGEM TIKTOK:", upload);
      return c.json({ error: upload.message || "Erro ao enviar imagem para o TikTok", detalhe: upload }, 400);
    }

    return c.json({
      sucesso: true,
      image_id: upload.data.image_id,
      url: upload.data.image_url || upload.data.url || null
    });
  } catch (err: any) {
    console.error("ERRO /tiktok/upload-imagem:", err?.message || err);
    return c.json({ error: err?.message || "Erro upload imagem TikTok" }, 500);
  }
});

// Upload de vídeo de criativo para a TikTok Ads (equivalente ao /meta/upload-video)
app.post("/tiktok/upload-video", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const body = await c.req.formData();

    const video = body.get("video") as File;
    const usuario_id = body.get("usuario_id");
    const nomeInformado = String(body.get("nome") || video?.name || "video-campanha.mp4");
    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);

    if (!usuarioId) {
      return negarAcessoConta(c);
    }
    if (!video) {
      return c.json({ error: "Vídeo não enviado" }, 400);
    }

    const conexao = await obterConexaoTikTok(usuarioId);
    if (!conexao) {
      return c.json({ error: "TikTok não conectada" }, 400);
    }
    if (!conexao.advertiserId) {
      return c.json({ error: "Conta de anúncios TikTok não selecionada" }, 400);
    }

    // ASSUMPTION: TikTok exige video_signature (MD5 do arquivo) no upload de vídeo —
    // confirmar contra o SDK oficial na Fase 2B.
    const bytes = new Uint8Array(await video.arrayBuffer());
    const signature = createHash("md5").update(bytes).digest("hex");

    const tiktokForm = new FormData();
    tiktokForm.append("advertiser_id", conexao.advertiserId);
    tiktokForm.append("upload_type", "UPLOAD_BY_FILE");
    tiktokForm.append("video_signature", signature);
    tiktokForm.append("video_file", video, nomeInformado);

    const response = await fetch(`${TIKTOK_API}/file/video/ad/upload/`, {
      method: "POST",
      headers: { "Access-Token": conexao.token },
      body: tiktokForm
    });

    const texto = await response.text();
    let upload: any = {};
    try { upload = JSON.parse(texto); } catch (_) { upload = { raw: texto }; }

    const videoData = Array.isArray(upload.data) ? upload.data[0] : upload.data;

    if (upload.code !== 0 || !videoData?.video_id) {
      console.error("ERRO UPLOAD VIDEO TIKTOK:", upload);
      return c.json({ error: upload.message || "Erro ao enviar vídeo para o TikTok", detalhe: upload }, 400);
    }

    return c.json({
      sucesso: true,
      video_id: videoData.video_id,
      video_nome: nomeInformado,
      video_tipo: video.type || "",
      video_tamanho: video.size || 0
    });
  } catch (err: any) {
    console.error("ERRO /tiktok/upload-video:", err?.message || err);
    return c.json({ error: err?.message || "Erro upload vídeo TikTok" }, 500);
  }
});

// Lista identidades (perfil TikTok / usuário customizado) disponíveis do anunciante conectado
// — equivalente à Página do Facebook, mas é um objeto próprio da TikTok Business API.
app.get("/tiktok/identidades", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    const conexao = await obterConexaoTikTok(user.id);
    if (!conexao) return c.json({ error: "TikTok nao conectado" }, 400);
    if (!conexao.advertiserId) {
      return c.json({ error: "Selecione a conta de anunciante TikTok antes de buscar identidades" }, 400);
    }

    // ASSUMPTION: shape de /identity/get/ (identity_id/identity_type/display_name) —
    // confirmar contra o SDK oficial (github.com/tiktok/tiktok-business-api-sdk) na Fase 2B.
    const params = new URLSearchParams({ advertiser_id: conexao.advertiserId });
    const resposta = await tiktokFetch(`/identity/get/?${params}`, conexao.token);

    if (!resposta.ok) {
      console.error("ERRO TIKTOK IDENTIDADES:", resposta.data);
      return c.json({ error: resposta.error || "Erro ao buscar identidades TikTok" }, 502);
    }

    const identidades = Array.isArray(resposta.data?.data?.identity_list)
      ? resposta.data.data.identity_list
      : Array.isArray(resposta.data?.data)
      ? resposta.data.data
      : [];

    return c.json({ identidades });
  } catch (err: any) {
    console.error("ERRO /tiktok/identidades:", err);
    return c.json({ error: "Erro interno" }, 500);
  }
});

// Salva a identidade (perfil TikTok) escolhida pelo usuário para publicar os anúncios
app.post("/tiktok/selecionar-identidade", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    const { identity_id, identity_type } = await c.req.json();
    if (!identity_id || !identity_type) {
      return c.json({ error: "identity_id e identity_type obrigatorios" }, 400);
    }

    await client.query(
      `UPDATE plataforma_conexoes
       SET dados_conta = COALESCE(dados_conta, '{}'::jsonb)
         || jsonb_build_object('identity_id', $1::text, 'identity_type', $2::text),
           atualizado_em = NOW()
       WHERE usuario_id = $3 AND plataforma = 'tiktok'`,
      [String(identity_id), String(identity_type), user.id]
    );
    return c.json({ sucesso: true });
  } catch (err: any) {
    console.error("ERRO /tiktok/selecionar-identidade:", err);
    return c.json({ error: "Erro interno" }, 500);
  }
});

// Busca de interesses para segmentação (equivalente ao /meta/direcionamento/interesses)
app.post("/tiktok/direcionamento/interesses", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { usuario_id, busca } = await c.req.json();

    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);
    if (!usuarioId) {
      return negarAcessoConta(c);
    }

    const termo = textoOpcional(busca).slice(0, 80);
    if (termo.length < 2) {
      return c.json({ data: [] });
    }

    const conexao = await obterConexaoTikTok(usuarioId);
    if (!conexao) {
      return c.json({ error: "Conecte a TikTok antes de buscar interesses" }, 400);
    }
    if (!conexao.advertiserId) {
      return c.json({ error: "Selecione a conta de anúncios TikTok antes de buscar interesses" }, 400);
    }

    // ASSUMPTION: /interest_category/list/ retorna a árvore inteira de categorias de
    // interesse (a API não parece expor busca por termo nesse endpoint), então o filtro
    // por substring é feito aqui no backend. Confirmar na Fase 2B se existe um endpoint
    // mais direto de busca por palavra-chave (ex.: interest_keyword/recommend/).
    const params = new URLSearchParams({ advertiser_id: conexao.advertiserId });
    const resposta = await tiktokFetch(`/interest_category/list/?${params}`, conexao.token);

    if (!resposta.ok) {
      return c.json({
        error: resposta.error || "Erro ao buscar interesses na TikTok",
        detalhe: resposta.data
      }, 400);
    }

    const termoBusca = termo.toLowerCase();
    const categorias = Array.isArray(resposta.data?.data?.interest_category_list)
      ? resposta.data.data.interest_category_list
      : Array.isArray(resposta.data?.data)
      ? resposta.data.data
      : [];

    const data = categorias
      .map((cat: any) => ({
        id: textoOpcional(cat.interest_category_id ?? cat.id),
        nome: textoOpcional(cat.name),
        caminho: listaOpcional(cat.path ?? [])
      }))
      .filter((cat: any) =>
        cat.id &&
        cat.nome &&
        cat.nome.toLowerCase().includes(termoBusca)
      )
      .slice(0, 12);

    return c.json({ data });
  } catch (err) {
    console.error("ERRO BUSCA INTERESSES TIKTOK:", err);
    return c.json({ error: "Erro ao buscar interesses TikTok" }, 500);
  }
});

// Busca de localizações para segmentação (equivalente ao /meta/direcionamento/localizacao)
app.post("/tiktok/direcionamento/localizacao", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { usuario_id, busca } = await c.req.json();

    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);
    if (!usuarioId) {
      return negarAcessoConta(c);
    }

    const termo = textoOpcional(busca).slice(0, 80);
    if (termo.length < 2) {
      return c.json({ data: [] });
    }

    const conexao = await obterConexaoTikTok(usuarioId);
    if (!conexao) {
      return c.json({ error: "Conecte a TikTok antes de buscar localizações" }, 400);
    }
    if (!conexao.advertiserId) {
      return c.json({ error: "Selecione a conta de anúncios TikTok antes de buscar localizações" }, 400);
    }

    // ASSUMPTION: /region/ retorna a árvore inteira de localidades disponíveis pro
    // advertiser (sem busca por termo nativa), então o filtro por substring é feito
    // aqui no backend. Confirmar o shape exato (campos de nível/hierarquia) na Fase 2B.
    const params = new URLSearchParams({ advertiser_id: conexao.advertiserId });
    const resposta = await tiktokFetch(`/region/?${params}`, conexao.token);

    if (!resposta.ok) {
      return c.json({
        error: resposta.error || "Erro ao buscar localizações na TikTok",
        detalhe: resposta.data
      }, 400);
    }

    const termoBusca = termo.toLowerCase();
    const locais = Array.isArray(resposta.data?.data?.region_list)
      ? resposta.data.data.region_list
      : Array.isArray(resposta.data?.data)
      ? resposta.data.data
      : [];

    const data = locais
      .map((local: any) => ({
        key: textoOpcional(local.region_code ?? local.id),
        nome: textoOpcional(local.region_name ?? local.name),
        tipo: textoOpcional(local.level ?? local.type),
        pais: textoOpcional(local.country_code ?? local.pais)
      }))
      .filter((local: any) =>
        local.key &&
        local.nome &&
        local.nome.toLowerCase().includes(termoBusca)
      )
      .slice(0, 10);

    return c.json({ data });
  } catch (err) {
    console.error("ERRO BUSCA LOCALIZACAO TIKTOK:", err);
    return c.json({ error: "Erro ao buscar localização TikTok" }, 500);
  }
});

// Cria a Campanha na TikTok Ads (equivalente ao /meta/campanha)
app.post("/tiktok/campanha", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const {
      usuario_id,
      nome,
      configuracoes_avancadas,
      nicho_id,
      daily_budget,
      publicacao_grupo_id,
      destino
    } = await c.req.json();

    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);
    if (!usuarioId) {
      return negarAcessoConta(c);
    }

    const conexao = await obterConexaoTikTok(usuarioId);
    if (!conexao) {
      return c.json({ error: "TikTok não conectada" }, 400);
    }
    if (!conexao.advertiserId) {
      return c.json({ error: "Selecione a conta de anúncios TikTok antes de criar a campanha" }, 400);
    }

    // ASSUMPTION: enum objective_type ("LEAD_GENERATION") conforme
    // documentação pública do campaign/create — confirmar contra o SDK
    // oficial na Fase 2B.
    //
    // Orçamento fica SEMPRE no ad group (/tiktok/adgroup), não aqui — sem
    // CBO configurado, setar budget_mode/budget nos dois níveis ao mesmo
    // tempo (campanha E ad group) é ambíguo pra API da TikTok e arriscava
    // rejeição ou double-booking de orçamento. Campanha fica sempre
    // BUDGET_MODE_INFINITE; quem limita o gasto de verdade é o ad group.
    const payloadCampanha: any = {
      advertiser_id: conexao.advertiserId,
      campaign_name: nome || "Campanha Leads Plataforma",
      objective_type: "LEAD_GENERATION",
      budget_mode: "BUDGET_MODE_INFINITE",
      operation_status: "DISABLE"
    };

    const resposta = await tiktokFetch("/campaign/create/", conexao.token, {
      method: "POST",
      body: payloadCampanha
    });

    if (!resposta.ok || !resposta.data?.data?.campaign_id) {
      console.error("ERRO CAMPANHA TIKTOK:", resposta.data);
      return c.json({
        error: resposta.error || "Erro ao criar campanha na TikTok",
        detalhe: resposta.data
      }, 400);
    }

    const campaignId = String(resposta.data.data.campaign_id);
    const destinoResolvido = resolverDestinoCampanhaTikTok(
      destino ?? configuracoes_avancadas?.destino
    );
    const configuracoesPersistidas = {
      ...(configuracoes_avancadas || {}),
      destino: destinoResolvido
    };

    await client.query(
      `INSERT INTO campanhas (
        usuario_id, campaign_id, conta_anuncios_id, nome, status, origem,
        configuracoes_avancadas, nicho_id, plataforma, publicacao_grupo_id
      )
      VALUES ($1,$2,$3,$4,$5,$6,$7,$8,'tiktok',$9)`,
      [
        usuarioId,
        campaignId,
        conexao.advertiserId,
        nome || "Campanha Plataforma",
        "PAUSED",
        "plataforma",
        JSON.stringify(configuracoesPersistidas),
        nicho_id ?? null,
        textoOpcional(publicacao_grupo_id) || null
      ]
    );

    return c.json({ id: campaignId, campaign_id: campaignId });
  } catch (err: any) {
    console.error("ERRO /tiktok/campanha:", err);
    return c.json({ error: "Erro ao criar campanha TikTok" }, 500);
  }
});

// Cria o Grupo de Anúncios (Ad Group) na TikTok Ads (equivalente ao /meta/adset)
app.post("/tiktok/adgroup", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const {
      usuario_id,
      campaign_id,
      daily_budget,
      configuracoes_avancadas,
      destino
    } = await c.req.json();

    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);
    if (!usuarioId) {
      return negarAcessoConta(c);
    }

    if (!campaign_id) {
      return c.json({ error: "campaign_id não enviado" }, 400);
    }

    const conexao = await obterConexaoTikTok(usuarioId);
    if (!conexao) {
      return c.json({ error: "TikTok não conectada" }, 400);
    }
    if (!conexao.advertiserId) {
      return c.json({ error: "Selecione a conta de anúncios TikTok antes de criar o grupo de anúncios" }, 400);
    }

    const avancadas = configuracoes_avancadas || {};
    const targeting = montarTargetingTikTok(avancadas);
    const destinoResolvido = resolverDestinoCampanhaTikTok(destino ?? avancadas.destino);

    if (!targeting.location_ids?.length) {
      return c.json({ error: "Selecione ao menos uma localização para segmentar a campanha TikTok" }, 400);
    }

    // daily_budget chega multiplicado por 100 (mesma convenção usada pra
    // Meta, que trabalha em centavos) — mas a TikTok espera o valor "cru" na
    // moeda da conta (R$50/dia = manda 50, não 5000). Sem essa divisão, uma
    // campanha configurada pra R$50/dia era criada na TikTok com orçamento
    // de R$5.000/dia (bug confirmado nesta auditoria).
    const orcamentoCentavos = numeroOpcional(daily_budget);
    if (!orcamentoCentavos || orcamentoCentavos <= 0) {
      return c.json({ error: "Orçamento diário é obrigatório para o grupo de anúncios TikTok" }, 400);
    }
    const orcamento = orcamentoCentavos / 100;

    const inicio = textoOpcional(avancadas.inicio);
    const fim = textoOpcional(avancadas.fim);

    let numeroWhatsappTikTok = "";
    if (destinoResolvido === "whatsapp") {
      const numeroConectado = await obterNumeroWhatsappConectadoUsuario(usuarioId);
      if (!numeroConectado) {
        return c.json({
          error: "Conecte o WhatsApp da plataforma (aba WhatsApp Bot) antes de publicar uma campanha TikTok com destino WhatsApp."
        }, 400);
      }
      numeroWhatsappTikTok = prepararNumeroWhatsappBrasilTikTok(numeroConectado);
      if (!numeroWhatsappTikTok) {
        return c.json({
          error: "O número conectado ao WhatsApp precisa ser brasileiro e conter DDD para ser usado no TikTok Ads."
        }, 400);
      }
    }

    // Mapeamento oficial da TikTok Business API v1.3:
    // - Instant Form: LEAD_GENERATION + INSTANT_PAGE, otimizado para Lead Generation;
    // - site: LEAD_GENERATION + EXTERNAL_WEBSITE, otimizado para clique sem exigir Pixel;
    // - WhatsApp: LEAD_GEN_CLICK_TO_SOCIAL_MEDIA_APP_MESSAGE + WHATSAPP.
    // Click/CPC no WhatsApp funciona sem parceiro de mensagens nem event set.
    const ehFormulario = destinoResolvido === "lead_ads";
    const payloadAdgroup: any = {
      advertiser_id: conexao.advertiserId,
      campaign_id: String(campaign_id),
      adgroup_name: `AdGroup Leads ${Date.now()}`,
      promotion_type: destinoResolvido === "whatsapp"
        ? "LEAD_GEN_CLICK_TO_SOCIAL_MEDIA_APP_MESSAGE"
        : "LEAD_GENERATION",
      ...(destinoResolvido === "lead_ads" ? { promotion_target_type: "INSTANT_PAGE" } : {}),
      ...(destinoResolvido === "site" ? { promotion_target_type: "EXTERNAL_WEBSITE" } : {}),
      ...(destinoResolvido === "whatsapp" ? {
        messaging_app_type: "WHATSAPP",
        phone_region_code: "BR",
        phone_region_calling_code: "+55",
        phone_number: numeroWhatsappTikTok
      } : {}),
      placement_type: "PLACEMENT_TYPE_AUTOMATIC",
      ...targeting,
      budget_mode: "BUDGET_MODE_DYNAMIC_DAILY_BUDGET",
      budget: orcamento,
      billing_event: ehFormulario ? "OCPM" : "CPC",
      optimization_goal: ehFormulario ? "LEAD_GENERATION" : "CLICK",
      bid_type: "BID_TYPE_NO_BID",
      pacing: "PACING_MODE_SMOOTH",
      schedule_start_time: formatarDataHoraTikTok(
        inicio ? new Date(inicio) : new Date(Date.now() + 60000)
      ),
      operation_status: "DISABLE"
    };

    if (fim) {
      payloadAdgroup.schedule_type = "SCHEDULE_START_END";
      payloadAdgroup.schedule_end_time = formatarDataHoraTikTok(new Date(fim));
    } else {
      payloadAdgroup.schedule_type = "SCHEDULE_FROM_NOW";
    }

    const resposta = await tiktokFetch("/adgroup/create/", conexao.token, {
      method: "POST",
      body: payloadAdgroup
    });

    if (!resposta.ok || !resposta.data?.data?.adgroup_id) {
      console.error("ERRO ADGROUP TIKTOK:", resposta.data);
      return c.json({
        error: resposta.error || "Erro ao criar grupo de anúncios na TikTok",
        detalhe: resposta.data,
        targeting_enviado: targeting
      }, 400);
    }

    return c.json({ adgroup_id: String(resposta.data.data.adgroup_id) });
  } catch (err: any) {
    console.error("ERRO /tiktok/adgroup:", err);
    return c.json({ error: "Erro ao criar grupo de anúncios TikTok" }, 500);
  }
});

// Lista os formulários instantâneos (Instant Form) já existentes do anunciante conectado.
// Diferente do Meta, a TikTok não cria formulário via API neste fluxo — o usuário escolhe
// um já criado no TikTok Ads Manager. Se a listagem falhar (endpoint incerto até validação
// na Fase 2B), devolve lista vazia com aviso em vez de erro, para o frontend usar o campo
// de ID manual como alternativa (a UI já foi desenhada prevendo esse fallback).
app.get("/tiktok/formularios", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    const conexao = await obterConexaoTikTok(user.id);
    if (!conexao) return c.json({ error: "TikTok nao conectado" }, 400);
    if (!conexao.advertiserId) {
      return c.json({ error: "Selecione a conta de anunciante TikTok antes de listar formularios" }, 400);
    }

    // ASSUMPTION MAIS ARRISCADA DE TODA A FASE 2A: endpoint e formato de listagem de
    // Instant Forms — confirmar contra o SDK oficial na Fase 2B.
    const params = new URLSearchParams({ advertiser_id: conexao.advertiserId });
    const resposta = await tiktokFetch(`/page/lead_gen/get/?${params}`, conexao.token);

    if (!resposta.ok) {
      console.warn("TIKTOK FORMULARIOS: listagem indisponivel, frontend deve oferecer ID manual:", resposta.error);
      return c.json({
        formularios: [],
        aviso: "Não foi possível listar formulários existentes. Informe o ID manualmente."
      });
    }

    const formularios = Array.isArray(resposta.data?.data?.pages)
      ? resposta.data.data.pages
      : Array.isArray(resposta.data?.data)
      ? resposta.data.data
      : [];

    return c.json({ formularios });
  } catch (err: any) {
    console.error("ERRO /tiktok/formularios:", err);
    return c.json({
      formularios: [],
      aviso: "Não foi possível listar formulários existentes. Informe o ID manualmente."
    });
  }
});

// Cria o Anúncio (criativo + ad) na TikTok Ads (equivalente ao /meta/anuncio) —
// é aqui que a linha de campanhas recebe adset_id/ad_id/form_id, mesmo padrão do Meta.
app.post("/tiktok/anuncio", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const {
      usuario_id,
      campaign_id,
      adgroup_id,
      form_id,
      identity_id,
      identity_type,
      texto,
      cta,
      configuracoes_avancadas,
      daily_budget,
      image_ids,
      image_id,
      video_id,
      destino,
      url_destino
    } = await c.req.json();

    const usuarioId = resolverUsuarioIdOperacao(user, usuario_id);
    if (!usuarioId) {
      return negarAcessoConta(c);
    }

    const avancadas = configuracoes_avancadas || {};
    const destinoResolvido = resolverDestinoCampanhaTikTok(destino ?? avancadas.destino);
    const urlDestino = destinoResolvido === "site" ? urlOpcional(url_destino, "") : "";

    if (destinoResolvido === "lead_ads" && !form_id) {
      return c.json({ error: "form_id (Instant Form) não enviado" }, 400);
    }
    if (destinoResolvido === "site" && !urlDestino) {
      return c.json({ error: "Informe um endereço completo e válido para o anúncio TikTok" }, 400);
    }
    if (!adgroup_id) {
      return c.json({ error: "adgroup_id não enviado" }, 400);
    }

    const conexao = await obterConexaoTikTok(usuarioId);
    if (!conexao) {
      return c.json({ error: "TikTok não conectada" }, 400);
    }
    if (!conexao.advertiserId) {
      return c.json({ error: "Selecione a conta de anúncios TikTok antes de publicar o anúncio" }, 400);
    }

    const identidadeId = textoOpcional(identity_id) || conexao.identityId;
    const identidadeTipo = textoOpcional(identity_type) || conexao.identityType;

    if (!identidadeId || !identidadeTipo) {
      return c.json({ error: "Selecione a identidade (perfil TikTok) antes de publicar o anúncio" }, 400);
    }

    const tituloAnuncio = textoOpcional(avancadas.titulo) || "Saiba mais";

    const imagens: string[] =
      Array.isArray(image_ids) && image_ids.length
        ? image_ids
        : image_id
        ? [image_id]
        : [];

    if (!imagens.length && !video_id) {
      return c.json({ error: "Envie ao menos uma imagem ou vídeo para o anúncio TikTok" }, 400);
    }

    // page_id só é válido para Instant Form. No site a URL vai no criativo; no
    // WhatsApp o destino já foi definido no ad group e a própria TikTok o preenche.
    const criativo: any = {
      ad_name: `Anuncio Leads ${Date.now()}`,
      ad_format: video_id ? "SINGLE_VIDEO" : imagens.length > 1 ? "CAROUSEL_ADS" : "SINGLE_IMAGE",
      identity_id: identidadeId,
      identity_type: identidadeTipo,
      ad_text: texto || "Quer mais clientes? 🚀",
      call_to_action: destinoResolvido === "whatsapp" ? "CONTACT_US" : (cta || "LEARN_MORE"),
      ...(destinoResolvido === "lead_ads" ? { page_id: String(form_id) } : {}),
      ...(destinoResolvido === "site" ? { landing_page_url: urlDestino } : {})
    };

    if (video_id) {
      criativo.video_id = video_id;
    } else {
      criativo.image_ids = imagens;
    }

    const resposta = await tiktokFetch("/ad/create/", conexao.token, {
      method: "POST",
      body: {
        advertiser_id: conexao.advertiserId,
        adgroup_id: String(adgroup_id),
        creatives: [criativo]
      }
    });

    const adId =
      Array.isArray(resposta.data?.data?.ad_ids)
        ? resposta.data.data.ad_ids[0]
        : resposta.data?.data?.ad_id;

    if (!resposta.ok || !adId) {
      console.error("ERRO ANUNCIO TIKTOK:", resposta.data);
      return c.json({
        error: resposta.error || "Erro ao criar anúncio na TikTok",
        detalhe: resposta.data
      }, 400);
    }

    // 💾 grava tudo no banco — mesmo padrão do /meta/anuncio (page_id fica NULL pra
    // linhas TikTok, já que não existe Página do Facebook aqui; identity/form vão no JSONB)
    const configuracoesPersistidas = {
      ...avancadas,
      texto,
      cta,
      destino: destinoResolvido,
      url_destino: urlDestino || null,
      form_id: destinoResolvido === "lead_ads" ? String(form_id) : null,
      identity_id: identidadeId,
      identity_type: identidadeTipo,
      image_ids: imagens,
      video_id: video_id || null,
      criativo: {
        ad_id: String(adId),
        tipo: video_id ? "video" : imagens.length > 1 ? "carrossel" : "imagem",
        titulo: tituloAnuncio,
        image_ids: imagens,
        video_id: video_id || null
      }
    };

    await client.query(
      `UPDATE campanhas
       SET adset_id = $1,
           ad_id = $2,
           form_id = $3,
           daily_budget = $4,
           configuracoes_avancadas = COALESCE(configuracoes_avancadas, '{}'::jsonb) || $5::jsonb,
           atualizado_em = NOW()
       WHERE campaign_id = $6 AND usuario_id = $7 AND plataforma = 'tiktok'`,
      [
        String(adgroup_id),
        String(adId),
        destinoResolvido === "lead_ads" ? String(form_id) : null,
        numeroOpcional(daily_budget),
        JSON.stringify(configuracoesPersistidas),
        String(campaign_id),
        usuarioId
      ]
    );

    return c.json({ id: String(adId), ad_id: String(adId) });
  } catch (err: any) {
    console.error("ERRO /tiktok/anuncio:", err);
    return c.json({ error: "Erro ao criar anúncio TikTok", detalhe: err?.message || err }, 500);
  }
});

/* =========================
   🎬 KWAI ADS
   Kuaishou Marketing API (磁力引擎 / "Magnetic Engine"). FASE 1 — ESQUELETO
   ESTRUTURAL, NÃO INTEGRAÇÃO REAL: a Kuaishou exige aprovação formal de
   parceiro pra liberar client_id/secret e documentação de campos, que o
   projeto ainda não tem (ver o comentário em OAUTH_PROVEDORES.kwai — por
   isso authUrl/tokenUrl ficam vazios lá, e /auth/kwai/login já retorna 503
   antes de qualquer coisa aqui embaixo rodar).
   Diferente da seção TIKTOK ADS (que serviu de molde pra shape de todas as
   rotas abaixo), NENHUMA chamada de rede real pra Kuaishou é feita nesta
   seção — não temos como confirmar o schema de request/response de um
   parceiro sem acesso à documentação oficial, e adivinhar formato de campo
   arriscaria quebrar de forma silenciosa quando a integração de verdade for
   plugada. Toda validação de banco (conexão existe? anunciante selecionado?
   arquivo enviado?) é real; só o passo final ("chamar a API da Kuaishou")
   devolve um erro amigável em português avisando que a integração está
   pendente de aprovação. Rotas de criação (campanha/adgroup/anúncio) não
   gravam linha em `campanhas` quando stubadas — ver comentário em
   POST /kwai/campanha sobre por que essa escolha foi feita.
   Quando a aprovação de parceiro sair: trocar cada bloco "🚧 STUB" abaixo
   pela chamada real via kwaiFetch/fetch, no mesmo padrão desta função ou
   rota TikTok equivalente citada no comentário.
========================= */

const kwaiSyncEmAndamento = new Set<number>();

// Gateway real da Kuaishou Marketing API por documentação pública — os PATHS
// específicos abaixo dele (advertiser/get, campaign/create etc.) ainda NÃO
// estão confirmados contra docs oficiais de parceiro (ver cabeçalho da
// seção). Por isso nenhuma rota abaixo faz fetch() de verdade usando esta
// constante ainda — só existe pronta pra quando a aprovação sair.
const KWAI_API = "https://ad.e.kuaishou.com/rest/openapi";

function kwaiHeaders(token: string) {
  return { "Access-Token": token, "Content-Type": "application/json" };
}

// Wrapper espelhando tiktokFetch — o envelope {code, message, data} aqui é um
// CHUTE baseado no padrão comum de outras APIs de ads (a própria TikTok usa
// esse formato), NÃO confirmado contra documentação oficial da Kuaishou.
// Ainda não é chamado por nenhuma rota desta seção (ver nota em KWAI_API);
// existe só como scaffold pronto pra quando o schema real for confirmado.
async function kwaiFetch(
  endpoint: string,
  token: string,
  opts: { method?: string; body?: any } = {}
): Promise<{ ok: boolean; data: any; error: string | null }> {
  try {
    const res = await fetch(`${KWAI_API}${endpoint}`, {
      method: opts.method || "GET",
      headers: kwaiHeaders(token),
      body: opts.body ? JSON.stringify(opts.body) : undefined
    });
    const data = await res.json() as any;
    if (data.code !== 0) {
      return { ok: false, data, error: data.message || "Erro na API do Kwai" };
    }
    return { ok: true, data, error: null };
  } catch (err: any) {
    return { ok: false, data: null, error: err?.message || "Erro de rede ao chamar a API do Kwai" };
  }
}

// Busca token + conta de anúncios (advertiser_id) + identidade já
// selecionadas pelo usuário — mesmo shape de obterConexaoTikTok.
async function obterConexaoKwai(
  usuarioId: number
): Promise<{
  token: string;
  advertiserId: string | null;
  identityId: string | null;
  identityType: string | null;
} | null> {
  const conn = await client.query(
    `SELECT access_token, dados_conta FROM plataforma_conexoes
     WHERE usuario_id = $1 AND plataforma = 'kwai' LIMIT 1`,
    [usuarioId]
  );
  if (!conn.rows.length) return null;
  const dadosConta = conn.rows[0].dados_conta ?? {};
  return {
    token: conn.rows[0].access_token,
    advertiserId: dadosConta.advertiser_id ?? null,
    identityId: dadosConta.identity_id ?? null,
    identityType: dadosConta.identity_type ?? null
  };
}

const KWAI_AVISO_INDISPONIVEL =
  "Integração com a API do Kwai Ads ainda não está disponível — aguardando aprovação da API Kwai.";

// Lista contas de anunciante vinculadas ao token (equivalente ao
// /tiktok/anunciantes). 🚧 STUB: a checagem de conexão é real; a chamada de
// listagem de verdade ainda não existe.
app.get("/kwai/anunciantes", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    const conn = await client.query(
      `SELECT access_token, dados_conta FROM plataforma_conexoes
       WHERE usuario_id = $1 AND plataforma = 'kwai' LIMIT 1`,
      [user.id]
    );
    if (!conn.rows.length) return c.json({ error: "Kwai nao conectado" }, 400);

    return c.json({ error: KWAI_AVISO_INDISPONIVEL }, 503);
  } catch (err: any) {
    console.error("ERRO /kwai/anunciantes:", err);
    return c.json({ error: "Erro interno" }, 500);
  }
});

// Salva o anunciante selecionado pelo usuário — puro UPDATE em
// plataforma_conexoes.dados_conta, sem chamada de rede nenhuma (igual ao
// /tiktok/selecionar-anunciante), então é real e funcional desde já.
app.post("/kwai/selecionar-anunciante", authMiddleware, async (c) => {
  const user: any = c.get("user");
  try {
    const { advertiser_id } = await c.req.json();
    if (!advertiser_id) return c.json({ error: "advertiser_id obrigatorio" }, 400);

    await client.query(
      `UPDATE plataforma_conexoes
       SET dados_conta = COALESCE(dados_conta, '{}'::jsonb) || jsonb_build_object('advertiser_id', $1::text),
           atualizado_em = NOW()
       WHERE usuario_id = $2 AND plataforma = 'kwai'`,
      [String(advertiser_id), user.id]
    );
    return c.json({ sucesso: true });
  } catch (err: any) {
    console.error("ERRO /kwai/selecionar-anunciante:", err);
    return c.json({ error: "Erro interno" }, 500);
  }
});

// Sincroniza campanhas e leads do Kwai Ads (equivalente a
// sincronizarTikTokAdsUsuario). Compartilhada entre o botão manual e o ciclo
// automático (ver sincronizarTodasCampanhas). 🚧 STUB: a checagem de conexão
// e de anunciante selecionado é real; a sincronização de verdade (buscar
// campanha/lead na Kuaishou, upsert em `campanhas`/`leads`, disparar
// avaliarEEnviarQualificacaoLead) ainda não existe — na prática esta função
// nunca chega a rodar hoje, porque não existe fluxo de OAuth funcional pra
// criar uma conexão 'kwai' de verdade (ver OAUTH_PROVEDORES.kwai).
async function sincronizarKwaiAdsUsuario(usuarioId: number) {
  const conn = await client.query(
    `SELECT access_token, dados_conta FROM plataforma_conexoes
     WHERE usuario_id = $1 AND plataforma = 'kwai' LIMIT 1`,
    [usuarioId]
  );
  if (!conn.rows.length) throw new Error("Kwai nao conectado");

  const dadosConta = conn.rows[0].dados_conta ?? {};
  const advertiserId = dadosConta.advertiser_id;

  if (!advertiserId) {
    throw new Error("Selecione a conta de anunciante Kwai antes de sincronizar");
  }

  // TODO(kwai): espelhar aqui o mesmo padrão de sincronizarTikTokAdsUsuario
  // (busca campaign/get + lead/get paginado, upsert em campanhas/leads,
  // chamada de avaliarEEnviarQualificacaoLead por lead novo) assim que a
  // aprovação de parceiro sair e o schema de resposta for confirmado.
  throw new Error(KWAI_AVISO_INDISPONIVEL);
}

app.post("/kwai/sincronizar-campanhas", authMiddleware, async (c) => {
  const user: any = c.get("user");

  if (kwaiSyncEmAndamento.has(user.id)) {
    return c.json({ error: "Sincronizacao Kwai ja em andamento" }, 429);
  }
  kwaiSyncEmAndamento.add(user.id);

  try {
    return c.json(await sincronizarKwaiAdsUsuario(user.id));
  } catch (err: any) {
    console.error("ERRO KWAI SINCRONIZAR:", err);
    return c.json({ error: err?.message || "Erro ao sincronizar Kwai" }, 500);
  } finally {
    kwaiSyncEmAndamento.delete(user.id);
  }
});

// Pausa/ativa uma campanha Kwai (equivalente ao /tiktok/toggle-campanha).
// 🚧 STUB: a busca/atualização local em `campanhas` é real; a chamada real
// pra pausar/ativar na Kuaishou ainda não existe — por ora só refletimos o
// status localmente, mesmo espírito de tolerância que o TikTok usa quando a
// conexão não está disponível (ver /tiktok/restaurar-campanha). Na prática
// nenhuma linha com plataforma = 'kwai' existe em `campanhas` hoje, porque
// POST /kwai/campanha não grava nada (ver comentário lá) — esta rota fica
// inerte, mas estruturalmente pronta.
app.post("/kwai/toggle-campanha", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { campaign_id, status } = await c.req.json();

    if (!campaign_id || !["ACTIVE", "PAUSED"].includes(status)) {
      return c.json({ error: "campaign_id e status (ACTIVE/PAUSED) obrigatorios" }, 400);
    }

    const campanhaBanco = await client.query(
      `SELECT id
       FROM campanhas
       WHERE campaign_id = $1 AND usuario_id = $2 AND plataforma = 'kwai'
       LIMIT 1`,
      [campaign_id, user.id]
    );

    if (!campanhaBanco.rows.length) {
      return c.json({ error: "Campanha não disponível para este usuário" }, 404);
    }

    await client.query(
      `UPDATE campanhas SET status = $1, atualizado_em = NOW() WHERE id = $2`,
      [status, campanhaBanco.rows[0].id]
    );

    return c.json({
      sucesso: true,
      aviso: `${KWAI_AVISO_INDISPONIVEL} O status foi alterado apenas na plataforma, não na Kuaishou.`
    });
  } catch (err: any) {
    console.error("ERRO /kwai/toggle-campanha:", err);
    return c.json({ error: "Erro ao alterar campanha" }, 500);
  }
});

// Exclui (marca como DELETED) uma campanha Kwai — equivalente ao
// /tiktok/excluir-campanha. 🚧 STUB: mesma lógica do toggle acima — exclusão
// real na Kuaishou ainda não existe, marca como excluída só localmente.
app.post("/kwai/excluir-campanha", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { campaign_id } = await c.req.json();

    if (!campaign_id) {
      return c.json({ error: "campaign_id obrigatorio" }, 400);
    }

    const campanha = await client.query(
      `SELECT id
       FROM campanhas
       WHERE campaign_id = $1 AND usuario_id = $2 AND plataforma = 'kwai'
       LIMIT 1`,
      [campaign_id, user.id]
    );

    if (!campanha.rows.length) {
      return c.json({ error: "Apenas o dono da campanha pode excluí-la" }, 403);
    }

    await client.query(
      `UPDATE campanhas SET status = 'DELETED', atualizado_em = NOW() WHERE id = $1`,
      [campanha.rows[0].id]
    );

    return c.json({
      sucesso: true,
      aviso: `${KWAI_AVISO_INDISPONIVEL} A campanha foi excluída apenas na plataforma.`
    });
  } catch (err: any) {
    console.error("ERRO /kwai/excluir-campanha:", err);
    return c.json({ error: "Erro ao excluir campanha" }, 500);
  }
});

// Restaura (volta pra PAUSED) uma campanha Kwai excluída no histórico local —
// equivalente ao /tiktok/restaurar-campanha. 🚧 STUB: mesmo espírito de
// tolerância que o TikTok usa quando a conexão não está disponível.
app.post("/kwai/restaurar-campanha", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const { campaign_id } = await c.req.json();

    if (!campaign_id) {
      return c.json({ error: "campaign_id obrigatorio" }, 400);
    }

    const campanha = await client.query(
      `SELECT id FROM campanhas
       WHERE campaign_id = $1 AND usuario_id = $2 AND plataforma = 'kwai' AND UPPER(status) = 'DELETED'
       LIMIT 1`,
      [campaign_id, user.id]
    );

    if (!campanha.rows.length) {
      return c.json({ error: "Campanha excluída não encontrada para este usuário" }, 404);
    }

    await client.query(
      `UPDATE campanhas SET status = 'PAUSED', atualizado_em = NOW() WHERE id = $1`,
      [campanha.rows[0].id]
    );

    return c.json({
      sucesso: true,
      aviso: `${KWAI_AVISO_INDISPONIVEL} A campanha foi restaurada apenas no histórico local.`
    });
  } catch (err: any) {
    console.error("ERRO /kwai/restaurar-campanha:", err);
    return c.json({ error: "Erro ao restaurar campanha" }, 500);
  }
});

