// 🔹 listar campanhas
app.get("/campanhas", authMiddleware, async (c) => {

  try {

    const user = c.get("user");

    console.log("USER:", user.id);

    const contaAnunciosId =
      await obterContaAnunciosSelecionadaIdUsuario(
        user.id
      );

    // A checagem de "pertence a conta de anuncios selecionada" abaixo so comparava
    // contra a conta Meta — campanhas Google (e futuramente TikTok) tem
    // conta_anuncios_id num espaco de IDs completamente diferente (customer_id do
    // Google, advertiser_id do TikTok), entao nunca batiam e a linha inteira
    // desaparecia da listagem mesmo com a campanha criada com sucesso. Resolve a
    // conta selecionada de cada plataforma pra comparar cada uma com a sua propria.
    const contaAnunciosIdGoogle = await client.query(
      `SELECT dados_conta->>'customer_id' AS id FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'google' LIMIT 1`,
      [user.id]
    ).then(r => r.rows[0]?.id || null);

    const contaAnunciosIdTikTok = await client.query(
      `SELECT dados_conta->>'advertiser_id' AS id FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'tiktok' LIMIT 1`,
      [user.id]
    ).then(r => r.rows[0]?.id || null);

    const contaAnunciosIdLinkedIn = await client.query(
      `SELECT dados_conta->>'ad_account_id' AS id FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'linkedin' LIMIT 1`,
      [user.id]
    ).then(r => r.rows[0]?.id || null);

    // Kwai segue o mesmo padrão — nunca vai bater com nada na prática hoje
    // (nenhuma conexão 'kwai' real existe sem OAuth funcionando, ver
    // OAUTH_PROVEDORES.kwai), mas fica pronto pra quando existir.
    const contaAnunciosIdKwai = await client.query(
      `SELECT dados_conta->>'advertiser_id' AS id FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'kwai' LIMIT 1`,
      [user.id]
    ).then(r => r.rows[0]?.id || null);

    const nichoSlug =
      textoOpcional(c.req.query("nicho"));

    const campanhas = await client.query(
      `
      SELECT
        c.*,
        COALESCE(n.id,   nd.id)   AS nicho_id,
        COALESCE(n.slug, nd.slug) AS nicho_slug,
        COALESCE(n.nome, nd.nome) AS nicho_nome,
        COALESCE(n.cor,  nd.cor)  AS nicho_cor,
        COALESCE(dono_origem.email,     dono.email)     AS criado_por_email,
        COALESCE(dono_origem.nome,      dono.nome)      AS criado_por_nome,
        COALESCE(dono_origem.sobrenome, dono.sobrenome) AS criado_por_sobrenome,
        (c.origem_campanha_id IS NOT NULL) AS recebida_por_encaminhamento,
        COALESCE(
          (
            SELECT json_agg(json_build_object(
              'id', cor.id,
              'nome', cor.nome,
              'sobrenome', cor.sobrenome,
              'email', cor.email
            ))
            FROM campanhas cop
            INNER JOIN usuarios cor
              ON cor.id = cop.usuario_id
            WHERE cop.origem_campanha_id = c.id
          ),
          '[]'
        ) AS corretores_encaminhados,
        COALESCE(
          (
            SELECT json_agg(json_build_object(
              'id', cor.id,
              'nome', cor.nome,
              'sobrenome', cor.sobrenome,
              'email', cor.email,
              'status', ch.status,
              'atualizado_em', ch.atualizado_em
            ) ORDER BY ch.atualizado_em DESC)
            FROM campanha_corretores_historico ch
            INNER JOIN usuarios cor
              ON cor.id = ch.usuario_id
            WHERE ch.campanha_id = c.id
          ),
          '[]'
        ) AS corretores_envio_historico
      FROM campanhas c
      INNER JOIN usuarios dono
        ON dono.id = c.usuario_id
      LEFT JOIN campanhas origem_c
        ON origem_c.id = c.origem_campanha_id
      LEFT JOIN usuarios dono_origem
        ON dono_origem.id = origem_c.usuario_id
      LEFT JOIN nichos n
        ON n.id = c.nicho_id
      LEFT JOIN LATERAL (
        SELECT ni.id, ni.slug, ni.nome, ni.cor
        FROM nichos ni
        WHERE c.nicho_id IS NULL AND (
          EXISTS (SELECT 1 FROM campanhas_saude      cs WHERE cs.campanha_id = c.id) AND ni.slug = 'saude'
          OR
          EXISTS (SELECT 1 FROM campanhas_imoveis    ci WHERE ci.campanha_id = c.id) AND ni.slug = 'imoveis'
          OR
          EXISTS (SELECT 1 FROM campanhas_suplementos cp WHERE cp.campanha_id = c.id) AND ni.slug = 'suplementos'
          OR
          EXISTS (SELECT 1 FROM campanhas_higienizacao chg WHERE chg.campanha_id = c.id) AND ni.slug = 'higienizacao'
          OR
          EXISTS (SELECT 1 FROM campanhas_telecom ctc WHERE ctc.campanha_id = c.id) AND ni.slug = 'telecom'
          OR
          EXISTS (SELECT 1 FROM leads l WHERE l.campanha = c.nome AND l.nicho_id = ni.id AND l.usuario_id = c.usuario_id LIMIT 1)
        )
        LIMIT 1
      ) nd ON true
      WHERE
        c.usuario_id = $1
        AND NOT (
          c.plataforma = 'google'
          AND c.origem = 'plataforma'
          AND UPPER(COALESCE(c.status, '')) IN ('REMOVED', 'DELETED')
          AND c.ad_id IS NULL
        )
        AND (
          c.origem = 'manual'
          OR (COALESCE(c.plataforma, 'meta') = 'meta' AND c.conta_anuncios_id = $2)
          OR (c.plataforma = 'google' AND c.conta_anuncios_id = $4)
          OR (c.plataforma = 'tiktok' AND c.conta_anuncios_id = $5)
          OR (c.plataforma = 'linkedin' AND c.conta_anuncios_id = $6)
          OR (c.plataforma = 'kwai' AND c.conta_anuncios_id = $7)
        )
        AND ($3::text IS NULL OR COALESCE(n.slug, nd.slug) = $3)
      ORDER BY c.id DESC
      `,
      [user.id, contaAnunciosId ?? null, nichoSlug ?? null, contaAnunciosIdGoogle, contaAnunciosIdTikTok, contaAnunciosIdLinkedIn, contaAnunciosIdKwai]
    );

    console.log("CAMPANHAS:", campanhas.rows);

    return c.json(campanhas.rows);

  } catch (err) {

    console.error("ERRO CAMPANHAS:", err);

    return c.json({
      error: "Erro ao buscar campanhas"
    }, 500);
  }
});

