// 📊 métricas reais das campanhas
app.get("/meta/metricas-campanhas", authMiddleware, async (c) => {

  try {

    const user: any = c.get("user");

    const conn = await client.query(
      `
      SELECT access_token, conta_anuncios_id
      FROM meta_conexoes
      WHERE usuario_id = $1
      ORDER BY id DESC
      LIMIT 1
      `,
      [user.id]
    );

    const token =
      conn.rows[0]?.access_token || null;

    const contaAnunciosId =
      conn.rows[0]?.conta_anuncios_id || null;

    // Apesar do nome, essa rota e a fonte real de "Minhas Campanhas" pro frontend
    // (carregarCampanhas() chama so ela) — o WHERE abaixo so comparava contra a conta
    // Meta, entao toda campanha Google/TikTok sumia da lista mesmo criada com sucesso
    // (mesmo bug ja corrigido em GET /campanhas, que na pratica nao e usada pela tela).
    const contaAnunciosIdGoogle = await client.query(
      `SELECT dados_conta->>'customer_id' AS id FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'google' LIMIT 1`,
      [user.id]
    ).then(r => r.rows[0]?.id || null);

    const contaAnunciosIdTikTok = await client.query(
      `SELECT dados_conta->>'advertiser_id' AS id FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'tiktok' LIMIT 1`,
      [user.id]
    ).then(r => r.rows[0]?.id || null);

    const contaAnunciosIdLinkedIn = await client.query(
      `SELECT dados_conta->>'ad_account_id' AS id FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'linkedin' LIMIT 1`,
      [user.id]
    ).then(r => r.rows[0]?.id || null);

    // Kwai segue o mesmo padrão — nunca vai bater com nada na prática hoje
    // (nenhuma conexão 'kwai' real existe sem OAuth funcionando, ver
    // OAUTH_PROVEDORES.kwai), mas fica pronto pra quando existir.
    const contaAnunciosIdKwai = await client.query(
      `SELECT dados_conta->>'advertiser_id' AS id FROM plataforma_conexoes WHERE usuario_id = $1 AND plataforma = 'kwai' LIMIT 1`,
      [user.id]
    ).then(r => r.rows[0]?.id || null);

    const campanhas = await client.query(
      `
      SELECT
        c.*,
        ci.tipo_imovel,
        ci.finalidade,
        ci.valor_min,
        ci.valor_max,
        ci.regiao,
        cs.operadora,
        cs.tipo_plano,
        cs.faixa_etaria_min,
        cs.faixa_etaria_max,
        cs.cobertura,
        cs.acomodacao,
        cp.produto,
        cp.objetivo AS objetivo_nicho,
        cp.marca,
        cp.publico_alvo,
        chg.tipo_servico,
        chg.frequencia,
        chg.area_atendida,
        chg.publico_alvo AS publico_alvo_higienizacao,
        ctc.tipo_servico AS tipo_servico_telecom,
        ctc.porte_empresa,
        ctc.situacao_atual,
        ctc.area_atendida AS area_atendida_telecom,
        COALESCE(dono_origem.email,     dono.email)     AS criado_por_email,
        COALESCE(dono_origem.nome,      dono.nome)      AS criado_por_nome,
        COALESCE(dono_origem.sobrenome, dono.sobrenome) AS criado_por_sobrenome,
        COALESCE(
          (
            SELECT json_agg(json_build_object(
              'id', cor.id,
              'nome', cor.nome,
              'sobrenome', cor.sobrenome,
              'email', cor.email
            ))
            FROM campanhas cop
            INNER JOIN usuarios cor
              ON cor.id = cop.usuario_id
            WHERE cop.origem_campanha_id = c.id
          ),
          '[]'
        ) AS corretores_encaminhados,
        COALESCE(
          (
            SELECT json_agg(json_build_object(
              'id', cor.id,
              'nome', cor.nome,
              'sobrenome', cor.sobrenome,
              'email', cor.email,
              'status', ch.status,
              'atualizado_em', ch.atualizado_em
            ) ORDER BY ch.atualizado_em DESC)
            FROM campanha_corretores_historico ch
            INNER JOIN usuarios cor
              ON cor.id = ch.usuario_id
            WHERE ch.campanha_id = c.id
          ),
          '[]'
        ) AS corretores_envio_historico
      FROM campanhas c
      INNER JOIN usuarios dono
        ON dono.id = c.usuario_id
      LEFT JOIN campanhas origem_c
        ON origem_c.id = c.origem_campanha_id
      LEFT JOIN usuarios dono_origem
        ON dono_origem.id = origem_c.usuario_id
      LEFT JOIN campanhas_imoveis ci
        ON ci.campanha_id = c.id
      LEFT JOIN campanhas_saude cs
        ON cs.campanha_id = c.id
      LEFT JOIN campanhas_suplementos cp
        ON cp.campanha_id = c.id
      LEFT JOIN campanhas_higienizacao chg
        ON chg.campanha_id = c.id
      LEFT JOIN campanhas_telecom ctc
        ON ctc.campanha_id = c.id
      WHERE
        c.usuario_id = $1
        AND NOT (
          c.plataforma = 'google'
          AND c.origem = 'plataforma'
          AND UPPER(COALESCE(c.status, '')) IN ('REMOVED', 'DELETED')
          AND c.ad_id IS NULL
        )
        AND (
          c.origem = 'manual'
          OR (COALESCE(c.plataforma, 'meta') = 'meta' AND ($2::text IS NULL OR c.conta_anuncios_id = $2))
          OR (c.plataforma = 'google' AND c.conta_anuncios_id = $3)
          OR (c.plataforma = 'tiktok' AND c.conta_anuncios_id = $4)
          OR (c.plataforma = 'linkedin' AND c.conta_anuncios_id = $5)
          OR (c.plataforma = 'kwai' AND c.conta_anuncios_id = $6)
        )
      ORDER BY c.id DESC
      `,
      [user.id, contaAnunciosId, contaAnunciosIdGoogle, contaAnunciosIdTikTok, contaAnunciosIdLinkedIn, contaAnunciosIdKwai]
    );

    const periodoMetricas = intervaloMetricasCampanhas(30);
    const [metricasGoogle, metricasTikTok, metricasLinkedIn, metricasKwai] = await Promise.all([
      carregarMetricasGoogleCampanhas(
        user.id,
        periodoMetricas.inicio,
        periodoMetricas.fim,
        periodoMetricas.hoje
      ),
      carregarMetricasTikTokCampanhas(
        user.id,
        periodoMetricas.inicio,
        periodoMetricas.fim,
        periodoMetricas.hoje
      ),
      carregarMetricasLinkedInCampanhas(
        user.id,
        periodoMetricas.inicio,
        periodoMetricas.fim,
        periodoMetricas.hoje
      ),
      carregarMetricasKwaiCampanhas(
        user.id,
        periodoMetricas.inicio,
        periodoMetricas.fim,
        periodoMetricas.hoje
      ),
    ]);

    const timeRangeMeta = encodeURIComponent(JSON.stringify({
      since: periodoMetricas.inicio,
      until: periodoMetricas.fim,
    }));

    // 🔥 STATUS DA CONTA (account_status indica problema de pagamento/cobranca)
    let erroPagamentoConta: string | null = null;

    if (token && contaAnunciosId) {
      try {
        const contaInfo = await fetch(
          `https://graph.facebook.com/v19.0/${contaAnunciosId}?fields=account_status,disable_reason,balance,is_prepay_account,funding_source,funding_source_details&access_token=${token}`
        ).then(r => r.json());

        console.log("META ACCOUNT STATUS:", JSON.stringify(contaInfo));

        // 3 = UNSETTLED, 8 = PENDING_SETTLEMENT, 9 = IN_GRACE_PERIOD
        if ([3, 8, 9].includes(Number(contaInfo.account_status))) {
          erroPagamentoConta =
            "Sua conta tem uma pendência financeira registrada na Meta — isso pode acontecer mesmo com saldo disponível, quando a Meta tentou cobrar um método automático e a cobrança falhou. Para resolver: acesse o Gerenciador de Anúncios > Faturamento, verifique se há cobranças em aberto e confirme ou atualize o método de pagamento.";
        } else if (!contaInfo.funding_source) {
          erroPagamentoConta =
            "Nenhum método de pagamento configurado na conta de anúncios. Para resolver: acesse o Gerenciador de Anúncios > Faturamento e adicione um cartão de crédito ou saldo pré-pago para ativar as campanhas.";
        } else if (contaInfo.is_prepay_account) {
          // Conta com saldo pré-pago: o saldo real disponível vem na string
          // "Saldo disponível (R$0,00 BRL)" — o campo "balance" não reflete isso.
          const display: string =
            contaInfo.funding_source_details?.display_string || "";

          const match = display.match(/([\d.,]+)\s*[A-Z]{3}\)/);

          if (match) {
            const saldo = Number(
              match[1].replace(/\./g, "").replace(",", ".")
            );

            if (!Number.isNaN(saldo) && saldo <= 0) {
              erroPagamentoConta =
                "Saldo pré-pago zerado na conta de anúncios. Para resolver: acesse o Gerenciador de Anúncios > Faturamento, clique em 'Adicionar saldo' e insira um valor para os anúncios voltarem a veicular.";
            }
          }
        }
      } catch (e) {
        console.error("ERRO STATUS CONTA:", e);
      }
    }

    // 🔥 ISSUES (ex.: erro de pagamento) de todas as campanhas da conta
    const issuesPorCampanha: Record<string, any[]> = {};

    if (token && contaAnunciosId) {
      try {
        const issuesCampResp = await fetch(
          `https://graph.facebook.com/v19.0/${contaAnunciosId}/campaigns?fields=id,issues_info&limit=500&access_token=${token}`
        ).then(r => r.json());

        console.log("META ISSUES CAMPANHAS:", JSON.stringify(issuesCampResp));

        for (const item of issuesCampResp.data || []) {
          if (item.issues_info?.length) {
            issuesPorCampanha[item.id] = [
              ...(issuesPorCampanha[item.id] || []),
              ...item.issues_info
            ];
          }
        }
      } catch (e) {
        console.error("ERRO ISSUES CAMPANHAS:", e);
      }

      try {
        const issuesAdsetResp = await fetch(
          `https://graph.facebook.com/v19.0/${contaAnunciosId}/adsets?fields=id,campaign_id,issues_info,effective_status&limit=500&access_token=${token}`
        ).then(r => r.json());

        console.log("META ISSUES ADSETS:", JSON.stringify(issuesAdsetResp));

        for (const item of issuesAdsetResp.data || []) {
          if (item.issues_info?.length && item.campaign_id) {
            issuesPorCampanha[item.campaign_id] = [
              ...(issuesPorCampanha[item.campaign_id] || []),
              ...item.issues_info
            ];
          }
        }
      } catch (e) {
        console.error("ERRO ISSUES ADSETS:", e);
      }
    }

    // 🔥 VEICULAÇÃO (status detalhado dos anúncios, igual ao Gerenciador de Anúncios)
    const veiculacaoPorCampanha: Record<string, string> = {};

    if (token && contaAnunciosId) {
      try {
        const adsResp = await fetch(
          `https://graph.facebook.com/v19.0/${contaAnunciosId}/ads?fields=id,campaign_id,effective_status&limit=500&access_token=${token}`
        ).then(r => r.json());

        console.log("META ADS EFFECTIVE STATUS:", JSON.stringify(adsResp));

        const prioridade = [
          "WITH_ISSUES",
          "DISAPPROVED",
          "PENDING_BILLING_INFO",
          "PENDING_REVIEW",
          "IN_PROCESS",
          "PREAPPROVED",
          "ADSET_PAUSED",
          "CAMPAIGN_PAUSED",
          "PAUSED",
          "ACTIVE",
          "ARCHIVED",
          "DELETED"
        ];

        const statusPorCampanha: Record<string, string[]> = {};

        for (const ad of adsResp.data || []) {
          if (!ad.campaign_id || !ad.effective_status) continue;

          statusPorCampanha[ad.campaign_id] =
            statusPorCampanha[ad.campaign_id] || [];
          statusPorCampanha[ad.campaign_id].push(ad.effective_status);
        }

        for (const [campaignId, statuses] of Object.entries(statusPorCampanha)) {
          const melhorStatus = prioridade.find(p => statuses.includes(p));
          if (melhorStatus) {
            veiculacaoPorCampanha[campaignId] = melhorStatus;
          }
        }
      } catch (e) {
        console.error("ERRO ADS EFFECTIVE STATUS:", e);
      }
    }

    // Detecção de nicho por nome para campanhas sem nicho_id no BD
    const userNichos = (user.nichos || []) as Array<{id: number; slug: string; nome: string; cor: string}>;
    if (userNichos.length > 0) {
      const norm = (t: string) =>
        String(t).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
      const saasNicho = userNichos.find(n => n.slug === "saas" || norm(n.nome).includes("saas") || norm(n.nome).includes("plataforma"));
      for (const c of campanhas.rows as any[]) {
        // Migra nicho legado "Plataforma" para o nicho SaaS atual do usuário
        if (saasNicho && c.nicho_nome && /^plataforma$/i.test(c.nicho_nome.trim())) {
          c.nicho_id   = saasNicho.id;
          c.nicho_slug = saasNicho.slug;
          c.nicho_nome = saasNicho.nome;
          c.nicho_cor  = saasNicho.cor;
          continue;
        }
        if (c.nicho_id || c.nicho_slug) continue;
        const nomeLower = norm(c.nome || "");
        for (const nicho of userNichos) {
          const nichoNomeLower = norm(nicho.nome || "");
          if (nomeLower.includes(nichoNomeLower) || nomeLower.includes(nicho.slug)) {
            c.nicho_id   = nicho.id;
            c.nicho_slug = nicho.slug;
            c.nicho_nome = nicho.nome;
            c.nicho_cor  = nicho.cor;
            break;
          }
        }
      }
    }

    const metricas = [];

    for (const campanha of campanhas.rows) {

      let dados: any = {};
      let grafico: any[] = [];
      let gastoHojeCampanha = 0;
      let metaDisponivel = false;
      let erroMeta: string | null = null;

      const plataformaCampanha = String(campanha.plataforma || "meta").toLowerCase();

      if (
        token &&
        campanha.campaign_id &&
        plataformaCampanha === "meta" &&
        String(campanha.status || "").toUpperCase() !== "DELETED"
      ) {
        try {
          const [insightsTotais, insightsGrafico, insightsHoje] = await Promise.all([
            fetch(
              `https://graph.facebook.com/v19.0/${campanha.campaign_id}/insights?fields=impressions,clicks,spend,cpc,ctr,reach,actions,cost_per_action_type&time_range=${timeRangeMeta}&access_token=${token}`
            ).then(r => r.json()),
            fetch(
              `https://graph.facebook.com/v19.0/${campanha.campaign_id}/insights?fields=impressions,clicks,spend,ctr&time_increment=1&time_range=${timeRangeMeta}&access_token=${token}`
            ).then(r => r.json()),
            fetch(
              `https://graph.facebook.com/v19.0/${campanha.campaign_id}/insights?fields=spend&date_preset=today&access_token=${token}`
            ).then(r => r.json())
          ]);

          if (insightsTotais.error) {
            erroMeta =
              insightsTotais.error.message ||
              "Métricas indisponíveis na Meta";
          } else {
            dados = insightsTotais.data?.[0] || {};

            const diasGrafico = insightsGrafico.data || [];

            grafico = diasGrafico.map((d: any) => ({
              data: d.date_start,
              clicks: Number(d.clicks || 0),
              ctr: Number(d.ctr || 0),
              gasto: Number(d.spend || 0),
              impressoes: Number(d.impressions || 0)
            }));

            gastoHojeCampanha = Number(insightsHoje.data?.[0]?.spend || 0);

            metaDisponivel = true;
          }
        } catch {
          erroMeta = "Métricas indisponíveis na Meta";
        }
      } else if (campanha.campaign_id && plataformaCampanha === "google") {
        if (metricasGoogle.disponivel) {
          const metrica =
            metricasGoogle.metricas.get(String(campanha.campaign_id)) ||
            metricasCampanhaVazias();
          dados = {
            impressions: metrica.impressoes,
            clicks: metrica.cliques,
            reach: metrica.alcance,
            spend: metrica.gasto,
            cpc: metrica.cpc,
            ctr: metrica.ctr,
          };
          grafico = metrica.grafico;
          gastoHojeCampanha = metrica.gasto_hoje;
          metaDisponivel = true;
        } else {
          erroMeta = metricasGoogle.erro;
        }
      } else if (campanha.campaign_id && plataformaCampanha === "tiktok") {
        if (metricasTikTok.disponivel) {
          const metrica =
            metricasTikTok.metricas.get(String(campanha.campaign_id)) ||
            metricasCampanhaVazias();
          dados = {
            impressions: metrica.impressoes,
            clicks: metrica.cliques,
            reach: metrica.alcance,
            spend: metrica.gasto,
            cpc: metrica.cpc,
            ctr: metrica.ctr,
          };
          grafico = metrica.grafico;
          gastoHojeCampanha = metrica.gasto_hoje;
          metaDisponivel = true;
        } else {
          erroMeta = metricasTikTok.erro;
        }
      } else if (campanha.campaign_id && plataformaCampanha === "linkedin") {
        if (metricasLinkedIn.disponivel) {
          const metrica =
            metricasLinkedIn.metricas.get(String(campanha.campaign_id)) ||
            metricasCampanhaVazias();
          dados = {
            impressions: metrica.impressoes,
            clicks: metrica.cliques,
            reach: metrica.alcance,
            spend: metrica.gasto,
            cpc: metrica.cpc,
            ctr: metrica.ctr,
          };
          grafico = metrica.grafico;
          gastoHojeCampanha = metrica.gasto_hoje;
          metaDisponivel = true;
        } else {
          erroMeta = metricasLinkedIn.erro;
        }
      } else if (campanha.campaign_id && plataformaCampanha === "kwai") {
        if (metricasKwai.disponivel) {
          const metrica =
            metricasKwai.metricas.get(String(campanha.campaign_id)) ||
            metricasCampanhaVazias();
          dados = {
            impressions: metrica.impressoes,
            clicks: metrica.cliques,
            reach: metrica.alcance,
            spend: metrica.gasto,
            cpc: metrica.cpc,
            ctr: metrica.ctr,
          };
          grafico = metrica.grafico;
          gastoHojeCampanha = metrica.gasto_hoje;
          metaDisponivel = true;
        } else {
          erroMeta = metricasKwai.erro;
        }
      }

      // ✅ LEADS REAIS DO BANCO
      const leadsBanco = await client.query(
        `
        SELECT COUNT(*) AS total
        FROM leads
        WHERE usuario_id = $1
        AND campanha = $2
        AND conta_anuncios_id = $3
        `,
        [
          user.id,
          campanha.nome,
          campanha.conta_anuncios_id
        ]
      );

      const totalLeadsBanco =
        Number(leadsBanco.rows[0]?.total || 0);

      // 🔥 ERRO DE PAGAMENTO REPORTADO PELA META
      const issuesCampanha =
        issuesPorCampanha[campanha.campaign_id] || [];

      const issuePagamento = issuesCampanha.find((i: any) =>
        /pagamento|payment|billing|cobran/i.test(
          `${i.error_summary || ""} ${i.error_message || ""}`
        )
      );

      const campanhaAtiva =
        ["ACTIVE", "ENABLED"].includes(
          String(campanha.status || "").toUpperCase()
        );

      // erroPagamentoConta/issuesPorCampanha vem inteiramente da conta de anuncios
      // Meta (contaAnunciosId) — sem este filtro, uma campanha Google/TikTok ativa
      // herdava o aviso de faturamento da conta Meta do usuario, mesmo sem nenhuma
      // relacao com ela.
      const campanhaEhMeta =
        (campanha.plataforma || "meta") === "meta";

      const mensagemErroPagamento =
        campanhaEhMeta
          ? (issuePagamento &&
              (issuePagamento.error_summary || issuePagamento.error_message)) ||
            (campanhaAtiva ? erroPagamentoConta : null)
          : null;

      // 🔥 VEICULAÇÃO (status detalhado igual ao Gerenciador de Anúncios)
      const veiculacaoStatus =
        veiculacaoPorCampanha[campanha.campaign_id] || null;

      // Corrige divergência de status entre banco e Meta automaticamente.
      // Ex.: usuário pausou direto na Meta → banco ainda mostra ACTIVE.
      const statusMetaCampanha =
        veiculacaoStatus === "CAMPAIGN_PAUSED" ? "PAUSED"
        : veiculacaoStatus === "ACTIVE"        ? "ACTIVE"
        : null;

      if (
        statusMetaCampanha &&
        statusMetaCampanha !== String(campanha.status || "").toUpperCase()
      ) {
        client.query(
          `UPDATE campanhas SET status = $1, atualizado_em = NOW() WHERE id = $2`,
          [statusMetaCampanha, campanha.id]
        ).catch(() => {});
        campanha.status = statusMetaCampanha;
      }

      const diagnosticoVeiculacao =
        diagnosticarVeiculacaoMeta(
          veiculacaoStatus,
          issuesCampanha,
          mensagemErroPagamento || (campanhaEhMeta ? erroPagamentoConta : null),
          campanha.status
        );

      // Persiste nicho detectado pelas tabelas de detalhe ou leads
      if (!campanha.nicho_id && campanha.nicho_slug) {
        client.query(
          `UPDATE campanhas SET nicho_id = (SELECT id FROM nichos WHERE slug = $1 LIMIT 1) WHERE id = $2`,
          [campanha.nicho_slug, campanha.id]
        ).catch(() => {});
      }

      console.log(
        "ERRO PAGAMENTO CAMPANHA:",
        campanha.nome,
        "status:", campanha.status,
        "campanhaAtiva:", campanhaAtiva,
        "erroPagamentoConta:", erroPagamentoConta,
        "mensagemErroPagamento:", mensagemErroPagamento
      );

      const configuracoesCampanha = {
        ...(campanha.configuracoes_avancadas || {}),
        tipo_imovel: campanha.tipo_imovel ?? campanha.configuracoes_avancadas?.tipo_imovel,
        finalidade: campanha.finalidade ?? campanha.configuracoes_avancadas?.finalidade,
        valor_min: campanha.valor_min ?? campanha.configuracoes_avancadas?.valor_min,
        valor_max: campanha.valor_max ?? campanha.configuracoes_avancadas?.valor_max,
        regiao: campanha.regiao ?? campanha.configuracoes_avancadas?.regiao,
        operadora: campanha.operadora ?? campanha.configuracoes_avancadas?.operadora,
        tipo_plano: campanha.tipo_plano ?? campanha.configuracoes_avancadas?.tipo_plano,
        faixa_etaria_min: campanha.faixa_etaria_min ?? campanha.configuracoes_avancadas?.faixa_etaria_min,
        faixa_etaria_max: campanha.faixa_etaria_max ?? campanha.configuracoes_avancadas?.faixa_etaria_max,
        cobertura: campanha.cobertura ?? campanha.configuracoes_avancadas?.cobertura,
        acomodacao: campanha.acomodacao ?? campanha.configuracoes_avancadas?.acomodacao,
        produto: campanha.produto ?? campanha.configuracoes_avancadas?.produto,
        objetivo: campanha.objetivo_nicho ?? campanha.configuracoes_avancadas?.objetivo,
        marca: campanha.marca ?? campanha.configuracoes_avancadas?.marca,
        publico_alvo: campanha.publico_alvo ?? campanha.publico_alvo_higienizacao ?? campanha.configuracoes_avancadas?.publico_alvo,
        tipo_servico: campanha.tipo_servico ?? campanha.tipo_servico_telecom ?? campanha.configuracoes_avancadas?.tipo_servico,
        frequencia: campanha.frequencia ?? campanha.configuracoes_avancadas?.frequencia,
        area_atendida: campanha.area_atendida ?? campanha.area_atendida_telecom ?? campanha.configuracoes_avancadas?.area_atendida,
        porte_empresa: campanha.porte_empresa ?? campanha.configuracoes_avancadas?.porte_empresa,
        situacao_atual: campanha.situacao_atual ?? campanha.configuracoes_avancadas?.situacao_atual
      };

      metricas.push({
        id: campanha.id,
        nome: campanha.nome,
        status: campanha.status,
        origem: campanha.origem,
        plataforma: campanha.plataforma || "meta",
        campaign_id: campanha.campaign_id,
        adset_id: campanha.adset_id,
        ad_id: campanha.ad_id,
        form_id: campanha.form_id,
        destino_editavel:
          !campanha.adset_id && !campanha.ad_id,
        criada_por_usuario_id: campanha.usuario_id,
        criada_por_email: campanha.criado_por_email,
        criada_por_nome:
          [
            campanha.criado_por_nome,
            campanha.criado_por_sobrenome
          ].filter(Boolean).join(" ") || null,
        corretores_encaminhados:
          (campanha.corretores_encaminhados || []).map((cor: any) => ({
            id: cor.id,
            email: cor.email,
            nome:
              [cor.nome, cor.sobrenome]
                .filter(Boolean).join(" ") || cor.email
          })),
        corretores_envio_historico:
          (campanha.corretores_envio_historico || []).map((cor: any) => ({
            id: cor.id,
            email: cor.email,
            status: cor.status,
            atualizado_em: cor.atualizado_em,
            nome:
              [cor.nome, cor.sobrenome]
                .filter(Boolean).join(" ") || cor.email
          })),
        recebida_por_encaminhamento:
          Boolean(campanha.origem_campanha_id),
        rascunho_local:
          String(campanha.origem || "").toLowerCase() === "manual" ||
          (!campanha.adset_id && !campanha.ad_id) ||
          (!campanha.campaign_id && !metaDisponivel),
        configuracoes_avancadas:
          configuracoesCampanha,
        daily_budget:
          campanha.daily_budget || null,

        impressoes: dados.impressions || 0,
        cliques: dados.clicks || 0,
        alcance: dados.reach || 0,
        gasto: dados.spend || 0,
        gasto_hoje: gastoHojeCampanha,
        cpc: dados.cpc || 0,
        ctr: dados.ctr || 0,

        // 🔥 agora vem da sua plataforma
        leads: totalLeadsBanco,

        grafico,
        criado_em: campanha.criado_em,
        metricas_origem: metaDisponivel ? plataformaCampanha : "local",
        meta_disponivel: metaDisponivel,
        erro_meta: erroMeta,
        erro_publicacao:
          campanha.configuracoes_avancadas?.ultimo_erro_publicacao || null,
        erro_pagamento: mensagemErroPagamento || null,
        veiculacao: veiculacaoStatus,
        veiculacao_label: traduzirVeiculacaoMeta(veiculacaoStatus),
        veiculacao_tipo: diagnosticoVeiculacao.tipo,
        veiculacao_subcategoria: diagnosticoVeiculacao.subcategoria,
        veiculacao_motivo: diagnosticoVeiculacao.motivo,
        veiculacao_acao: diagnosticoVeiculacao.acao,
        veiculacao_acao_passos: diagnosticoVeiculacao.acao_passos,
        veiculacao_acao_url: urlAcaoVeiculacaoMeta(
          diagnosticoVeiculacao.subcategoria,
          campanha.campaign_id || null,
          campanha.conta_anuncios_id || null
        ),
        veiculacao_detalhes: diagnosticoVeiculacao.detalhes,
        conta_anuncios_id: campanha.conta_anuncios_id || null,
        nicho_id: campanha.nicho_id || null,
        nicho_slug: campanha.nicho_slug || null,
        nicho_nome: campanha.nicho_nome || null,
        nicho_cor: campanha.nicho_cor || null
      });
    }

    return c.json(metricas);

  } catch (err) {

    console.error("ERRO MÉTRICAS:", err);

    return c.json({
      error: "Erro ao buscar métricas"
    }, 500);
  }
});

// 🔄 sincroniza campanhas + leads da Meta
app.get("/meta/performance-diaria", authMiddleware, async (c) => {

  try {

    const user: any = c.get("user");

    const periodoParam =
      String(c.req.query("periodo") || "semanal")
        .toLowerCase();

    const periodo =
      ["semanal", "mensal", "anual"].includes(periodoParam)
        ? periodoParam
        : "semanal";

    const dias =
      periodo === "anual"
        ? 365
        : periodo === "mensal"
        ? 30
        : 7;

    const conn = await client.query(
      `
      SELECT access_token, conta_anuncios_id
      FROM meta_conexoes
      WHERE usuario_id = $1
      ORDER BY id DESC
      LIMIT 1
      `,
      [user.id]
    );

    if (conn.rows.length === 0) {
      return c.json({
        error: "Meta nao conectada"
      }, 400);
    }

    const token = conn.rows[0].access_token;

    const contaAds =
      await obterContaAnuncios(
        token,
        conn.rows[0].conta_anuncios_id
      );

    if (!contaAds) {
      return c.json({
        error: "Nenhuma conta de anuncios encontrada"
      }, 400);
    }

    const adAccountId = contaAds.id;

    const campaignIdsUsuario =
      await listarCampaignIdsMetaDoUsuario(
        Number(user.id),
        adAccountId
      );

    const inicio = new Date();
    inicio.setDate(inicio.getDate() - (dias - 1));
    inicio.setHours(0, 0, 0, 0);

    const fim = new Date();
    fim.setHours(23, 59, 59, 999);

    const since =
      inicio.toISOString().slice(0, 10);

    const until =
      fim.toISOString().slice(0, 10);

    const timeRange =
      encodeURIComponent(
        JSON.stringify({
          since,
          until
        })
      );

    const insights = await fetch(
      `https://graph.facebook.com/v19.0/${adAccountId}/insights?fields=campaign_id,spend,actions,impressions,clicks,reach&level=campaign&time_increment=1&time_range=${timeRange}&access_token=${token}`
    ).then(r => r.json());

    if (insights.error) {
      return c.json({
        error: "Erro ao buscar performance na Meta",
        detalhe: insights.error
      }, 400);
    }

    const leadsBanco = await client.query(
      `
      SELECT
        DATE(criado_em) AS dia,
        COUNT(*) AS total
      FROM leads
      WHERE usuario_id = $1
      AND conta_anuncios_id = $2
      AND criado_em >= $3
      GROUP BY DATE(criado_em)
      `,
      [
        user.id,
        adAccountId,
        inicio
      ]
    );

    const leadsBancoPorDia = new Map(
      leadsBanco.rows.map((row: any) => [
        new Date(row.dia)
          .toISOString()
          .slice(0, 10),
        Number(row.total || 0)
      ])
    );

    const metaPorDia = new Map();

    for (const linha of insights.data || []) {
      const campaignId =
        String(linha.campaign_id || "");

      if (!campaignIdsUsuario.has(campaignId)) {
        continue;
      }

      const dataLinha =
        linha.date_start;

      const atual =
        metaPorDia.get(dataLinha) || {
          date_start: dataLinha,
          spend: 0,
          leads: 0,
          clicks: 0,
          impressions: 0,
          reach: 0
        };

      atual.spend += Number(linha.spend || 0);
      atual.leads += extrairLeadsActionsMeta(linha.actions || []);
      atual.clicks += Number(linha.clicks || 0);
      atual.impressions += Number(linha.impressions || 0);
      atual.reach += Number(linha.reach || 0);

      metaPorDia.set(dataLinha, atual);
    }

    const datasPeriodo = Array.from(
      { length: dias },
      (_, index) => {
        const data = new Date(inicio);
        data.setDate(inicio.getDate() + index);
        return data.toISOString().slice(0, 10);
      }
    );

    const diasPerformance = datasPeriodo
      .map((data) => {
        const linha: any =
          metaPorDia.get(data) || {};
        const gasto =
          Number(linha.spend || 0);
        const leadsMeta =
          Number(linha.leads || 0);
        const leadsPlataforma =
          leadsBancoPorDia.get(data) || 0;
        const leads =
          leadsMeta;

        return {
          data,
          gasto,
          leads,
          leads_meta: leadsMeta,
          leads_plataforma: leadsPlataforma,
          custo_por_lead:
            leads > 0
              ? gasto / leads
              : null,
          cliques: Number(linha.clicks || 0),
          impressoes: Number(linha.impressions || 0),
          alcance: Number(linha.reach || 0)
        };
      });

    const totalGasto =
      diasPerformance.reduce(
        (total: number, dia: any) =>
          total + dia.gasto,
        0
      );

    const totalLeads =
      diasPerformance.reduce(
        (total: number, dia: any) =>
          total + dia.leads,
        0
      );

    const totalLeadsPlataforma =
      diasPerformance.reduce(
        (total: number, dia: any) =>
          total + (dia.leads_plataforma || 0),
        0
      );

    const hoje =
      diasPerformance[diasPerformance.length - 1] || null;

    // Tendência calculada com calcularTendenciaCPL (janela de dias, não só "hoje" contra
    // o resto) — ver definição da função para o motivo: um único dia costuma ter poucos
    // leads (às vezes 1), o que fazia esse percentual oscilar demais pra ser confiável.
    const { media_cpl_anterior: mediaCplAnterior, economia_percentual: economiaPercentual } =
      calcularTendenciaCPL(diasPerformance);

    const registros =
      periodo === "anual"
        ? Object.values(
            diasPerformance.reduce((acc: any, dia: any) => {
              const chave =
                dia.data.slice(0, 7);

              if (!acc[chave]) {
                acc[chave] = {
                  periodo: chave,
                  data: chave,
                  gasto: 0,
                  leads: 0,
                  leads_meta: 0,
                  leads_plataforma: 0,
                  cliques: 0,
                  impressoes: 0,
                  alcance: 0,
                  custo_por_lead: null
                };
              }

              acc[chave].gasto += dia.gasto;
              acc[chave].leads += dia.leads;
              acc[chave].leads_meta += dia.leads_meta;
              acc[chave].leads_plataforma += dia.leads_plataforma;
              acc[chave].cliques += dia.cliques;
              acc[chave].impressoes += dia.impressoes;
              acc[chave].alcance += dia.alcance;
              acc[chave].custo_por_lead =
                acc[chave].leads > 0
                  ? acc[chave].gasto / acc[chave].leads
                  : null;

              return acc;
            }, {})
          )
        : diasPerformance;

    return c.json({
      conta_anuncios: {
        id: contaAds.id,
        nome: contaAds.name,
        moeda: contaAds.currency || "BRL"
      },
      periodo,
      periodo_dias: dias,
      periodo_inicio: since,
      periodo_fim: until,
      agrupamento:
        periodo === "anual"
          ? "mensal"
          : "diario",
      resumo: {
        gasto_total: totalGasto,
        leads_total: totalLeads,
        leads_total_plataforma: totalLeadsPlataforma,
        custo_por_lead_medio:
          totalLeads > 0
            ? totalGasto / totalLeads
            : null,
        hoje,
        media_cpl_anterior: mediaCplAnterior,
        economia_percentual: economiaPercentual,
        status:
          economiaPercentual === null
            ? "dados_insuficientes"
            : economiaPercentual >= 0
            ? "melhor_que_media"
            : "acima_da_media"
      },
      dias: diasPerformance,
      registros
    });

  } catch (err: any) {

    console.error(
      "ERRO PERFORMANCE DIARIA:",
      err
    );

    return c.json({
      error: "Erro ao buscar performance diaria",
      detalhe: err?.message || err
    }, 500);
  }
});

// Resumo (comparativo com o CPL médio anterior) + agrupamento mensal (quando periodo=anual),
// compartilhado por /google/performance-diaria e /tiktok/performance-diaria — mesma lógica que
// /meta/performance-diaria já usa inline, extraída aqui só para as duas rotas novas (a rota da
// Meta foi deixada como está, já em produção, pra não arriscar quebrar o que já funciona).
// Compara a média de CPL dos últimos `tamanhoJanela` dias (padrão 3) contra a média do
// restante do período, em vez de "só hoje" contra o resto. Motivo: um único dia
// normalmente tem poucos leads (às vezes 1) — CPL calculado sobre uma amostra tão pequena
// oscila muito de uma hora pra outra conforme o gasto do dia acumula sem lead novo ainda,
// o que fazia esse percentual de "tendência" pular de forma enganosa (ex: 27% pior virar
// 30% pior em poucos minutos, sem nenhuma mudança real na campanha). Uma janela de alguns
// dias suaviza esse ruído de amostra pequena sem deixar de mostrar uma tendência real.
function calcularTendenciaCPL(diasPerformance: any[], tamanhoJanela = 3) {
  if (diasPerformance.length <= tamanhoJanela) {
    return { media_cpl_anterior: null, economia_percentual: null };
  }

  const janelaRecente = diasPerformance.slice(-tamanhoJanela);
  const janelaAnterior = diasPerformance.slice(0, -tamanhoJanela);

  const somar = (dias: any[], campo: string) =>
    dias.reduce((total: number, dia: any) => total + (dia[campo] || 0), 0);

  const gastoRecente = somar(janelaRecente, "gasto");
  const leadsRecente = somar(janelaRecente, "leads");
  const gastoAnterior = somar(janelaAnterior, "gasto");
  const leadsAnterior = somar(janelaAnterior, "leads");

  const cplRecente = leadsRecente > 0 ? gastoRecente / leadsRecente : null;
  const mediaCplAnterior = leadsAnterior > 0 ? gastoAnterior / leadsAnterior : null;

  const economiaPercentual =
    mediaCplAnterior && cplRecente
      ? ((mediaCplAnterior - cplRecente) / mediaCplAnterior) * 100
      : null;

  return { media_cpl_anterior: mediaCplAnterior, economia_percentual: economiaPercentual };
}

function montarResumoPerformanceDiaria(diasPerformance: any[], periodo: string) {
  const totalGasto = diasPerformance.reduce((total, dia) => total + dia.gasto, 0);
  const totalLeads = diasPerformance.reduce((total, dia) => total + dia.leads, 0);

  const hoje = diasPerformance[diasPerformance.length - 1] || null;
  const { media_cpl_anterior: mediaCplAnterior, economia_percentual: economiaPercentual } =
    calcularTendenciaCPL(diasPerformance);

  const registros =
    periodo === "anual"
      ? Object.values(
          diasPerformance.reduce((acc: any, dia: any) => {
            const chave = dia.data.slice(0, 7);
            if (!acc[chave]) {
              acc[chave] = {
                periodo: chave, data: chave, gasto: 0, leads: 0,
                leads_meta: null, leads_plataforma: 0,
                cliques: 0, impressoes: 0, alcance: 0, custo_por_lead: null,
              };
            }
            acc[chave].gasto += dia.gasto;
            acc[chave].leads += dia.leads;
            acc[chave].leads_plataforma += dia.leads_plataforma;
            acc[chave].cliques += dia.cliques;
            acc[chave].impressoes += dia.impressoes;
            acc[chave].alcance += dia.alcance || 0;
            acc[chave].custo_por_lead = acc[chave].leads > 0 ? acc[chave].gasto / acc[chave].leads : null;
            return acc;
          }, {})
        )
      : diasPerformance;

  return {
    resumo: {
      gasto_total: totalGasto,
      leads_total: totalLeads,
      leads_total_plataforma: totalLeads,
      custo_por_lead_medio: totalLeads > 0 ? totalGasto / totalLeads : null,
      hoje,
      media_cpl_anterior: mediaCplAnterior,
      economia_percentual: economiaPercentual,
      status:
        economiaPercentual === null ? "dados_insuficientes"
        : economiaPercentual >= 0 ? "melhor_que_media"
        : "acima_da_media",
    },
    registros,
  };
}

// Mesmo formato de resposta de /meta/performance-diaria (conta_anuncios, resumo, dias, registros),
// pra reaproveitar a mesma renderização no frontend. Diferença deliberada: aqui não existe um
// "leads que o Google registrou" pra comparar com os leads reais (ao contrário da Meta, cujo
// campo `actions` do Graph API dá esse número) — leads_meta fica null e o único número de leads
// mostrado é o real, salvo na Central de Leads. Ver conversa com o Milton sobre a confusão que o
// par "Leads (Meta) / Leads (Plataforma)" causava: pra Google/TikTok, evitamos criar esse mesmo
// par com um número "reportado pela plataforma" que nem é totalmente confiável pra começo de conversa.
app.get("/google/performance-diaria", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");

    const periodoParam = String(c.req.query("periodo") || "semanal").toLowerCase();
    const periodo = ["semanal", "mensal", "anual"].includes(periodoParam) ? periodoParam : "semanal";
    const dias = periodo === "anual" ? 365 : periodo === "mensal" ? 30 : 7;

    if (!Bun.env.GOOGLE_ADS_DEVELOPER_TOKEN) {
      return c.json({ error: "Google Ads nao configurado" }, 400);
    }

    const conn = await client.query(
      `SELECT refresh_token, dados_conta FROM plataforma_conexoes
       WHERE usuario_id = $1 AND plataforma = 'google' LIMIT 1`,
      [user.id]
    );
    const row = conn.rows[0];
    const customerId = row?.dados_conta?.customer_id;
    const loginCustomerId = row?.dados_conta?.login_customer_id || null;

    if (!row?.refresh_token || !customerId) {
      return c.json({ error: "Google Ads nao conectado" }, 400);
    }

    const inicio = new Date();
    inicio.setDate(inicio.getDate() - (dias - 1));
    inicio.setHours(0, 0, 0, 0);
    const fim = new Date();
    fim.setHours(23, 59, 59, 999);
    const since = inicio.toISOString().slice(0, 10);
    const until = fim.toISOString().slice(0, 10);

    const accessToken = await obterAccessTokenGoogle(row.refresh_token);

    // Mesmo filtro que a Meta já faz (só soma gasto de campanhas criadas por essa plataforma,
    // não a conta inteira) — evita mostrar gasto de campanhas do Google Ads que nunca passaram
    // por aqui.
    const campanhaIdsResult = await client.query(
      `SELECT DISTINCT campaign_id FROM campanhas
       WHERE usuario_id = $1 AND plataforma = 'google' AND campaign_id IS NOT NULL
         AND COALESCE(status, '') <> 'DELETED'`,
      [user.id]
    );
    const campaignIdsUsuario = new Set(campanhaIdsResult.rows.map((r: any) => String(r.campaign_id)));

    let contaInfo: any = null;
    try {
      const contaResults = await googleAdsQuery(
        customerId, accessToken,
        "SELECT customer.descriptive_name, customer.currency_code FROM customer LIMIT 1",
        loginCustomerId
      );
      contaInfo = (contaResults[0] as any)?.customer ?? null;
    } catch (_) {}

    const googlePorDia = new Map<string, { spend: number; clicks: number; impressions: number; reach: number }>();

    if (campaignIdsUsuario.size > 0) {
      const resultados = await googleAdsQuery(
        customerId, accessToken,
        `SELECT campaign.id, segments.date, metrics.impressions, metrics.clicks, metrics.cost_micros
         FROM campaign WHERE segments.date BETWEEN '${since}' AND '${until}'`,
        loginCustomerId
      );
      for (const item of resultados as any[]) {
        const campaignId = String((item as any).campaign?.id || "");
        if (!campaignIdsUsuario.has(campaignId)) continue;
        const data = String((item as any).segments?.date || "");
        const atual = googlePorDia.get(data) || { spend: 0, clicks: 0, impressions: 0, reach: 0 };
        atual.spend += Number((item as any).metrics?.costMicros || 0) / 1_000_000;
        atual.clicks += Number((item as any).metrics?.clicks || 0);
        atual.impressions += Number((item as any).metrics?.impressions || 0);
        googlePorDia.set(data, atual);
      }

      // Alcance (unique_users) só existe pra alguns tipos de campanha no Google — best-effort,
      // mesmo padrão de tolerância a falha já usado em carregarMetricasGoogleCampanhas.
      try {
        const alcanceResultados = await googleAdsQuery(
          customerId, accessToken,
          `SELECT segments.date, metrics.unique_users, campaign.id
           FROM campaign WHERE segments.date BETWEEN '${since}' AND '${until}'`,
          loginCustomerId
        );
        for (const item of alcanceResultados as any[]) {
          const campaignId = String((item as any).campaign?.id || "");
          if (!campaignIdsUsuario.has(campaignId)) continue;
          const data = String((item as any).segments?.date || "");
          const atual = googlePorDia.get(data);
          if (atual) atual.reach += Number((item as any).metrics?.uniqueUsers || 0);
        }
      } catch (_) {}
    }

    const leadsBanco = await client.query(
      `SELECT DATE(criado_em) AS dia, COUNT(*) AS total
       FROM leads WHERE usuario_id = $1 AND plataforma = 'google' AND criado_em >= $2
       GROUP BY DATE(criado_em)`,
      [user.id, inicio]
    );
    const leadsBancoPorDia = new Map(
      leadsBanco.rows.map((r: any) => [new Date(r.dia).toISOString().slice(0, 10), Number(r.total || 0)])
    );

    const datasPeriodo = Array.from({ length: dias }, (_, index) => {
      const data = new Date(inicio);
      data.setDate(inicio.getDate() + index);
      return data.toISOString().slice(0, 10);
    });

    const diasPerformance = datasPeriodo.map((data) => {
      const linha = googlePorDia.get(data) || { spend: 0, clicks: 0, impressions: 0, reach: 0 };
      const leadsPlataforma = leadsBancoPorDia.get(data) || 0;
      const gasto = Number(linha.spend || 0);
      return {
        data,
        gasto,
        leads: leadsPlataforma,
        leads_meta: null,
        leads_plataforma: leadsPlataforma,
        custo_por_lead: leadsPlataforma > 0 ? gasto / leadsPlataforma : null,
        cliques: Number(linha.clicks || 0),
        impressoes: Number(linha.impressions || 0),
        alcance: Number(linha.reach || 0),
      };
    });

    const { resumo, registros } = montarResumoPerformanceDiaria(diasPerformance, periodo);

    return c.json({
      conta_anuncios: {
        id: customerId,
        nome: contaInfo?.descriptiveName || customerId,
        moeda: contaInfo?.currencyCode || "BRL",
      },
      periodo,
      periodo_dias: dias,
      periodo_inicio: since,
      periodo_fim: until,
      agrupamento: periodo === "anual" ? "mensal" : "diario",
      resumo,
      dias: diasPerformance,
      registros,
    });
  } catch (err: any) {
    console.error("ERRO PERFORMANCE DIARIA GOOGLE:", err);
    return c.json({ error: "Erro ao buscar performance diaria do Google Ads", detalhe: err?.message || err }, 500);
  }
});

// Mesmo racional do /google/performance-diaria acima (mesmo formato de resposta, leads_meta
// sempre null). Reaproveita relatorioTikTokCampanhas (já usada por carregarMetricasTikTokCampanhas)
// em vez de montar uma chamada nova à Report API do TikTok.
app.get("/tiktok/performance-diaria", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");

    const periodoParam = String(c.req.query("periodo") || "semanal").toLowerCase();
    const periodo = ["semanal", "mensal", "anual"].includes(periodoParam) ? periodoParam : "semanal";
    const dias = periodo === "anual" ? 365 : periodo === "mensal" ? 30 : 7;

    const conn = await client.query(
      `SELECT access_token, dados_conta FROM plataforma_conexoes
       WHERE usuario_id = $1 AND plataforma = 'tiktok' LIMIT 1`,
      [user.id]
    );
    const row = conn.rows[0];
    const advertiserId = row?.dados_conta?.advertiser_id;
    if (!row?.access_token || !advertiserId) {
      return c.json({ error: "TikTok Ads nao conectado" }, 400);
    }

    const inicio = new Date();
    inicio.setDate(inicio.getDate() - (dias - 1));
    inicio.setHours(0, 0, 0, 0);
    const fim = new Date();
    fim.setHours(23, 59, 59, 999);
    const since = inicio.toISOString().slice(0, 10);
    const until = fim.toISOString().slice(0, 10);

    const campanhaIdsResult = await client.query(
      `SELECT DISTINCT campaign_id FROM campanhas
       WHERE usuario_id = $1 AND plataforma = 'tiktok' AND campaign_id IS NOT NULL
         AND COALESCE(status, '') <> 'DELETED'`,
      [user.id]
    );
    const campaignIdsUsuario = new Set(campanhaIdsResult.rows.map((r: any) => String(r.campaign_id)));

    const tiktokPorDia = new Map<string, { spend: number; clicks: number; impressions: number; reach: number }>();

    if (campaignIdsUsuario.size > 0) {
      const registros = await relatorioTikTokCampanhas(
        row.access_token, String(advertiserId), since, until, ["campaign_id", "stat_time_day"]
      );
      for (const item of registros) {
        const campaignId = String(item.dimensions?.campaign_id || "");
        if (!campaignIdsUsuario.has(campaignId)) continue;
        const data = String(item.dimensions?.stat_time_day || "").slice(0, 10);
        const atual = tiktokPorDia.get(data) || { spend: 0, clicks: 0, impressions: 0, reach: 0 };
        atual.spend += Number(item.metrics?.spend || 0);
        atual.clicks += Number(item.metrics?.clicks || 0);
        atual.impressions += Number(item.metrics?.impressions || 0);
        atual.reach += Number(item.metrics?.reach || 0);
        tiktokPorDia.set(data, atual);
      }
    }

    const leadsBanco = await client.query(
      `SELECT DATE(criado_em) AS dia, COUNT(*) AS total
       FROM leads WHERE usuario_id = $1 AND plataforma = 'tiktok' AND criado_em >= $2
       GROUP BY DATE(criado_em)`,
      [user.id, inicio]
    );
    const leadsBancoPorDia = new Map(
      leadsBanco.rows.map((r: any) => [new Date(r.dia).toISOString().slice(0, 10), Number(r.total || 0)])
    );

    const datasPeriodo = Array.from({ length: dias }, (_, index) => {
      const data = new Date(inicio);
      data.setDate(inicio.getDate() + index);
      return data.toISOString().slice(0, 10);
    });

    const diasPerformance = datasPeriodo.map((data) => {
      const linha = tiktokPorDia.get(data) || { spend: 0, clicks: 0, impressions: 0, reach: 0 };
      const leadsPlataforma = leadsBancoPorDia.get(data) || 0;
      const gasto = Number(linha.spend || 0);
      return {
        data,
        gasto,
        leads: leadsPlataforma,
        leads_meta: null,
        leads_plataforma: leadsPlataforma,
        custo_por_lead: leadsPlataforma > 0 ? gasto / leadsPlataforma : null,
        cliques: Number(linha.clicks || 0),
        impressoes: Number(linha.impressions || 0),
        alcance: Number(linha.reach || 0),
      };
    });

    const { resumo, registros } = montarResumoPerformanceDiaria(diasPerformance, periodo);

    return c.json({
      conta_anuncios: {
        id: String(advertiserId),
        nome: String(advertiserId),
        moeda: "BRL",
      },
      periodo,
      periodo_dias: dias,
      periodo_inicio: since,
      periodo_fim: until,
      agrupamento: periodo === "anual" ? "mensal" : "diario",
      resumo,
      dias: diasPerformance,
      registros,
    });
  } catch (err: any) {
    console.error("ERRO PERFORMANCE DIARIA TIKTOK:", err);
    return c.json({ error: "Erro ao buscar performance diaria do TikTok Ads", detalhe: err?.message || err }, 500);
  }
});

app.get("/meta/performance-diaria/:data/campanhas", authMiddleware, async (c: any) => {
  try {
    const user: any = c.get("user");
    const data = c.req.param("data");

    if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
      return c.json({ error: "Data invalida. Use YYYY-MM-DD" }, 400);
    }

    const conn = await client.query(
      `SELECT access_token, conta_anuncios_id FROM meta_conexoes WHERE usuario_id = $1 ORDER BY id DESC LIMIT 1`,
      [user.id]
    );

    if (conn.rows.length === 0) {
      return c.json({ error: "Meta nao conectada" }, 400);
    }

    const token = conn.rows[0].access_token;
    const contaAds = await obterContaAnuncios(token, conn.rows[0].conta_anuncios_id);

    if (!contaAds) {
      return c.json({ error: "Conta de anuncios nao encontrada" }, 400);
    }

    const adAccountId = contaAds.id;
    const campaignIdsUsuario =
      await listarCampaignIdsMetaDoUsuario(
        Number(user.id),
        adAccountId
      );
    const timeRange = encodeURIComponent(JSON.stringify({ since: data, until: data }));

    const insights = await fetch(
      `https://graph.facebook.com/v19.0/${adAccountId}/insights?fields=campaign_name,campaign_id,spend,actions,clicks,impressions&level=campaign&time_range=${timeRange}&access_token=${token}`
    ).then(r => r.json());

    if (insights.error) {
      return c.json({ error: "Erro ao buscar dados da Meta", detalhe: insights.error }, 400);
    }

    const campanhas = (insights.data || [])
      .filter((item: any) =>
        campaignIdsUsuario.has(String(item.campaign_id || ""))
      )
      .map((item: any) => {
        const gasto = Number(item.spend || 0);
        const leads = extrairLeadsActionsMeta(item.actions || []);
        return {
          campaign_id: item.campaign_id,
          nome: item.campaign_name || "Campanha sem nome",
          gasto,
          leads,
          cliques: Number(item.clicks || 0),
          impressoes: Number(item.impressions || 0),
          custo_por_lead: leads > 0 ? gasto / leads : null
        };
      });

    campanhas.sort((a: any, b: any) => b.gasto - a.gasto);

    return c.json({ data, campanhas });

  } catch (err: any) {
    console.error("ERRO CAMPANHAS DIA:", err);
    return c.json({ error: "Erro ao buscar campanhas do dia", detalhe: err?.message }, 500);
  }
});

