app.post("/meta/sincronizar-campanhas", authMiddleware, async (c) => {

  const user: any = c.get("user");

  try {

    console.log("USER AUTH:", user);

    if (syncEmAndamento.has(user.id)) {
      return c.json({
        error: "Já existe uma sincronização em andamento para este usuário."
      }, 429);
    }

    syncEmAndamento.add(user.id);

    console.log("USER LOGADO:", user);


    // 🔐 TOKEN META
    const conn = await client.query(
      `
      SELECT access_token, conta_anuncios_id
      FROM meta_conexoes
      WHERE usuario_id = $1
      ORDER BY id DESC
      LIMIT 1
      `,
      [user.id]
    );

    console.log("CONN:", conn.rows);

    if (conn.rows.length === 0) {

      return c.json({
        error: "Meta não conectada"
      }, 400);
    }

    const token = conn.rows[0].access_token;

    // 🔥 CONTA DE ANÚNCIOS
    let contaAds;

    try {

      contaAds =
        await obterContaAnuncios(
          token,
          conn.rows[0].conta_anuncios_id
        );

    } catch (erroConta: any) {

      return c.json({
        error: erroConta?.message ||
          "Selecione a conta de anúncios Meta que deseja usar."
      }, 400);
    }

    if (!contaAds) {

      return c.json({
        error: "Nenhuma conta de anúncios encontrada"
      }, 400);
    }
    
    const adAccountId = contaAds.id;

    // 🔥 BUSCA CAMPANHAS
    const campanhasMeta = await fetch(
      `https://graph.facebook.com/v19.0/${adAccountId}/campaigns?fields=id,name,status,effective_status,objective&limit=500&access_token=${token}`
    ).then(r => r.json());

    console.log(
      "META CAMPANHAS:",
      JSON.stringify(campanhasMeta, null, 2)
    );

    console.log("TOTAL META:", campanhasMeta.data?.length);

    if (!campanhasMeta.data) {

      return c.json({
        error: "Nenhuma campanha encontrada",
        detalhe: campanhasMeta
      }, 400);
    }

    // 🔄 SALVA / ATUALIZA CAMPANHAS
    for (const campanha of campanhasMeta.data) {

      const statusFinal =
        campanha.effective_status ||
        campanha.status ||
        "PAUSED";

      const existe = await client.query(
        `
        SELECT id
        FROM campanhas
        WHERE campaign_id = $1
        AND usuario_id = $2
        `,
        [campanha.id, user.id]
      );

      if (existe.rows.length > 0) {

        await client.query(
          `
          UPDATE campanhas
          SET
            nome = $1,
            status = $2,
            conta_anuncios_id = $3,
            atualizado_em = NOW()
          WHERE campaign_id = $4
          AND usuario_id = $5
          `,
          [
            campanha.name,
            statusFinal,
            adAccountId,
            campanha.id,
            user.id
          ]
        );

        console.log(
          "♻️ Atualizada:",
          campanha.name
        );

      } else {

        await client.query(
          `
          INSERT INTO campanhas (
            usuario_id,
            campaign_id,
            conta_anuncios_id,
            nome,
            status,
            origem,
            atualizado_em
          )
          VALUES ($1,$2,$3,$4,$5,$6,NOW())
          `,
          [
            user.id,
            campanha.id,
            adAccountId,
            campanha.name,
            statusFinal,
            "meta"
          ]
        );

        console.log(
          "✅ Nova:",
          campanha.name
        );
      }
    }

    // =====================================================
    // 🔥 SINCRONIZA LEADS
    // =====================================================
    await sincronizarLeadsMetaUsuario(user.id, token, adAccountId);

    // 🔥 UPDATE ÚLTIMO SYNC
    await client.query(
      `
      UPDATE meta_conexoes
      SET ultimo_sync = NOW()
      WHERE usuario_id = $1
      `,
      [user.id]
    );
    
    return c.json({
      sucesso: true,
      total: campanhasMeta.data.length
    });

    } catch (err) {

    console.error("ERRO SINCRONIZAR:", err);

    return c.json({
      error: "Erro ao sincronizar campanhas"
    }, 500);

  } finally {

    syncEmAndamento.delete(user.id);
  }
});

app.post("/meta/toggle-campanha", authMiddleware, async (c) => {

  try {

    const user: any = c.get("user");

    const {
      campaign_id,
      status
    } = await c.req.json();

    const campanhaBanco = await client.query(
      `
      SELECT id, adset_id, ad_id, usuario_id, conta_anuncios_id
      FROM campanhas
      WHERE campaign_id = $1
      AND usuario_id = $2
      LIMIT 1
      `,
      [campaign_id, user.id]
    );

    if (!campanhaBanco.rows.length) {
      return c.json({
        error: "Campanha não disponível para este usuário"
      }, 404);
    }

    const adset_id =
      campanhaBanco.rows[0]?.adset_id;

    const ad_id =
      campanhaBanco.rows[0]?.ad_id;

    console.log("ADSET:", adset_id);

    console.log("AD:", ad_id);



    // 🔐 TOKEN — sempre usa a conta Meta do próprio usuário que está publicando
    const conn = await client.query(
      `
      SELECT access_token
      FROM meta_conexoes
      WHERE usuario_id = $1
      ORDER BY id DESC
      LIMIT 1
      `,
      [user.id]
    );

    if (conn.rows.length === 0) {

      return c.json({
        error: "Meta não conectada"
      }, 400);
    }

    const token = conn.rows[0].access_token;

    // 🔥 ALTERA STATUS NA META
    const metaRes = await fetch(
      `https://graph.facebook.com/v19.0/${campaign_id}`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          status,
          access_token: token
        })
      }
    ).then(r => r.json());


    // 🔥 TOGGLE ADSET
    if (adset_id) {
    
      const adsetRes = await fetch(
        `https://graph.facebook.com/v19.0/${adset_id}`,
        {
          method: "POST",
    
          headers: {
            "Content-Type": "application/json"
          },
    
          body: JSON.stringify({
            status,
            access_token: token
          })
        }
      ).then(r => r.json());
    
      console.log(
        "TOGGLE ADSET:",
        adsetRes
      );
    }

    // 🔥 TOGGLE ANÚNCIO
    if (ad_id) {
    
      const adRes = await fetch(
        `https://graph.facebook.com/v19.0/${ad_id}`,
        {
          method: "POST",
    
          headers: {
            "Content-Type": "application/json"
          },
    
          body: JSON.stringify({
            status,
            access_token: token
          })
        }
      ).then(r => r.json());
    
      console.log(
        "TOGGLE AD:",
        adRes
      );
    }

    

    

    console.log("TOGGLE META:", metaRes);

    if (metaRes.error) {

      return c.json({
        error: metaRes.error.message
      }, 400);
    }

    // 💾 UPDATE LOCAL
    await client.query(
      `
      UPDATE campanhas
      SET status = $1
      WHERE id = $2
      `,
      [status, campanhaBanco.rows[0].id]
    );

    return c.json({
      sucesso: true
    });

  } catch (err) {

    console.error("TOGGLE:", err);

    return c.json({
      error: "Erro ao alterar campanha"
    }, 500);
  }
});


app.post("/meta/excluir-campanha", authMiddleware, async (c) => {

  try {

    const user: any = c.get("user");

    const {
      campaign_id
    } = await c.req.json();

    const contaAnunciosId =
      await obterContaAnunciosSelecionadaIdUsuario(
        user.id
      );

    const campanha = await client.query(
      `
      SELECT id
      FROM campanhas
      WHERE campaign_id = $1
      AND usuario_id = $2
      AND (conta_anuncios_id = $3 OR conta_anuncios_id IS NULL)
      LIMIT 1
      `,
      [campaign_id, user.id, contaAnunciosId]
    );

    if (!campanha.rows.length) {
      return c.json({
        error: "Apenas o dono da campanha pode excluí-la"
      }, 403);
    }

    // 🔐 TOKEN
    const conn = await client.query(
      `
      SELECT access_token
      FROM meta_conexoes
      WHERE usuario_id = $1
      ORDER BY id DESC
      LIMIT 1
      `,
      [user.id]
    );

    if (conn.rows.length === 0) {

      return c.json({
        error: "Meta não conectada"
      }, 400);
    }

    const token = conn.rows[0].access_token;

    // 🔥 DELETA NA META
    const metaRes = await fetch(
      `https://graph.facebook.com/v19.0/${campaign_id}`,
      {
        method: "POST",

        headers: {
          "Content-Type": "application/json"
        },

        body: JSON.stringify({
          status: "DELETED",
          access_token: token
        })
      }
    ).then(r => r.json());

    console.log("DELETE META:", metaRes);

    if (metaRes.error) {
      const errCode = Number(metaRes.error?.code) || 0;
      const errMsg = (metaRes.error?.message || "").toLowerCase();

      // Campanha não existe mais no Meta (inválida, já excluída lá ou nunca criada):
      // marca como deletada localmente sem bloquear o usuário
      const naoPertenceMaisMeta =
        errCode === 803 ||   // no such object
        errCode === 100 ||   // invalid parameter (inclui IDs inexistentes)
        errMsg.includes("invalid parameter") ||
        errMsg.includes("no such") ||
        errMsg.includes("does not exist") ||
        errMsg.includes("deleted");

      if (!naoPertenceMaisMeta) {
        return c.json({
          error: metaRes.error?.error_user_msg || metaRes.error?.message || "Erro ao excluir no Meta"
        }, 400);
      }

      console.log("EXCLUIR: campanha não encontrada no Meta, removendo localmente:", campaign_id);
    }

    // 💾 REMOVE LOCAL
    await client.query(
      `
      UPDATE campanhas
      SET status = 'DELETED'
      WHERE id = $1
      `,
      [campanha.rows[0].id]
    );

    return c.json({
      sucesso: true
    });

  } catch (err) {

    console.error("EXCLUIR CAMPANHA:", err);

    return c.json({
      error: "Erro ao excluir campanha"
    }, 500);
  }
});


// 🔹 restaurar campanha excluída no histórico local
app.post("/meta/restaurar-campanha", authMiddleware, async (c) => {

  try {

    const user: any = c.get("user");

    const {
      campaign_id
    } = await c.req.json();

    const campanha = await client.query(
      `
      SELECT id, adset_id, ad_id
      FROM campanhas
      WHERE campaign_id = $1
      AND usuario_id = $2
      AND UPPER(status) = 'DELETED'
      LIMIT 1
      `,
      [campaign_id, user.id]
    );

    if (!campanha.rows.length) {
      return c.json({
        error: "Campanha excluída não encontrada para este usuário"
      }, 404);
    }

    const conn = await client.query(
      `
      SELECT access_token
      FROM meta_conexoes
      WHERE usuario_id = $1
      ORDER BY id DESC
      LIMIT 1
      `,
      [user.id]
    );

    const token =
      conn.rows[0]?.access_token || null;

    let aviso: string | null = null;

    if (token) {
      const idsMeta = [
        campaign_id,
        campanha.rows[0].adset_id,
        campanha.rows[0].ad_id
      ].filter(Boolean);

      for (const idMeta of idsMeta) {
        const metaRes = await fetch(
          `https://graph.facebook.com/v19.0/${idMeta}`,
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json"
            },
            body: JSON.stringify({
              status: "PAUSED",
              access_token: token
            })
          }
        ).then(r => r.json());

        if (metaRes.error && !aviso) {
          aviso =
            "A Meta não permitiu recuperar a campanha original. Ela ficou restaurada apenas na plataforma.";
        }
      }
    } else {
      aviso =
        "Meta não conectada. A campanha foi restaurada apenas no histórico local.";
    }

    await client.query(
      `
      UPDATE campanhas
      SET status = 'PAUSED'
      WHERE id = $1
      `,
      [campanha.rows[0].id]
    );

    return c.json({
      sucesso: true,
      aviso
    });

  } catch (err) {

    console.error("RESTAURAR CAMPANHA:", err);

    return c.json({
      error: "Erro ao restaurar campanha"
    }, 500);
  }
});


// 🔹 excluir definitivamente uma campanha da plataforma
app.delete("/campanhas/:id/definitiva", authMiddleware, async (c) => {

  try {

    const user: any = c.get("user");

    const campanhaId =
      Number(c.req.param("id"));

    if (!Number.isFinite(campanhaId)) {
      return c.json({
        error: "Campanha inválida"
      }, 400);
    }

    const campanha = await client.query(
      `
      SELECT id, campaign_id, status, plataforma
      FROM campanhas
      WHERE id = $1
      AND usuario_id = $2
      LIMIT 1
      `,
      [campanhaId, user.id]
    );

    if (!campanha.rows.length) {
      return c.json({
        error: "Apenas o dono da campanha pode excluí-la definitivamente"
      }, 403);
    }

    const campanhaLocal =
      campanha.rows[0];

    const statusAtual =
      String(campanhaLocal.status || "").toUpperCase();

    const plataformaLocal =
      campanhaLocal.plataforma || "meta";

    // Antes so tentava excluir via Meta, ignorando a plataforma real da campanha —
    // pra uma campanha Google/TikTok isso chamava a API errada com um campaign_id
    // que nao existe la, e o botao "excluir definitivamente" nunca funcionava.
    if (
      campanhaLocal.campaign_id &&
      statusAtual !== "DELETED"
    ) {
      if (plataformaLocal === "google") {
        const conexao = await resolverConexaoGoogleAds(user.id);

        if (!("erro" in conexao)) {
          try {
            await googleAdsMutate(conexao.customerId, conexao.accessToken, "campaigns", [
              { remove: `customers/${conexao.customerId}/campaigns/${campanhaLocal.campaign_id}` },
            ]);
          } catch (err: any) {
            const msg = String(err?.message || "").toLowerCase();
            const naoPertenceMaisGoogle =
              msg.includes("not found") ||
              msg.includes("does not exist") ||
              msg.includes("invalid resource") ||
              msg.includes("resource was not found");

            if (!naoPertenceMaisGoogle) {
              return c.json({
                error: err?.message || "O Google Ads não permitiu excluir a campanha"
              }, 400);
            }
            console.log("EXCLUIR DEFINITIVO GOOGLE: campanha não encontrada no Google Ads, removendo localmente:", campanhaLocal.campaign_id);
          }
        }
      } else if (plataformaLocal === "tiktok") {
        const conexao = await obterConexaoTikTok(user.id);

        if (conexao?.advertiserId) {
          const del = await tiktokFetch("/campaign/update/status/", conexao.token, {
            method: "POST",
            body: {
              advertiser_id: conexao.advertiserId,
              campaign_ids: [String(campanhaLocal.campaign_id)],
              operation_status: "DELETE"
            }
          });

          if (!del.ok) {
            const msg = (del.error || "").toLowerCase();
            const naoPertenceMaisTikTok =
              msg.includes("not exist") ||
              msg.includes("not found") ||
              msg.includes("invalid campaign") ||
              msg.includes("does not exist");

            if (!naoPertenceMaisTikTok) {
              return c.json({ error: del.error || "O TikTok não permitiu excluir a campanha" }, 400);
            }
            console.log("EXCLUIR DEFINITIVO TIKTOK: campanha não encontrada na TikTok, removendo localmente:", campanhaLocal.campaign_id);
          }
        }
      } else {
        const conn = await client.query(
          `
          SELECT access_token
          FROM meta_conexoes
          WHERE usuario_id = $1
          ORDER BY id DESC
          LIMIT 1
          `,
          [user.id]
        );

        const token =
          conn.rows[0]?.access_token || null;

        if (token) {
          const metaRes = await fetch(
            `https://graph.facebook.com/v19.0/${campanhaLocal.campaign_id}`,
            {
              method: "POST",
              headers: {
                "Content-Type": "application/json"
              },
              body: JSON.stringify({
                status: "DELETED",
                access_token: token
              })
            }
          ).then(r => r.json());

          console.log("DELETE DEFINITIVO META:", metaRes);

          if (metaRes.error) {
            return c.json({
              error:
                metaRes.error.message ||
                "A Meta não permitiu excluir a campanha"
            }, 400);
          }
        }
      }
    }

    await client.query(
      `
      DELETE FROM campanhas
      WHERE id = $1
      AND usuario_id = $2
      `,
      [campanhaId, user.id]
    );

    return c.json({
      sucesso: true
    });

  } catch (err) {

    console.error("EXCLUIR CAMPANHA DEFINITIVA:", err);

    return c.json({
      error: "Erro ao excluir campanha definitivamente"
    }, 500);
  }
});

// Carrega a configuração real usada no editor. Campanhas antigas, importadas
// ou criadas antes de todos os campos serem persistidos podem ter apenas os IDs
// locais. Nesse caso completamos os dados a partir da campanha/adset/criativo
// publicados na Meta, sem modificar o anúncio remoto.
app.get("/meta/campanhas/:id/configuracao-edicao", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const campanhaId = Number(c.req.param("id"));

    if (!Number.isFinite(campanhaId) || campanhaId <= 0) {
      return c.json({ error: "Campanha inválida" }, 400);
    }

    const campanhaRes = await client.query(
      `SELECT * FROM campanhas WHERE id = $1 AND usuario_id = $2 LIMIT 1`,
      [campanhaId, user.id]
    );

    if (!campanhaRes.rows.length) {
      return c.json({ error: "Campanha não encontrada" }, 404);
    }

    const campanha = campanhaRes.rows[0];

    const objetoConfiguracao = (valor: any): Record<string, any> => {
      if (!valor) return {};
      if (typeof valor === "string") {
        try {
          const parsed = JSON.parse(valor);
          return parsed && typeof parsed === "object" ? parsed : {};
        } catch {
          return {};
        }
      }
      return typeof valor === "object" ? { ...valor } : {};
    };

    const configuracoes = objetoConfiguracao(campanha.configuracoes_avancadas);
    const respostaLocal = (aviso: string | null = null) => ({
      id: campanha.id,
      nome: campanha.nome,
      status: campanha.status,
      campaign_id: campanha.campaign_id,
      adset_id: campanha.adset_id,
      ad_id: campanha.ad_id,
      form_id: campanha.form_id,
      page_id: campanha.page_id,
      daily_budget: campanha.daily_budget,
      configuracoes_avancadas: configuracoes,
      meta_carregada: false,
      aviso
    });

    const plataforma = String(campanha.plataforma || "meta").toLowerCase();
    if (plataforma !== "meta" || !campanha.campaign_id) {
      return c.json(respostaLocal());
    }

    const conn = await client.query(
      `SELECT access_token, conta_anuncios_id
       FROM meta_conexoes
       WHERE usuario_id = $1
       ORDER BY id DESC
       LIMIT 1`,
      [user.id]
    );

    const token = conn.rows[0]?.access_token;
    if (!token) {
      return c.json(respostaLocal("Meta não conectada; exibindo os dados salvos na plataforma."));
    }

    const consultarObjetoMeta = async (id: string, fields: string) => {
      const params = new URLSearchParams({ fields, access_token: token });
      const res = await fetch(
        `https://graph.facebook.com/v19.0/${id}?${params}`
      );
      const data = await res.json() as any;
      if (!res.ok || data?.error) {
        throw new Error(
          data?.error?.error_user_msg ||
          data?.error?.message ||
          `Não foi possível consultar ${id} na Meta`
        );
      }
      return data;
    };

    const consultarPrimeiroEdgeMeta = async (
      id: string,
      edge: string,
      fields: string
    ) => {
      const params = new URLSearchParams({
        fields,
        limit: "1",
        access_token: token
      });
      const res = await fetch(
        `https://graph.facebook.com/v19.0/${id}/${edge}?${params}`
      );
      const data = await res.json() as any;
      if (!res.ok || data?.error) return null;
      return data?.data?.[0] || null;
    };

    try {
      const campanhaMeta = await consultarObjetoMeta(
        String(campanha.campaign_id),
        "id,name,status,objective,daily_budget,special_ad_categories"
      );

      let adsetId = textoOpcional(campanha.adset_id);
      let adId = textoOpcional(campanha.ad_id);

      const adsetLista = !adsetId
        ? await consultarPrimeiroEdgeMeta(
            String(campanha.campaign_id),
            "adsets",
            "id"
          )
        : null;
      adsetId = adsetId || textoOpcional(adsetLista?.id);

      const adLista = !adId
        ? await consultarPrimeiroEdgeMeta(
            String(campanha.campaign_id),
            "ads",
            "id,adset_id,creative"
          )
        : null;
      adId = adId || textoOpcional(adLista?.id);
      adsetId = adsetId || textoOpcional(adLista?.adset_id);

      const [adsetMeta, adMetaConsultado] = await Promise.all([
        adsetId
          ? consultarObjetoMeta(
              adsetId,
              "id,daily_budget,bid_strategy,bid_amount,start_time,end_time,targeting,attribution_spec,destination_type,promoted_object"
            ).catch(() => null)
          : Promise.resolve(null),
        adId
          ? consultarObjetoMeta(adId, "id,adset_id,creative").catch(() => null)
          : Promise.resolve(adLista)
      ]);

      // Se o acesso direto ao anúncio falhar pontualmente, ainda aproveita o
      // objeto que veio da listagem da campanha para localizar o criativo.
      const adMeta = adMetaConsultado || adLista;

      const creativeRef = adMeta?.creative ?? adLista?.creative;
      const creativeId =
        textoOpcional(creativeRef?.id) ||
        (typeof creativeRef === "string" ? textoOpcional(creativeRef) : "");

      let creativeMeta: any = null;
      if (creativeId) {
        creativeMeta = await consultarObjetoMeta(
          creativeId,
          "id,object_story_spec,thumbnail_url,image_url,image_hash,asset_feed_spec"
        ).catch(() => null);

        // Alguns tipos antigos de criativo não expõem asset_feed_spec. Uma
        // segunda consulta menor evita perder texto e imagem por causa apenas
        // desse campo opcional.
        if (!creativeMeta) {
          creativeMeta = await consultarObjetoMeta(
            creativeId,
            "id,object_story_spec,thumbnail_url,image_url,image_hash"
          ).catch(() => null);
        }
      }

      const story = creativeMeta?.object_story_spec || {};
      const linkData = story.link_data || {};
      const videoData = story.video_data || {};
      const anexos = Array.isArray(linkData.child_attachments)
        ? linkData.child_attachments
        : [];
      const targeting = adsetMeta?.targeting || {};
      const geo = targeting.geo_locations || {};

      const definir = (chave: string, valor: any) => {
        const vazio =
          valor === null ||
          valor === undefined ||
          valor === "" ||
          (Array.isArray(valor) && !valor.length);
        if (!vazio) configuracoes[chave] = valor;
      };

      // Dados básicos/criativo publicados.
      definir("page_id", story.page_id || campanha.page_id);
      definir("texto", linkData.message || videoData.message);
      definir("titulo", linkData.name || videoData.title);
      definir("descricao", linkData.description || videoData.description);
      definir("link", linkData.link);
      if (!configuracoes.cta) {
        definir(
          "cta",
          linkData.call_to_action?.type || videoData.call_to_action?.type
        );
      }
      definir("creative_id", creativeId);
      definir("adset_id", adsetId);
      definir("ad_id", adId);
      definir("objetivo", campanhaMeta?.objective);
      definir("categoria_especial", campanhaMeta?.special_ad_categories?.[0]);

      if (campanhaMeta?.daily_budget !== undefined) {
        configuracoes.cbo = true;
      } else if (configuracoes.cbo === undefined && adsetMeta?.daily_budget !== undefined) {
        configuracoes.cbo = false;
      }

      const formIdMeta =
        linkData.call_to_action?.value?.lead_gen_form_id ||
        videoData.call_to_action?.value?.lead_gen_form_id ||
        adsetMeta?.promoted_object?.lead_gen_form_id ||
        campanha.form_id;
      definir("form_id", formIdMeta);

      const destinationType = String(adsetMeta?.destination_type || "").toUpperCase();
      if (destinationType.includes("WHATSAPP")) {
        configuracoes.destino = "whatsapp";
      } else if (!configuracoes.destino) {
        configuracoes.destino = "lead_ads";
      }

      // Público, posicionamentos e orçamento reais do Ad Set.
      definir("idade_min", targeting.age_min);
      definir("idade_max", targeting.age_max);
      definir("genero", targeting.genders?.[0]);
      definir("pais", geo.countries?.[0]);
      definir("plataformas", targeting.publisher_platforms);
      definir("facebook_positions", targeting.facebook_positions);
      definir("instagram_positions", targeting.instagram_positions);
      definir("dispositivos", targeting.device_platforms);
      definir(
        "interesses_detalhados",
        (targeting.flexible_spec || [])
          .flatMap((grupo: any) => grupo?.interests || [])
          .map((item: any) => ({
            id: textoOpcional(item?.id),
            nome: textoOpcional(item?.name)
          }))
          .filter((item: any) => item.id && item.nome)
      );
      definir(
        "custom_audiences",
        (targeting.custom_audiences || [])
          .map((item: any) => textoOpcional(item?.id || item))
          .filter(Boolean)
      );

      if (targeting.targeting_automation?.advantage_audience !== undefined) {
        configuracoes.advantage_audience =
          Number(targeting.targeting_automation.advantage_audience) !== 0;
      }

      const localidades: any[] = [];
      const adicionarLocalidades = (lista: any, tipo: string) => {
        for (const local of Array.isArray(lista) ? lista : []) {
          const key = textoOpcional(local?.key || local?.id);
          if (!key) continue;
          localidades.push({
            key,
            tipo,
            nome: textoOpcional(local?.name) || key,
            raio: numeroOpcional(local?.radius)
          });
        }
      };
      adicionarLocalidades(geo.regions, "region");
      adicionarLocalidades(geo.cities, "city");
      adicionarLocalidades(geo.neighborhoods, "neighborhood");
      adicionarLocalidades(geo.zips, "zip");
      adicionarLocalidades(geo.geo_markets, "geo_market");
      adicionarLocalidades(geo.electoral_districts, "electoral_district");
      definir("localidades", localidades);

      definir("bid_strategy", adsetMeta?.bid_strategy);
      if (numeroOpcional(adsetMeta?.bid_amount) !== null) {
        configuracoes.bid_amount = Number(adsetMeta.bid_amount) / 100;
      }

      const atrib = Array.isArray(adsetMeta?.attribution_spec)
        ? adsetMeta.attribution_spec
        : [];
      const clickDays = atrib.find((item: any) => item.event_type === "CLICK_THROUGH")?.window_days;
      const viewDays = atrib.find((item: any) => item.event_type === "VIEW_THROUGH")?.window_days;
      if (clickDays === 1 && viewDays === 1) configuracoes.attribution_spec = "1d_click_1d_view";
      else if (clickDays === 7 && viewDays === 1) configuracoes.attribution_spec = "7d_click_1d_view";
      else if (clickDays === 1) configuracoes.attribution_spec = "1d_click";
      else if (clickDays === 7) configuracoes.attribution_spec = "7d_click";
      else if (clickDays === 28) configuracoes.attribution_spec = "28d_click";

      const dataHoraBrasil = (valor: any) => {
        if (!valor) return "";
        const data = new Date(valor);
        if (Number.isNaN(data.getTime())) return "";
        const partes = new Intl.DateTimeFormat("en-CA", {
          timeZone: "America/Sao_Paulo",
          year: "numeric",
          month: "2-digit",
          day: "2-digit",
          hour: "2-digit",
          minute: "2-digit",
          hourCycle: "h23"
        }).formatToParts(data);
        const obter = (tipo: string) => partes.find(p => p.type === tipo)?.value || "";
        return `${obter("year")}-${obter("month")}-${obter("day")}T${obter("hour")}:${obter("minute")}`;
      };
      if (!configuracoes.inicio) definir("inicio", dataHoraBrasil(adsetMeta?.start_time));
      if (!configuracoes.fim) definir("fim", dataHoraBrasil(adsetMeta?.end_time));

      const hashesRemotos = Array.from(new Set([
        ...anexos.map((item: any) => item?.image_hash),
        linkData.image_hash,
        creativeMeta?.image_hash,
        ...(creativeMeta?.asset_feed_spec?.images || []).map((item: any) => item?.hash)
      ].filter(Boolean).map(String)));

      const hashesLocais = [
        ...(Array.isArray(configuracoes.imageHashes) ? configuracoes.imageHashes : []),
        ...(Array.isArray(configuracoes.image_hashes) ? configuracoes.image_hashes : []),
        configuracoes.imageHash,
        configuracoes.image_hash
      ].filter(Boolean).map(String);

      const hashes = hashesRemotos.length
        ? hashesRemotos
        : Array.from(new Set(hashesLocais));

      const urlPorHash = new Map<string, string>();
      if (hashes.length) {
        const contaAnunciosId =
          textoOpcional(campanha.conta_anuncios_id) ||
          textoOpcional(conn.rows[0]?.conta_anuncios_id);

        if (contaAnunciosId) {
          const params = new URLSearchParams({
            fields: "hash,url,url_128",
            hashes: JSON.stringify(hashes),
            access_token: token
          });
          const imagensMeta = await fetch(
            `https://graph.facebook.com/v19.0/${contaAnunciosId}/adimages?${params}`
          ).then(r => r.json()).catch(() => null) as any;
          const listaImagens = Array.isArray(imagensMeta?.data)
            ? imagensMeta.data
            : Object.values(imagensMeta?.data || {});
          for (const imagem of listaImagens as any[]) {
            const hash = textoOpcional(imagem?.hash);
            const url = textoOpcional(imagem?.url || imagem?.url_128);
            if (hash && url) urlPorHash.set(hash, url);
          }
        }
      }

      const urlsCriativo = [
        ...anexos.map((item: any) => item?.picture || item?.image_url),
        ...(creativeMeta?.asset_feed_spec?.images || []).map((item: any) => item?.url),
        creativeMeta?.image_url,
        creativeMeta?.thumbnail_url
      ].filter(Boolean).map(String);
      const urlsLocais = [
        ...(Array.isArray(configuracoes.imagens_urls) ? configuracoes.imagens_urls : []),
        ...(Array.isArray(configuracoes.image_urls) ? configuracoes.image_urls : []),
        configuracoes.imagem_url,
        configuracoes.image_url
      ].filter(Boolean).map(String);

      // A Meta pode devolver várias URLs para o mesmo hash (imagem completa,
      // thumbnail e novos links assinados a cada consulta). A identidade real
      // da imagem é o hash; guardar todas as URLs fazia uma única arte aparecer
      // repetida e a lista crescer toda vez que o editor era aberto.
      const urls = hashes.length
        ? hashes
            .map((hash, indice) =>
              urlPorHash.get(hash) ||
              urlsCriativo[indice] ||
              urlsLocais[indice] ||
              (indice === 0 ? urlsCriativo[0] || urlsLocais[0] : "")
            )
            .filter(Boolean)
        : Array.from(new Set([
            ...urlsCriativo,
            ...urlsLocais
          ]));

      if (hashes.length) {
        configuracoes.imageHashes = hashes;
        configuracoes.image_hashes = hashes;
        configuracoes.imageHash = hashes[0];
        configuracoes.image_hash = hashes[0];
      }
      // Sobrescreve também os formatos antigos para limpar URLs históricas já
      // acumuladas no banco na próxima abertura da campanha.
      configuracoes.imagens_urls = urls;
      configuracoes.image_urls = urls;
      configuracoes.imagem_url = urls[0] || null;
      configuracoes.image_url = urls[0] || null;
      configuracoes.criativo = {
        ...(configuracoes.criativo || {}),
        creative_id: creativeId || configuracoes.criativo?.creative_id || null,
        image_hash: hashes[0] || configuracoes.criativo?.image_hash || null,
        image_hashes: hashes,
        tipo: videoData.video_id
          ? "video"
          : hashes.length > 1
          ? "carrossel"
          : "imagem"
      };

      const dailyBudgetMeta =
        numeroOpcional(adsetMeta?.daily_budget) ??
        numeroOpcional(campanhaMeta?.daily_budget) ??
        numeroOpcional(campanha.daily_budget);

      // Faz um reparo local dos registros antigos para que as próximas
      // aberturas continuem completas mesmo se a Meta estiver temporariamente
      // indisponível. Nenhum dado do anúncio remoto é alterado aqui.
      await client.query(
        `UPDATE campanhas
         SET adset_id = COALESCE($1, adset_id),
             ad_id = COALESCE($2, ad_id),
             form_id = COALESCE($3, form_id),
             page_id = COALESCE($4, page_id),
             daily_budget = COALESCE($5, daily_budget),
             configuracoes_avancadas = $6,
             atualizado_em = NOW()
         WHERE id = $7 AND usuario_id = $8`,
        [
          adsetId || null,
          adId || null,
          formIdMeta || null,
          story.page_id || null,
          dailyBudgetMeta,
          JSON.stringify(configuracoes),
          campanha.id,
          user.id
        ]
      ).catch((errPersistencia: any) =>
        console.warn(
          "CONFIGURAÇÃO EDIÇÃO META: não foi possível persistir o reparo:",
          errPersistencia?.message || errPersistencia
        )
      );

      return c.json({
        id: campanha.id,
        nome: campanhaMeta?.name || campanha.nome,
        status: campanhaMeta?.status || campanha.status,
        campaign_id: campanha.campaign_id,
        adset_id: adsetId || campanha.adset_id,
        ad_id: adId || campanha.ad_id,
        form_id: formIdMeta || campanha.form_id,
        page_id: story.page_id || campanha.page_id,
        daily_budget: dailyBudgetMeta,
        configuracoes_avancadas: configuracoes,
        meta_carregada: true,
        aviso: null
      });
    } catch (errMeta: any) {
      console.warn("CONFIGURAÇÃO EDIÇÃO META: usando dados locais:", errMeta?.message || errMeta);
      return c.json(
        respostaLocal(
          "Não foi possível completar os dados ao vivo da Meta; exibindo o que está salvo na plataforma."
        )
      );
    }
  } catch (err) {
    console.error("ERRO CONFIGURAÇÃO EDIÇÃO CAMPANHA:", err);
    return c.json({ error: "Erro ao carregar configuração da campanha" }, 500);
  }
});

// 🔹 editar segmentação, orçamento, datas e lance de uma campanha existente
app.post("/meta/editar-campanha", authMiddleware, async (c) => {

  try {

    const user: any = c.get("user");

    const {
      usuario_id,
      campanha_local_id,
      campaign_id,
      daily_budget,
      configuracoes_avancadas,
      nome,
      imageHash: imageHashNovo,
      imageHashes: imageHashesNovo,
      imageUrls: imageUrlsNovo
    } = await c.req.json();

    // Um mesmo hash/URL de imagem é lido em varios formatos espalhados pelo
    // codigo (camelCase, snake_case, e uma copia dentro de `criativo`) — sem
    // sincronizar todos, telas diferentes (detalhes, edicao) podem mostrar
    // imagens diferentes para a mesma campanha apos uma troca.
    function sincronizarCamposImagem(avancadas: any, hashes: string[], urls: string[]) {
      if (!hashes.length) return;
      avancadas.imageHashes = hashes;
      avancadas.imageHash = hashes[0];
      avancadas.image_hashes = hashes;
      avancadas.image_hash = hashes[0];
      if (urls.length) {
        avancadas.imagens_urls = urls;
        avancadas.image_urls = urls;
      }
      if (avancadas.criativo) {
        avancadas.criativo.image_hashes = hashes;
        avancadas.criativo.image_hash = hashes[0];
      }
    }

    const usuarioId =
      resolverUsuarioIdOperacao(user, usuario_id);

    if (!usuarioId) {
      return negarAcessoConta(c);
    }

    // O estado do banco é a fonte de verdade. Algumas cópias antigas podem
    // chegar do frontend com um campaign_id herdado da campanha de origem; por
    // isso não usamos apenas o valor enviado pela tela para decidir se é rascunho.
    const campanhaLocalRes = campanha_local_id
      ? await client.query(
          `SELECT id, campaign_id, adset_id, ad_id, origem, origem_campanha_id
           FROM campanhas
           WHERE id = $1 AND usuario_id = $2
           LIMIT 1`,
          [campanha_local_id, usuarioId]
        )
      : { rows: [] as any[] };
    const campanhaLocal = campanhaLocalRes.rows[0] || null;
    const ehRascunhoLocal = Boolean(
      campanhaLocal && (
        !campanhaLocal.campaign_id ||
        (!campanhaLocal.adset_id && !campanhaLocal.ad_id) ||
        String(campanhaLocal.origem || "").toLowerCase() === "manual"
      )
    );

    // Campanha ainda não publicada na Meta (duplicada ou rascunho): salva só localmente.
    // Limpa IDs remotos eventualmente herdados para que a primeira publicação
    // crie campanha, conjunto e anúncio novos em vez de alterar a campanha original.
    if (ehRascunhoLocal) {
      const avancadas = configuracoes_avancadas || {};
      const hashesRascunho =
        Array.isArray(imageHashesNovo) && imageHashesNovo.length
          ? imageHashesNovo
          : textoOpcional(imageHashNovo)
          ? [imageHashNovo]
          : [];
      sincronizarCamposImagem(
        avancadas,
        hashesRascunho,
        Array.isArray(imageUrlsNovo) ? imageUrlsNovo.filter(Boolean) : []
      );
      const dailyBudget = numeroOpcional(daily_budget);
      const nomeLocal = textoOpcional(nome);
      await client.query(
        `UPDATE campanhas
         SET configuracoes_avancadas = $1,
             daily_budget = COALESCE($2, daily_budget),
             nome = COALESCE($3, nome),
             campaign_id = NULL,
             adset_id = NULL,
             ad_id = NULL,
             form_id = NULL,
             atualizado_em = NOW()
         WHERE id = $4 AND usuario_id = $5`,
        [JSON.stringify(avancadas), dailyBudget, nomeLocal, campanha_local_id, usuarioId]
      );
      return c.json({ sucesso: true });
    }

    const contaAnunciosId =
      await obterContaAnunciosSelecionadaIdUsuario(
        usuarioId
      );

    const campanhaBanco = await client.query(
      `
      SELECT id, adset_id, ad_id, form_id, configuracoes_avancadas
      FROM campanhas
      WHERE campaign_id = $1
      AND (
        usuario_id = $2
        OR encaminhada_para_usuario_id = $2
      )
      AND conta_anuncios_id = $3
      LIMIT 1
      `,
      [campaign_id, usuarioId, contaAnunciosId]
    );

    if (!campanhaBanco.rows.length) {
      return c.json({
        error: "Campanha não disponível para este usuário"
      }, 404);
    }

    const configuracoesBanco =
      campanhaBanco.rows[0]?.configuracoes_avancadas || {};
    const destinoOriginal =
      resolverDestinoCampanha(configuracoesBanco.destino);
    const destinoSolicitado =
      resolverDestinoCampanha(configuracoes_avancadas?.destino);

    // A Meta não permite converter o destination_type de um Ad Set existente
    // entre formulário e WhatsApp. Sem esta proteção, o banco passava a mostrar
    // WhatsApp enquanto o anúncio remoto continuava sendo Lead Ads.
    if (destinoSolicitado !== destinoOriginal) {
      return c.json({
        error: "O destino de uma campanha já publicada não pode ser alterado. Duplique a campanha e escolha o novo destino na cópia."
      }, 409);
    }

    const adsetId =
      campanhaBanco.rows[0]?.adset_id;

    if (!adsetId) {
      return c.json({
        error: "Conjunto de anúncios não encontrado para esta campanha"
      }, 400);
    }

    // 🔐 TOKEN
    const conn = await client.query(
      `
      SELECT access_token
      FROM meta_conexoes
      WHERE usuario_id = $1
      ORDER BY id DESC
      LIMIT 1
      `,
      [usuarioId]
    );

    if (!conn.rows.length) {
      return c.json({
        error: "Meta não conectada"
      }, 400);
    }

    const token = conn.rows[0].access_token;

    const avancadas =
      configuracoes_avancadas || {};

    const targeting =
      montarTargetingMeta(avancadas);

    const categoriaEspecial =
      textoOpcional(avancadas.categoria_especial);

    if (
      [
        "HOUSING",
        "CREDIT",
        "EMPLOYMENT"
      ].includes(categoriaEspecial)
    ) {
      delete targeting.age_min;
      delete targeting.age_max;
      delete targeting.genders;
    }

    const { bidStrategy, bidAmount } =
      prepararControleCustoMeta(
        avancadas.bid_strategy,
        avancadas.bid_amount
      );

    const inicio =
      textoOpcional(avancadas.inicio);

    const fim =
      textoOpcional(avancadas.fim);

    const dailyBudget =
      numeroOpcional(daily_budget);

    // CBO (Campaign Budget Optimization) determina se o orçamento vive na
    // CAMPANHA ou no CONJUNTO DE ANÚNCIOS — mandar daily_budget pro lado
    // errado faz a Meta rejeitar com "Você só pode definir um orçamento de
    // conjunto de anúncios ou um orçamento de campanha". `avancadas.cbo` (o
    // que o frontend manda, herdado do que já está salvo localmente) pode
    // estar desatualizado ou nunca ter sido preenchido corretamente — a
    // única fonte confiável é perguntar direto pra Meta se a campanha JÁ tem
    // daily_budget/lifetime_budget hoje (mesma lógica de GET /campanhas/:id/sincronizar,
    // linha ~20535). Falha na consulta cai de volta pro flag local antigo,
    // em vez de assumir silenciosamente que não é CBO.
    let campanhaTemOrcamentoProprio = false;
    try {
      const campanhaMetaAtual = await fetch(
        `https://graph.facebook.com/v19.0/${campaign_id}?fields=daily_budget,lifetime_budget&access_token=${token}`
      ).then(r => r.json());
      campanhaTemOrcamentoProprio =
        campanhaMetaAtual?.daily_budget !== undefined ||
        campanhaMetaAtual?.lifetime_budget !== undefined;
    } catch {}

    const cboAtivo = campanhaTemOrcamentoProprio || Boolean(avancadas.cbo);

    const payloadAdset: any = {
      targeting,
      access_token: token
    };

    // Com CBO a estrategia de lance (e o orçamento) vivem na campanha, nao no adset.
    if (cboAtivo) {
      const payloadCampanhaLance: any = {
        bid_strategy: bidStrategy || "LOWEST_COST_WITHOUT_CAP",
        access_token: token
      };

      if (bidAmount !== null && bidStrategyExigeValor(payloadCampanhaLance.bid_strategy)) {
        payloadCampanhaLance.bid_amount = Math.round(bidAmount * 100);
      }

      if (dailyBudget !== null) {
        payloadCampanhaLance.daily_budget = dailyBudget;
      }

      const campanhaLanceRes = await enviarPayloadMetaComFallbackBid(
        `https://graph.facebook.com/v19.0/${campaign_id}`,
        payloadCampanhaLance,
        "EDITAR_CAMPANHA_LANCE"
      );

      if (campanhaLanceRes.error) {
        return c.json({
          error: mensagemErroMeta(campanhaLanceRes, "Erro ao salvar o controle de custo no Meta"),
          detalhe: campanhaLanceRes.error,
          targeting_enviado: targeting
        }, 400);
      }
    } else if (bidStrategy) {
      payloadAdset.bid_strategy = bidStrategy;
    }

    if (dailyBudget !== null && !cboAtivo) {
      payloadAdset.daily_budget = dailyBudget;
    }

    if (
      bidAmount !== null &&
      bidStrategyExigeValor(bidStrategy) &&
      !avancadas.cbo
    ) {
      payloadAdset.bid_amount =
        Math.round(bidAmount * 100);
    }

    if (fim) {
      payloadAdset.end_time =
        new Date(fim).toISOString();
    }

    if (inicio) {
      const inicioData = new Date(inicio);

      if (inicioData.getTime() > Date.now()) {
        payloadAdset.start_time =
          inicioData.toISOString();
      }
    }

    // Janela de atribuição — mesmo mapeamento usado na criação (POST /meta/adset),
    // antes ausente aqui: o campo existia na tela de edição mas não tinha efeito
    // nenhum, porque nunca chegava a ser incluído no payload enviado à Meta.
    const atribuicaoEdicao =
      textoOpcional(avancadas.attribution_spec);

    if (atribuicaoEdicao) {
      const janelasValidas: Record<string, object> = {
        "1d_click": [{ event_type: "CLICK_THROUGH", window_days: 1 }],
        "7d_click": [{ event_type: "CLICK_THROUGH", window_days: 7 }],
        "28d_click": [{ event_type: "CLICK_THROUGH", window_days: 28 }],
        "1d_click_1d_view": [
          { event_type: "CLICK_THROUGH", window_days: 1 },
          { event_type: "VIEW_THROUGH", window_days: 1 }
        ],
        "7d_click_1d_view": [
          { event_type: "CLICK_THROUGH", window_days: 7 },
          { event_type: "VIEW_THROUGH", window_days: 1 }
        ]
      };

      if (janelasValidas[atribuicaoEdicao]) {
        payloadAdset.attribution_spec = janelasValidas[atribuicaoEdicao];
      }
    }

    let adsetRes = await enviarPayloadMetaComFallbackBid(
      `https://graph.facebook.com/v19.0/${adsetId}`,
      payloadAdset,
      "EDITAR_ADSET"
    );

    console.log(
      "EDITAR CAMPANHA PAYLOAD:",
      JSON.stringify(payloadAdset, null, 2)
    );

    console.log("EDITAR CAMPANHA RESPONSE:", adsetRes);

    // Mesmo self-healing da criação: se a janela de atribuição for incompatível
    // com o objetivo/otimização atual do conjunto, tenta de novo sem ela em vez
    // de devolver o erro cru pro usuário.
    if (adsetRes.error && payloadAdset.attribution_spec) {
      const errMsgAtribuicao = String(
        adsetRes.error?.error_user_msg ||
        adsetRes.error?.message ||
        ""
      ).toLowerCase();

      if (
        errMsgAtribuicao.includes("attribution") ||
        errMsgAtribuicao.includes("atribuição") ||
        errMsgAtribuicao.includes("atribuicao")
      ) {
        console.log("EDITAR_ADSET: attribution_spec rejeitada pela Meta, tentando sem ela...");
        delete payloadAdset.attribution_spec;
        adsetRes = await enviarPayloadMetaComFallbackBid(
          `https://graph.facebook.com/v19.0/${adsetId}`,
          payloadAdset,
          "EDITAR_ADSET_RETRY_ATTRIBUTION"
        );
      }
    }

    if (adsetRes.error) {
      return c.json({
        error: mensagemErroMeta(adsetRes, "Erro ao salvar as alterações no Meta"),
        detalhe: adsetRes.error,
        targeting_enviado: targeting
      }, 400);
    }

    const nomeNovo = textoOpcional(nome);

    if (nomeNovo) {
      await fetch(
        `https://graph.facebook.com/v19.0/${campaign_id}`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ name: nomeNovo, access_token: token })
        }
      ).catch(() => null);
    }

    // Se a atualização do criativo (imagem/vídeo/texto) falhar, a edição
    // ainda segue e salva o resto (orçamento, segmentação etc) — mas o
    // usuário precisa saber que o visual do anúncio não mudou, em vez de só
    // ver "atualizado com sucesso" enquanto o anúncio real continua com o
    // criativo antigo.
    let criativoAtualizadoComErro: any = null;

    // 🎨 ATUALIZAR CRIATIVO se campos visuais foram alterados
    try {
      const adId = campanhaBanco.rows[0]?.ad_id;
      const formId = campanhaBanco.rows[0]?.form_id;
      const cfgBanco = configuracoesBanco;

      const pageId =
        textoOpcional(avancadas.page_id) ||
        textoOpcional(cfgBanco.page_id);

      const texto =
        textoOpcional(avancadas.texto) ||
        textoOpcional(cfgBanco.texto) ||
        "Quer mais clientes? 🚀";

      const tituloAnuncio =
        textoOpcional(avancadas.titulo) ||
        textoOpcional(cfgBanco.titulo) || "";

      const descricaoAnuncio =
        textoOpcional(avancadas.descricao) ||
        textoOpcional(cfgBanco.descricao) || "";

      const linkDestino =
        destinoOriginal === "whatsapp"
          ? "https://api.whatsapp.com/send"
          : urlOpcional(
              textoOpcional(avancadas.link) ||
              textoOpcional(cfgBanco.link),
              "https://google.com"
            );

      const ctaType =
        textoOpcional(avancadas.cta) ||
        textoOpcional(cfgBanco.cta) || "LEARN_MORE";

      const imageHash =
        textoOpcional(imageHashNovo) ||
        textoOpcional(avancadas.imageHash) ||
        textoOpcional(avancadas.image_hash) ||
        textoOpcional(cfgBanco.imageHash) ||
        textoOpcional(cfgBanco.image_hash) || "";

      const imageHashes: string[] =
        (Array.isArray(imageHashesNovo) && imageHashesNovo.length
          ? imageHashesNovo
          : Array.isArray(avancadas.imageHashes) && avancadas.imageHashes.length
          ? avancadas.imageHashes
          : Array.isArray(cfgBanco.imageHashes) && cfgBanco.imageHashes.length
          ? cfgBanco.imageHashes
          : imageHash ? [imageHash] : []
        ).filter(Boolean);

      const imageUrls: string[] =
        (Array.isArray(imageUrlsNovo) && imageUrlsNovo.length
          ? imageUrlsNovo
          : Array.isArray(avancadas.imagens_urls) && avancadas.imagens_urls.length
          ? avancadas.imagens_urls
          : Array.isArray(cfgBanco.imagens_urls) && cfgBanco.imagens_urls.length
          ? cfgBanco.imagens_urls
          : []
        ).filter(Boolean);

      // Reflete a imagem nova recem-enviada em `avancadas` antes de persistir no
      // banco — sem isso o criativo na Meta ficava certo mas o registro salvo
      // (e portanto a tela de detalhes) continuava com o hash antigo, e as URLs
      // e os campos duplicados em snake_case/criativo ficavam desatualizados
      // mesmo quando o hash em si estava certo.
      sincronizarCamposImagem(avancadas, imageHashes, imageUrls);

      const videoId =
        textoOpcional(avancadas.video_id) ||
        textoOpcional(avancadas.videoId) ||
        textoOpcional(cfgBanco.video_id) ||
        textoOpcional(cfgBanco.videoId) || "";

      if (
        adId &&
        pageId &&
        (destinoOriginal === "whatsapp" || formId)
      ) {
        const ctaPayload = montarCallToActionMeta(
          destinoOriginal,
          ctaType,
          formId || null
        );

        // Carrossel misto (imagens + vídeo) exige uma miniatura (picture) no card do
        // vídeo — sem ela a Meta rejeita o object_story_spec inteiro com "picture or
        // image_hash é obrigatório". Na criação isso já vem de aguardarVideoMetaReady
        // (chamado logo após o upload do vídeo); na edição o vídeo já existe e nunca
        // era buscado, então essa miniatura ficava sempre null.
        let videoThumbnailUrl: string | null = null;
        if (videoId && imageHashes.length > 0) {
          const { picture } = await aguardarVideoMetaReady(token, videoId, 1, 0);
          videoThumbnailUrl = picture;
        }

        const conteudoCriativo = montarConteudoCriativoMeta({
          hashes: imageHashes,
          videoId: videoId || null,
          videoThumbnailUrl,
          instagramSelecionado: Array.isArray(avancadas?.plataformas) && avancadas.plataformas.includes("instagram"),
          escolhaMidiaInstagram: textoOpcional(avancadas.escolha_midia_instagram),
          videoPosicaoCarrossel: numeroOpcional(avancadas.video_posicao_carrossel),
          tituloAnuncio,
          descricaoAnuncio,
          texto,
          linkDestino,
          ctaPayload
        });

        const objectStorySpec: Record<string, any> = {
          page_id: pageId,
          ...conteudoCriativo
        };

        // Instagram actor — só faz sentido mandar esse campo quando o Instagram
        // continua marcado nesta edição. Sem essa checagem, remover o Instagram
        // de uma campanha que já teve instagram_actor_id salvo antes deixava o
        // campo "vazando" pro criativo mesmo depois de desmarcado.
        const instagramActorId =
          Array.isArray(avancadas?.plataformas) && avancadas.plataformas.includes("instagram")
            ? textoOpcional(avancadas.instagram_actor_id) || textoOpcional(cfgBanco.instagram_actor_id)
            : "";

        if (instagramActorId) {
          objectStorySpec.instagram_actor_id = instagramActorId;
        }

        const criarCreativoEdicao = async (spec: Record<string, any>) =>
          fetch(
            `https://graph.facebook.com/v19.0/${contaAnunciosId}/adcreatives`,
            {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                name: `Criativo Leads ${Date.now()}`,
                object_story_spec: spec,
                access_token: token
              })
            }
          ).then(r => r.json());

        let novoCreativo = await criarCreativoEdicao(objectStorySpec);

        // Mesmo self-healing já usado na criação (POST /meta/campanha) e no
        // attribution_spec logo acima nesta mesma função: um instagram_actor_id
        // desatualizado (a Página trocou a conta do Instagram vinculada, por
        // exemplo) derruba a criação do criativo INTEIRO — a Meta valida o
        // object_story_spec todo junto, então até o vídeo/imagem novos ficam de
        // fora quando só o campo do Instagram está errado. Primeiro tenta buscar
        // o id atual e válido direto na Meta (self-healing de verdade, não só
        // desistir do Instagram); só cai pro Facebook-only se nem isso resolver.
        if (!novoCreativo?.id && objectStorySpec.instagram_actor_id) {
          const erroCreativo = String(
            novoCreativo?.error?.error_user_msg ||
            novoCreativo?.error?.message ||
            ""
          ).toLowerCase();

          if (
            erroCreativo.includes("instagram_actor_id") ||
            erroCreativo.includes("instagram account")
          ) {
            console.warn(
              "EDITAR CAMPANHA: instagram_actor_id salvo está inválido, buscando o atual na Meta:",
              novoCreativo?.error
            );

            const contasInstagramAtuais =
              await listarContasInstagramAnuncio(token, contaAnunciosId);
            const instagramActorIdAtual =
              contasInstagramAtuais[0]?.id || null;

            if (
              instagramActorIdAtual &&
              instagramActorIdAtual !== objectStorySpec.instagram_actor_id
            ) {
              novoCreativo = await criarCreativoEdicao({
                ...objectStorySpec,
                instagram_actor_id: instagramActorIdAtual
              });

              if (novoCreativo?.id) {
                avancadas.instagram_actor_id = instagramActorIdAtual;
              }
            }

            if (!novoCreativo?.id) {
              const specSemInstagram = { ...objectStorySpec };
              delete specSemInstagram.instagram_actor_id;
              novoCreativo = await criarCreativoEdicao(specSemInstagram);
            }
          }
        }

        if (novoCreativo?.id) {
          const anexarRes = await fetch(
            `https://graph.facebook.com/v19.0/${adId}`,
            {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                creative: { creative_id: novoCreativo.id },
                access_token: token
              })
            }
          ).then(r => r.json()).catch(e => ({ error: { message: String(e) } }));

          if (anexarRes?.error) {
            // Criativo foi criado na Meta mas não ficou vinculado a este anúncio
            // — sem isso o que o usuário vê continua sendo o criativo antigo,
            // mesmo com um criativo novo (órfão) já existindo na conta.
            criativoAtualizadoComErro = anexarRes.error;
            console.warn("EDITAR CAMPANHA: criativo criado mas não vinculado ao anúncio:", anexarRes.error);
          } else {
            avancadas.creative_id = novoCreativo.id;
            if (avancadas.criativo) {
              avancadas.criativo.creative_id = novoCreativo.id;
            }
          }
        } else {
          criativoAtualizadoComErro = novoCreativo?.error || { message: "Erro desconhecido ao criar criativo" };
          console.warn("EDITAR CAMPANHA: criativo não atualizado na Meta:", novoCreativo?.error);
        }
      }
    } catch (errCreativo: any) {
      criativoAtualizadoComErro = { message: errCreativo?.message || String(errCreativo) };
      console.warn("EDITAR CAMPANHA: erro ao atualizar criativo (ignorado):", errCreativo);
    }

    await client.query(
      `
      UPDATE campanhas
      SET
        configuracoes_avancadas = $1,
        daily_budget = COALESCE($2, daily_budget),
        nome = COALESCE($3, nome),
        atualizado_em = NOW()
      WHERE id = $4
      `,
      [
        JSON.stringify(avancadas),
        dailyBudget,
        nomeNovo,
        campanhaBanco.rows[0].id
      ]
    );

    return c.json({
      sucesso: true,
      aviso: criativoAtualizadoComErro
        ? "As demais alterações foram salvas, mas não foi possível atualizar o criativo (imagem/vídeo/texto) do anúncio na Meta: " +
          (criativoAtualizadoComErro.error_user_msg || criativoAtualizadoComErro.message || "erro desconhecido") +
          ". O anúncio publicado continua com o criativo anterior."
        : null
    });

  } catch (err) {

    console.error("EDITAR CAMPANHA:", err);

    return c.json({
      error: "Erro ao editar campanha"
    }, 500);
  }
});


app.post("/campanhas/:id/publicar-recebida", authMiddleware, async (c) => {

  let campanhaId = 0;
  let campaignMetaId: string | null = null;
  let token = "";

  const falhar = async (
    mensagem: string,
    detalhe: any = null,
    status = 400
  ) => {
    if (campanhaId) {
      await registrarErroPublicacaoCampanha(campanhaId, mensagem);
    }

    if (campaignMetaId && token) {
      await fetch(
        `https://graph.facebook.com/v19.0/${campaignMetaId}`,
        {
          method: "DELETE",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ access_token: token })
        }
      ).catch(() => null);
    }

    return c.json({
      error: mensagem,
      detalhe
    }, status);
  };

  try {

    const user: any = c.get("user");

    campanhaId =
      Number(c.req.param("id"));

    if (!Number.isFinite(campanhaId) || campanhaId <= 0) {
      return c.json({
        error: "Campanha inválida"
      }, 400);
    }

    const campanhaRes = await client.query(
      `
      SELECT c.*
      FROM campanhas c
      WHERE c.id = $1
      AND c.usuario_id = $2
      LIMIT 1
      `,
      [campanhaId, user.id]
    );

    if (!campanhaRes.rows.length) {
      return c.json({
        error: "Campanha não disponível para este usuário"
      }, 404);
    }

    const campanha = campanhaRes.rows[0];
    const cfg = campanha.configuracoes_avancadas || {};
    const destino = resolverDestinoCampanha(cfg.destino);
    let whatsappPhoneNumber: string | null = null;

    if (destino === "whatsapp") {
      whatsappPhoneNumber =
        await obterNumeroWhatsappConectadoUsuario(user.id);

      if (!whatsappPhoneNumber) {
        return await falhar(
          "Conecte novamente o WhatsApp da plataforma para confirmar o número que receberá as conversas desta campanha."
        );
      }
    }

    const conn = await client.query(
      `
      SELECT access_token, conta_anuncios_id
      FROM meta_conexoes
      WHERE usuario_id = $1
      ORDER BY id DESC
      LIMIT 1
      `,
      [user.id]
    );

    if (!conn.rows.length) {
      return await falhar(
        "Meta não conectada. Conecte sua conta Meta antes de publicar esta campanha."
      );
    }

    token = conn.rows[0].access_token;

    const contaAds =
      await obterContaAnuncios(
        token,
        conn.rows[0].conta_anuncios_id
      );

    if (!contaAds) {
      return await falhar(
        "Nenhuma conta de anúncios encontrada na Meta conectada."
      );
    }

    const adAccountId = contaAds.id;

    const pages = await fetch(
      `https://graph.facebook.com/v19.0/me/accounts?fields=id,name,access_token,instagram_business_account{id,username},connected_instagram_account{id,username}&access_token=${token}`
    ).then(r => r.json());

    if (!Array.isArray(pages.data) || !pages.data.length) {
      return await falhar(
        "Nenhuma Página do Facebook encontrada na Meta conectada. Configure uma página antes de publicar."
      );
    }

    let page =
      pages.data.find((p: any) => p.id === textoOpcional(cfg.page_id)) ||
      pages.data[0];

    const pageId =
      page.id;

    const pageToken =
      page.access_token;

    if (!pageId || !pageToken) {
      return await falhar(
        "A Página selecionada não retornou token de acesso. Reconecte a Meta e tente novamente."
      );
    }

    const valorOrcamento =
      Number(campanha.daily_budget || cfg.daily_budget || cfg.orcamento_diario_centavos || 0) ||
      Math.round(Number(cfg.orcamento || cfg.orcamento_diario || 20) * 100);

    const dailyBudget =
      Math.max(100, Math.round(valorOrcamento));

    const categoriaEspecial =
      textoOpcional(cfg.categoria_especial);

    const payloadCampanha: any = {
      name: campanha.nome || cfg.nome || "Campanha Leads Plataforma",
      objective: montarObjetivoCampanhaMeta(destino, cfg.objetivo),
      status: "ACTIVE",
      special_ad_categories: categoriaEspecial ? [categoriaEspecial] : [],
      is_adset_budget_sharing_enabled: false,
      access_token: token
    };

    if (cfg.cbo ?? true) {
      payloadCampanha.daily_budget = dailyBudget;

      // Com CBO a estrategia de lance precisa estar na campanha (nao no adset);
      // sem isso a Meta pode rejeitar exigindo valor de lance mesmo em "menor custo possivel".
      const { bidStrategy, bidAmount } =
        prepararControleCustoMeta(cfg.bid_strategy, cfg.bid_amount);

      payloadCampanha.bid_strategy = bidStrategy || "LOWEST_COST_WITHOUT_CAP";

      if (bidAmount !== null && bidStrategyExigeValor(payloadCampanha.bid_strategy)) {
        payloadCampanha.bid_amount = Math.round(bidAmount * 100);
      }
    }

    const campanhaMeta = await enviarPayloadMetaComFallbackBid(
      `https://graph.facebook.com/v19.0/${adAccountId}/campaigns`,
      payloadCampanha,
      "PUBLICAR_RECEBIDA_CAMPANHA"
    );

    if (!campanhaMeta.id) {
      return await falhar(
        mensagemErroMeta(campanhaMeta, "Erro ao criar campanha na Meta"),
        campanhaMeta
      );
    }

    campaignMetaId = campanhaMeta.id;

    const perguntasExtras =
      Array.isArray(cfg.perguntas)
        ? cfg.perguntas
        : Array.isArray(cfg.perguntas_qualificacao)
          ? cfg.perguntas_qualificacao
          : [];

    let formMeta: { id: string | null } = { id: null };

    if (destino !== "whatsapp") {
      const payloadFormulario: any = {
        name: `Form ${campanha.nome || "Leads"} ${Date.now()}`,
        locale: "pt_BR",
        questions: [
          { type: "FULL_NAME" },
          { type: "EMAIL" },
          { type: "PHONE" },
          ...perguntasExtras.slice(0, 4).map((pergunta: string, index: number) => ({
            type: "CUSTOM",
            key: `qualificacao_${index + 1}`,
            label: pergunta
          }))
        ],
        privacy_policy: {
          url: urlOpcional(cfg.privacidade_url || cfg.url_privacidade, "https://google.com"),
          link_text:
            textoOpcional(cfg.privacidade_texto) ||
            "Política de Privacidade"
        },
        thank_you_page: {
          title:
            textoOpcional(cfg.obrigado_titulo) ||
            textoOpcional(cfg.mensagem_agradecimento_titulo) ||
            "Obrigado!",
          body:
            textoOpcional(cfg.obrigado_texto) ||
            textoOpcional(cfg.mensagem_agradecimento) ||
            "Recebemos seus dados 🚀",
          button_type: "VIEW_WEBSITE",
          button_text:
            textoOpcional(cfg.obrigado_botao) ||
            "Ver mais",
          website_url: urlOpcional(
            cfg.obrigado_url || cfg.url_privacidade || cfg.privacidade_url,
            "https://google.com"
          )
        },
        access_token: pageToken
      };

      if (cfg.formulario_qualidade) {
        payloadFormulario.is_optimized_for_quality = true;
      }

      formMeta = await fetch(
        `https://graph.facebook.com/v19.0/${pageId}/leadgen_forms`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payloadFormulario)
        }
      ).then(r => r.json());

      if (!formMeta.id) {
        return await falhar(
          mensagemErroMeta(formMeta, "Erro ao criar formulário de leads na Meta"),
          formMeta
        );
      }
    }

    const targeting =
      montarTargetingMeta(cfg);

    if (
      [
        "HOUSING",
        "CREDIT",
        "EMPLOYMENT"
      ].includes(categoriaEspecial)
    ) {
      delete targeting.age_min;
      delete targeting.age_max;
      delete targeting.genders;
    }

    const controleCusto =
      prepararControleCustoMeta(
        cfg.bid_strategy,
        cfg.bid_amount
      );

    const payloadAdset: any = {
      name: `AdSet ${campanha.nome || "Leads"} ${Date.now()}`,
      campaign_id: campanhaMeta.id,
      billing_event: "IMPRESSIONS",
      ...montarDestinoAdsetMeta(destino, pageId, whatsappPhoneNumber),
      start_time: new Date(Date.now() + 60000).toISOString(),
      targeting,
      status: "ACTIVE",
      access_token: token
    };

    if (controleCusto.bidStrategy) {
      payloadAdset.bid_strategy =
        controleCusto.bidStrategy;
    }

    if (!(cfg.cbo ?? true)) {
      payloadAdset.daily_budget = dailyBudget;
    }

    if (
      controleCusto.bidAmount !== null &&
      bidStrategyExigeValor(payloadAdset.bid_strategy)
    ) {
      payloadAdset.bid_amount =
        Math.round(controleCusto.bidAmount * 100);
    }

    const fim =
      textoOpcional(cfg.fim);

    if (fim) {
      payloadAdset.end_time =
        new Date(fim).toISOString();
    }

    const adsetMeta = await criarAdSetMetaParaDestino(
      `https://graph.facebook.com/v19.0/${adAccountId}/adsets`,
      payloadAdset,
      "PUBLICAR_RECEBIDA_ADSET",
      user.id,
      destino
    );

    if (!adsetMeta.id) {
      return await falhar(
        mensagemErroMeta(adsetMeta, "Erro ao criar conjunto de anúncios na Meta"),
        adsetMeta
      );
    }

    // imagens_urls/image_urls às vezes acumulam a MESMA imagem varias vezes
    // (URLs diferentes por parâmetro de cache do CDN, mesmo conteúdo) — sem
    // dedupe aqui, cada URL vira um card de carrossel repetido e a Meta
    // rejeita com "(#105) param child_attachments has too many elements".
    const imageUrls =
      [...new Set([
        ...(Array.isArray(cfg.imagens_urls) ? cfg.imagens_urls : []),
        ...(Array.isArray(cfg.image_urls) ? cfg.image_urls : [])
      ].filter(Boolean))];

    const instagramSelecionado =
      Array.isArray(cfg.plataformas) && cfg.plataformas.includes("instagram");
    const escolhaMidiaInstagram =
      textoOpcional(cfg.escolha_midia_instagram);
    const videoIdSalvo =
      textoOpcional(cfg.video_id) ||
      textoOpcional(cfg.videoId) ||
      null;
    const videoEscolhidoExplicitamente =
      instagramSelecionado && escolhaMidiaInstagram === "video";

    if (videoEscolhidoExplicitamente && !videoIdSalvo) {
      return await falhar(
        "O vídeo escolhido para o Instagram não está mais disponível nesta campanha. Edite a campanha, envie o vídeo novamente e tente publicar."
      );
    }

    let videoMetaId: string | null = null;
    let videoThumbnailUrl: string | null = null;
    const deveUsarVideo =
      Boolean(videoIdSalvo) &&
      (!instagramSelecionado || escolhaMidiaInstagram !== "imagens");

    if (deveUsarVideo && videoIdSalvo) {
      const videoMeta =
        await aguardarVideoMetaReady(token, videoIdSalvo, 1, 0);

      if (!videoMeta.ready) {
        return await falhar(
          "O vídeo escolhido não está disponível na conta de anúncios Meta atual. Edite esta campanha, envie o vídeo novamente e tente publicar."
        );
      }

      videoMetaId = videoIdSalvo;
      videoThumbnailUrl = videoMeta.picture;
    }

    const publicarSomenteVideo =
      instagramSelecionado &&
      Boolean(videoMetaId) &&
      escolhaMidiaInstagram !== "imagens";

    const hashes: string[] = [];

    if (!publicarSomenteVideo) {
      for (const urlImagem of imageUrls) {
        const uploadImagem =
          await enviarImagemMetaPorUrl(token, adAccountId, String(urlImagem));

        if (uploadImagem.hash) {
          // A Meta hasheia por conteúdo — URLs distintas da mesma imagem (ex.:
          // espelhos de CDN diferentes) voltam com o hash igual; sem este
          // dedupe, o card de carrossel se repete mesmo com URLs únicas.
          if (!hashes.includes(uploadImagem.hash)) {
            hashes.push(uploadImagem.hash);
          }
        } else {
          // Não existe fallback seguro para reaproveitar cfg.imageHash aqui: hashes de
          // imagem na Meta são específicos por conta de anúncios, e o hash salvo em
          // configuracoes_avancadas pertence à conta de quem encaminhou a campanha, não
          // à de quem está publicando agora. Reaproveitá-lo cria um anúncio que a Meta
          // aceita na criação mas rejeita na revisão ("Imagem não encontrada"). O link
          // de imagem da Meta usado no reenvio por URL também expira com o tempo, então
          // essa falha é esperada em campanhas encaminhadas há mais tempo.
          console.error(
            "PUBLICAR_RECEBIDA: falha ao reenviar imagem por URL (provável link expirado):",
            urlImagem, JSON.stringify(uploadImagem.resposta)
          );
        }
      }
    }

    if (!hashes.length && !videoMetaId) {
      return await falhar(
        "Não foi possível preparar a mídia original desta campanha para sua conta de anúncios. Edite a campanha, envie uma imagem ou vídeo novamente e tente publicar."
      );
    }

    const linkDestino =
      destino === "whatsapp"
        ? "https://api.whatsapp.com/send"
        : urlOpcional(cfg.link, "https://google.com");

    const tituloAnuncio =
      textoOpcional(cfg.titulo) ||
      campanha.nome ||
      "Saiba mais";

    const descricaoAnuncio =
      textoOpcional(cfg.descricao) ||
      "Entre em contato agora";

    const ctaType =
      textoOpcional(cfg.cta) ||
      "LEARN_MORE";

    const conteudoCriativo = montarConteudoCriativoMeta({
      hashes,
      videoId: videoMetaId,
      videoThumbnailUrl,
      instagramSelecionado,
      escolhaMidiaInstagram,
      videoPosicaoCarrossel: numeroOpcional(cfg.video_posicao_carrossel),
      tituloAnuncio,
      descricaoAnuncio,
      texto:
        textoOpcional(cfg.texto) ||
        textoOpcional(campanha.texto) ||
        "Entre em contato agora",
      linkDestino,
      ctaPayload: montarCallToActionMeta(destino, ctaType, formMeta.id)
    });

    const objectStorySpec: Record<string, any> = {
      page_id: pageId,
      ...conteudoCriativo
    };

    if (instagramSelecionado) {
      const instagramPaginaId =
        textoOpcional(page.instagram_business_account?.id) ||
        textoOpcional(page.connected_instagram_account?.id) ||
        null;
      const contasInstagramAnuncio =
        await listarContasInstagramAnuncio(token, adAccountId);
      const instagramContaId =
        textoOpcional(contasInstagramAnuncio[0]?.id) ||
        null;

      if (!instagramPaginaId && !instagramContaId) {
        return await falhar(
          "Nenhuma conta do Instagram está vinculada à sua conta de anúncios da Meta conectada. Vincule uma conta do Instagram a essa conta de anúncios no Gerenciador de Negócios antes de publicar para o Instagram."
        );
      }

      if (instagramPaginaId) {
        // O creative original que efetivamente entregou no Instagram não enviou
        // instagram_actor_id no object_story_spec. A Meta resolveu o vínculo da
        // Página e devolveu a identidade aplicada no campo instagram_user_id.
        console.log("PUBLICAR_RECEBIDA_IDENTIDADE_INSTAGRAM:", JSON.stringify({
          estrategia: "page_linked_instagram_user",
          page_id: pageId,
          instagram_user_id: instagramPaginaId,
          disponivel_na_conta_anuncios: contasInstagramAnuncio.some(
            (conta: any) => String(conta.id) === String(instagramPaginaId)
          )
        }));
      } else {
        // Compatibilidade para uma conta de Instagram liberada diretamente para a
        // conta de anúncios, mas sem vínculo retornado na Página selecionada.
        objectStorySpec.instagram_actor_id = instagramContaId;
      }
    }

    const criarCreativeRecebido = async (spec: Record<string, any>) => {
      const payloadCreative = {
        name: `Criativo Leads ${Date.now()}`,
        object_story_spec: spec,
        access_token: token
      };

      // Registra a estrutura exata enviada à Meta, sem expor o token de acesso.
      console.log(
        "PUBLICAR_RECEBIDA_ADCREATIVE_PAYLOAD:",
        JSON.stringify({ ...payloadCreative, access_token: "[REDACTED]" })
      );

      return fetch(
        `https://graph.facebook.com/v19.0/${adAccountId}/adcreatives`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payloadCreative)
        }
      ).then(r => r.json());
    };

    let creativeMeta =
      await criarCreativeRecebido(objectStorySpec);

    // Mesmo fallback já comprovado no fluxo normal de publicação: se a Meta
    // rejeitar o instagram_actor_id de uma conta sem vínculo direto à Página,
    // deixa a plataforma usar a identidade page-backed.
    if (!creativeMeta?.id && objectStorySpec.instagram_actor_id) {
      const erroCreativo = String(
        creativeMeta?.error?.error_user_msg ||
        creativeMeta?.error?.message ||
        ""
      ).toLowerCase();

      if (
        erroCreativo.includes("instagram_actor_id") ||
        erroCreativo.includes("instagram account")
      ) {
        console.warn(
          "PUBLICAR_RECEBIDA: instagram_actor_id rejeitado; tentando identidade page-backed:",
          creativeMeta?.error
        );
        const specSemInstagramActor = { ...objectStorySpec };
        delete specSemInstagramActor.instagram_actor_id;
        creativeMeta =
          await criarCreativeRecebido(specSemInstagramActor);
      }
    }

    if (!creativeMeta.id) {
      return await falhar(
        mensagemErroMeta(creativeMeta, "Erro ao criar criativo na Meta"),
        creativeMeta
      );
    }

    const adMeta = await fetch(
      `https://graph.facebook.com/v19.0/${adAccountId}/ads`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: `Anúncio Leads ${Date.now()}`,
          adset_id: adsetMeta.id,
          creative: {
            creative_id: creativeMeta.id
          },
          status: "ACTIVE",
          access_token: token
        })
      }
    ).then(r => r.json());

    if (!adMeta.id) {
      return await falhar(
        mensagemErroMeta(adMeta, "Erro ao criar anúncio na Meta"),
        adMeta
      );
    }

    const configuracoesPublicadas = {
      ...cfg,
      destino,
      page_id: pageId,
      form_id: formMeta.id,
      creative_id: creativeMeta.id,
      adset_id: adsetMeta.id,
      ad_id: adMeta.id,
      imageHashes: hashes,
      imageHash: hashes[0] || null,
      publicado_por_usuario_id: user.id,
      publicado_em: new Date().toISOString()
    };

    await client.query(
      `
      UPDATE campanhas
      SET
        campaign_id = $1,
        adset_id = $2,
        ad_id = $3,
        form_id = $4,
        page_id = $5,
        conta_anuncios_id = $6,
        status = 'ACTIVE',
        origem = 'plataforma',
        daily_budget = $7,
        configuracoes_avancadas = $8,
        atualizado_em = NOW()
      WHERE id = $9
      `,
      [
        campanhaMeta.id,
        adsetMeta.id,
        adMeta.id,
        formMeta.id,
        pageId,
        adAccountId,
        dailyBudget,
        JSON.stringify(configuracoesPublicadas),
        campanhaId
      ]
    );

    await limparErroPublicacaoCampanha(campanhaId);

    return c.json({
      sucesso: true,
      campaign_id: campanhaMeta.id,
      adset_id: adsetMeta.id,
      ad_id: adMeta.id,
      form_id: formMeta.id
    });

  } catch (err: any) {

    console.error("PUBLICAR CAMPANHA RECEBIDA:", err);

    return await falhar(
      err?.message || "Erro ao publicar campanha recebida",
      err,
      500
    );
  }
});


// 🔹 criar lead
// 🧪 TESTE TEMPORÁRIO — enviar notif WhatsApp para leads das últimas 24h
app.post("/leads", authMiddleware, async (c) => {
  try {
    const body = await c.req.json();
    const user: any = c.get("user");


    if (!body.nome) {
      return c.json({ error: "Nome obrigatório" }, 400);
    }

    await client.query(
      "INSERT INTO leads (nome, telefone, email, usuario_id, origem, plataforma) VALUES ($1,$2,$3,$4,'manual','formulario')",
      [body.nome, body.telefone, body.email, user.id]
    );

    await notificarNovoLeadWhatsApp(user.id, { nome: body.nome, telefone: body.telefone, email: body.email });

    return c.json({ message: "Lead salvo com sucesso" });
  } catch (err) {
    console.error("LEAD ERROR:", err);
    return c.json({ error: "Erro ao salvar lead" }, 500);
  }
});

// 🔔 TESTE DE NOTIFICAÇÃO WHATSAPP
app.post("/teste/notif-whatsapp", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const row = await client.query(
      `SELECT whatsapp, notif_whatsapp_lead FROM usuarios WHERE id = $1`,
      [user.id]
    );
    const u = row.rows[0];
    if (!u?.whatsapp) {
      return c.json({ erro: "Nenhum número de WhatsApp cadastrado no perfil." }, 400);
    }

    const numero = String(u.whatsapp).replace(/\D/g, "");
    const phone = numero.startsWith("55") ? numero : `55${numero}`;

    const instanceId  = Bun.env.ZAPI_INSTANCE_ID;
    const token       = Bun.env.ZAPI_TOKEN;
    const clientToken = Bun.env.ZAPI_CLIENT_TOKEN || "";

    if (!instanceId || !token) {
      return c.json({ erro: "ZAPI_INSTANCE_ID ou ZAPI_TOKEN não configurados no servidor." }, 500);
    }

    const agora = new Date().toLocaleString("pt-BR", {
      timeZone: "America/Sao_Paulo",
      day: "2-digit", month: "2-digit",
      hour: "2-digit", minute: "2-digit"
    });

    const msg = `✅ *Teste de notificação — Plataforma de Leads*\n\nSe você recebeu esta mensagem, as notificações de novos leads estão funcionando corretamente.\n\n⏰ ${agora}`;

    const res = await fetch(
      `https://api.z-api.io/instances/${instanceId}/token/${token}/send-text`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(clientToken ? { "Client-Token": clientToken } : {})
        },
        body: JSON.stringify({ phone, message: msg })
      }
    );

    const resposta = await res.json().catch(() => ({}));
    if (res.ok) {
      return c.json({ ok: true, phone, resposta });
    } else {
      return c.json({ erro: "Z-API retornou erro", status: res.status, resposta }, 500);
    }
  } catch (err: any) {
    return c.json({ erro: err?.message || "Erro desconhecido" }, 500);
  }
});

// 🔹 leads por plataforma (stats para o dashboard)
app.get("/leads/stats/plataformas", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    // Mesmo NULLIF já usado em /leads/meta-conversao/estatisticas: leads criados a partir
    // de uma conversa (CTWA da Meta, wa.me do LinkedIn etc.) gravam plataforma='whatsapp'
    // (o canal de conversão) mesmo vindo de um anúncio real — quem diz a rede de anúncio
    // nesse caso é "origem". Sem o NULLIF, esses leads formavam um balde "whatsapp" à parte,
    // desligado da plataforma que pagou pelo anúncio. canal_whatsapp deixa o front saber
    // quais linhas são desse tipo pra poder rotular como "Meta Ads · WhatsApp" em vez de só
    // "Meta Ads" (perderia a info de que veio de conversa, não formulário) ou só "whatsapp"
    // (perderia de qual plataforma veio o anúncio).
    // Dentro do balde 'meta', refina pra facebook/instagram quando a campanha
    // do lead (campanha_id) tiver essa marcação — mesma resolução usada em
    // /meta/status-completo e no front (plataformaCampanhaExibicao). Campanha
    // legada combinada, sem campanha vinculada, ou sem essa marcação continua
    // caindo em 'meta' genérico.
    const result = await client.query(
      `SELECT
         CASE
           WHEN COALESCE(NULLIF(l.plataforma, 'whatsapp'), l.origem, 'formulario') = 'meta'
           THEN COALESCE(
             CASE
               WHEN c.configuracoes_avancadas->'plataformas' = '["facebook"]'::jsonb THEN 'facebook'
               WHEN c.configuracoes_avancadas->'plataformas' = '["instagram"]'::jsonb THEN 'instagram'
             END,
             'meta'
           )
           ELSE COALESCE(NULLIF(l.plataforma, 'whatsapp'), l.origem, 'formulario')
         END AS plataforma,
         (l.plataforma = 'whatsapp') AS canal_whatsapp,
         COUNT(*)::int AS total
       FROM leads l
       LEFT JOIN campanhas c ON c.id = l.campanha_id
       WHERE l.usuario_id = $1
       GROUP BY 1, 2
       ORDER BY total DESC`,
      [user.id]
    );
    return c.json(result.rows);
  } catch (err) {
    console.error("ERRO stats plataformas:", err);
    return c.json({ error: "Erro ao carregar stats" }, 500);
  }
});

// 🔹 dashboard "IA & Performance Meta" — o que já foi enviado pro Conversion
// Leads da Meta (ver avaliarEEnviarQualificacaoMeta) e os últimos eventos.
app.get("/leads/meta-conversao/estatisticas", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");

    // Parecido com o fallback de plataforma usado em GET /leads (mesma ideia
    // de COALESCE entre plataforma/origem/'formulario'), mas com um ajuste: leads
    // vindos de conversa CTWA (criarLeadDeConversaCTWA) gravam
    // plataforma='whatsapp' (o canal — pra mostrar o ícone certo em outras
    // telas) mesmo vindo de um anúncio Meta (origem='meta'). Sem o
    // NULLIF abaixo, esses leads não batiam em nenhum dos 3 baldes (nem meta,
    // nem google, nem tiktok) e sumiam da contagem de qualificados/fechados
    // enviados mesmo já tendo sido enviados de verdade — foi visto acontecer
    // com um lead real que tinha o badge "Qualificação enviada à Meta" na
    // Central de Leads mas não aparecia aqui. Google e TikTok seguem o mesmo
    // padrão de 3 números (total/qualificados/fechados) que a Meta já tinha,
    // só trocando as colunas de rastreio.
    const resumo = await client.query(
      `
      SELECT
        COUNT(*) FILTER (
          WHERE COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'meta'
        )::int AS total_leads_meta,
        COUNT(*) FILTER (
          WHERE meta_evento_qualificado_enviado_em IS NOT NULL
          AND COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'meta'
        )::int AS qualificados_enviados,
        COUNT(*) FILTER (
          WHERE meta_evento_fechado_enviado_em IS NOT NULL
          AND COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'meta'
        )::int AS fechados_enviados,

        COUNT(*) FILTER (
          WHERE COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'google'
        )::int AS total_leads_google,
        COUNT(*) FILTER (
          WHERE google_evento_qualificado_enviado_em IS NOT NULL
          AND COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'google'
        )::int AS qualificados_enviados_google,
        COUNT(*) FILTER (
          WHERE google_evento_fechado_enviado_em IS NOT NULL
          AND COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'google'
        )::int AS fechados_enviados_google,

        COUNT(*) FILTER (
          WHERE COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'tiktok'
        )::int AS total_leads_tiktok,
        COUNT(*) FILTER (
          WHERE tiktok_evento_qualificado_enviado_em IS NOT NULL
          AND COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'tiktok'
        )::int AS qualificados_enviados_tiktok,
        COUNT(*) FILTER (
          WHERE tiktok_evento_fechado_enviado_em IS NOT NULL
          AND COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'tiktok'
        )::int AS fechados_enviados_tiktok,

        COUNT(*) FILTER (
          WHERE COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'kwai'
        )::int AS total_leads_kwai,
        COUNT(*) FILTER (
          WHERE kwai_evento_qualificado_enviado_em IS NOT NULL
          AND COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'kwai'
        )::int AS qualificados_enviados_kwai,
        COUNT(*) FILTER (
          WHERE kwai_evento_fechado_enviado_em IS NOT NULL
          AND COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') = 'kwai'
        )::int AS fechados_enviados_kwai
      FROM leads
      WHERE usuario_id = $1
      `,
      [user.id]
    );

    const {
      total_leads_meta, qualificados_enviados, fechados_enviados,
      total_leads_google, qualificados_enviados_google, fechados_enviados_google,
      total_leads_tiktok, qualificados_enviados_tiktok, fechados_enviados_tiktok,
      total_leads_kwai, qualificados_enviados_kwai, fechados_enviados_kwai
    } = resumo.rows[0];

    const taxa = (num: number, den: number) => den > 0 ? (num / den) * 100 : null;

    const ultimosEventos = await client.query(
      `
      SELECT
        nome,
        COALESCE(NULLIF(plataforma, 'whatsapp'), origem, 'formulario') AS plataforma,
        meta_evento_qualificado_enviado_em,
        meta_evento_fechado_enviado_em,
        google_evento_qualificado_enviado_em,
        google_evento_fechado_enviado_em,
        tiktok_evento_qualificado_enviado_em,
        tiktok_evento_fechado_enviado_em,
        kwai_evento_qualificado_enviado_em,
        kwai_evento_fechado_enviado_em
      FROM leads
      WHERE usuario_id = $1
      AND (
        meta_evento_qualificado_enviado_em IS NOT NULL
        OR meta_evento_fechado_enviado_em IS NOT NULL
        OR google_evento_qualificado_enviado_em IS NOT NULL
        OR google_evento_fechado_enviado_em IS NOT NULL
        OR tiktok_evento_qualificado_enviado_em IS NOT NULL
        OR tiktok_evento_fechado_enviado_em IS NOT NULL
        OR kwai_evento_qualificado_enviado_em IS NOT NULL
        OR kwai_evento_fechado_enviado_em IS NOT NULL
      )
      ORDER BY
        COALESCE(
          meta_evento_fechado_enviado_em, meta_evento_qualificado_enviado_em,
          google_evento_fechado_enviado_em, google_evento_qualificado_enviado_em,
          tiktok_evento_fechado_enviado_em, tiktok_evento_qualificado_enviado_em,
          kwai_evento_fechado_enviado_em, kwai_evento_qualificado_enviado_em
        ) DESC
      LIMIT 30
      `,
      [user.id]
    );

    return c.json({
      total_leads_meta,
      qualificados_enviados,
      fechados_enviados,
      taxa_qualificacao: taxa(qualificados_enviados, total_leads_meta),
      taxa_fechamento: taxa(fechados_enviados, total_leads_meta),

      total_leads_google,
      qualificados_enviados_google,
      fechados_enviados_google,
      taxa_qualificacao_google: taxa(qualificados_enviados_google, total_leads_google),
      taxa_fechamento_google: taxa(fechados_enviados_google, total_leads_google),

      total_leads_tiktok,
      qualificados_enviados_tiktok,
      fechados_enviados_tiktok,
      taxa_qualificacao_tiktok: taxa(qualificados_enviados_tiktok, total_leads_tiktok),
      taxa_fechamento_tiktok: taxa(fechados_enviados_tiktok, total_leads_tiktok),

      total_leads_kwai,
      qualificados_enviados_kwai,
      fechados_enviados_kwai,
      taxa_qualificacao_kwai: taxa(qualificados_enviados_kwai, total_leads_kwai),
      taxa_fechamento_kwai: taxa(fechados_enviados_kwai, total_leads_kwai),

      ultimos_eventos: ultimosEventos.rows.map(row => {
        const fechadoEm =
          row.meta_evento_fechado_enviado_em ||
          row.google_evento_fechado_enviado_em ||
          row.tiktok_evento_fechado_enviado_em ||
          row.kwai_evento_fechado_enviado_em;
        return {
          nome: row.nome,
          plataforma: row.plataforma,
          tipo: fechadoEm ? "fechado" : "qualificado",
          enviado_em:
            fechadoEm ||
            row.meta_evento_qualificado_enviado_em ||
            row.google_evento_qualificado_enviado_em ||
            row.tiktok_evento_qualificado_enviado_em ||
            row.kwai_evento_qualificado_enviado_em
        };
      })
    });

  } catch (err) {
    console.error("ERRO estatisticas meta-conversao:", err);
    return c.json({ error: "Erro ao carregar estatisticas" }, 500);
  }
});

// 🔹 listar leads
app.get("/leads", authMiddleware, async (c) => {

  try {

    const user: any = c.get("user");

    console.log("USER AUTH:", user);

    const contaAnunciosId =
      await obterContaAnunciosSelecionadaIdUsuario(
        user.id
      );

    const result = await client.query(
      `
      SELECT
        l.id,
        l.nome,
        l.telefone,
        l.email,
        l.status,
        l.origem,
        l.campanha,
        l.observacao,
        l.score,
        l.score_manual,
        l.motivo_perda,
        l.respostas_qualificacao,
        l.criado_em,
        l.nicho_id,
        n.slug AS nicho_slug,
        n.nome AS nicho_nome,
        n.cor  AS nicho_cor,
        l.data_contato,
        l.observacao_agendamento,
        l.meta_evento_qualificado_enviado_em,
        l.meta_evento_fechado_enviado_em,
        l.google_evento_qualificado_enviado_em,
        l.google_evento_fechado_enviado_em,
        l.tiktok_evento_qualificado_enviado_em,
        l.tiktok_evento_fechado_enviado_em,
        l.kwai_evento_qualificado_enviado_em,
        l.kwai_evento_fechado_enviado_em,
        COALESCE(l.plataforma, l.origem, 'formulario') AS plataforma,
        l.rede_origem,
        wt.transcricao AS whatsapp_transcricao
      FROM leads l
      LEFT JOIN nichos n ON n.id = l.nicho_id
      LEFT JOIN (
        SELECT wc.lead_id, string_agg(wml.conteudo, ' ' ORDER BY wml.criado_em) AS transcricao
        FROM whatsapp_mensagens_log wml
        JOIN whatsapp_conversas wc ON wc.id = wml.conversa_id
        WHERE wc.lead_id IS NOT NULL AND wml.direcao IN ('entrada', 'echo')
        GROUP BY wc.lead_id
      ) wt ON wt.lead_id = l.id
      WHERE l.usuario_id = $1
      AND (
        COALESCE(l.origem, 'manual') <> 'meta'
        OR l.conta_anuncios_id = $2
      )
      ORDER BY l.criado_em DESC
      `,
      [user.id, contaAnunciosId]
    );

    marcarLeadsRecorrentes(result.rows);

    // 🔥 separa por status
    const leads = {
      novos: [],
      primeiro_contato: [],
      em_conversa: [],
      fechado: [],
      perdido: []
    };

    const modeloMLLeads =
      usuarioTemRecurso(
        user,
        "machine_learning_leads"
      )
        ? treinarModeloMLLeads(result.rows)
        : null;
    
    for (const lead of result.rows) {

      // 🔥 SCORE AUTOMÁTICO
      const scoreData =
        calcularScoreLead(lead);
      
      lead.score =
        scoreData.score;
      
      lead.score_base =
        scoreData.base;

      lead.score_pontos =
        scoreData.pontos;

      if (modeloMLLeads) {
        lead.ml_leads =
          preverConversaoMLLead(
            modeloMLLeads,
            lead
          );
        aplicarMLAoScoreLead(lead);
      }

      if (usuarioTemIA(user)) {
        lead.ia_leads =
          gerarAnaliseIAOuroLead(
            lead,
            lead.ml_leads || null
          );
      }
    
      if (
        lead.status === "novo" ||
        !lead.status
      ) {
    
        leads.novos.push(lead);
    
      } else if (lead.status === "primeiro_contato") {
    
        leads.primeiro_contato.push(lead);
    
      } else if (lead.status === "em_conversa") {
    
        leads.em_conversa.push(lead);
    
      } else if (lead.status === "fechado") {
    
        leads.fechado.push(lead);
        
      } else if (lead.status === "perdido") {

          leads.perdido.push(lead);
        }
    }

    return c.json(leads);

  } catch (err) {

    console.error("LIST ERROR:", err);

    return c.json({
      error: "Erro ao buscar leads"
    }, 500);
  }
});




// 🔥 atualizar lead
app.get("/ia/leads/:id", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const limite =
      limitarRequisicao(c, `ia:${user.id}`, 30, 60 * 1000);

    if (limite) return limite;

    if (!usuarioTemIA(user)) {
      return c.json({
        error: "IA disponivel apenas no plano Ouro"
      }, 403);
    }

    if (!user.ia_ativo) {
      return c.json({
        error: "IA desativada para este usuario."
      }, 403);
    }

    const configIA =
      await buscarConfigIA();

    if (configIA?.status !== "contratado") {
      return c.json({
        error: configIA?.status === "pausado"
          ? "Uso da IA pausado pelo administrador."
          : "IA nao configurada pelo administrador."
      }, 403);
    }

    const limiteIA = await validarLimiteIAUsuario(user);

    if (!limiteIA.permitido) {
      return c.json({
        error: limiteIA.motivo
      }, 429);
    }

    const id = c.req.param("id");

    const leadResult = await client.query(
      `
      SELECT
        l.id,
        l.nome,
        l.telefone,
        l.email,
        l.status,
        l.origem,
        l.campanha,
        l.observacao,
        l.score,
        l.score_manual,
        l.motivo_perda,
        l.respostas_qualificacao,
        l.criado_em,
        n.slug AS nicho_slug,
        n.nome AS nicho_nome,
        (
          SELECT string_agg(wml.conteudo, ' ' ORDER BY wml.criado_em)
          FROM whatsapp_mensagens_log wml
          JOIN whatsapp_conversas wc ON wc.id = wml.conversa_id
          WHERE wc.lead_id = l.id AND wml.direcao IN ('entrada', 'echo')
        ) AS whatsapp_transcricao
      FROM leads l
      LEFT JOIN nichos n ON n.id = l.nicho_id
      WHERE l.id = $1
      AND l.usuario_id = $2
      LIMIT 1
      `,
      [id, user.id]
    );

    const lead = leadResult.rows[0];

    if (!lead) {
      return c.json({ error: "Lead nao encontrado" }, 404);
    }

    const todosLeads = await client.query(
      `
      SELECT
        l.id,
        l.nome,
        l.telefone,
        l.email,
        l.status,
        l.origem,
        l.campanha,
        l.observacao,
        l.score,
        l.score_manual,
        l.motivo_perda,
        l.respostas_qualificacao,
        l.criado_em,
        n.slug AS nicho_slug,
        n.nome AS nicho_nome,
        wt.transcricao AS whatsapp_transcricao
      FROM leads l
      LEFT JOIN nichos n ON n.id = l.nicho_id
      LEFT JOIN (
        SELECT wc.lead_id, string_agg(wml.conteudo, ' ' ORDER BY wml.criado_em) AS transcricao
        FROM whatsapp_mensagens_log wml
        JOIN whatsapp_conversas wc ON wc.id = wml.conversa_id
        WHERE wc.lead_id IS NOT NULL AND wml.direcao IN ('entrada', 'echo')
        GROUP BY wc.lead_id
      ) wt ON wt.lead_id = l.id
      WHERE l.usuario_id = $1
      `,
      [user.id]
    );

    marcarLeadsRecorrentes(todosLeads.rows);

    const leadRecorrente =
      todosLeads.rows.find((item: any) =>
        Number(item.id) === Number(lead.id)
      );

    if (leadRecorrente) {
      lead.repetido = leadRecorrente.repetido;
    }

    const modeloML =
      usuarioTemRecurso(user, "machine_learning_leads")
        ? treinarModeloMLLeads(todosLeads.rows)
        : null;

    const scoreData = calcularScoreLead(lead);
    lead.score = scoreData.score;
    lead.score_base = scoreData.base;
    lead.score_pontos = scoreData.pontos;

    const ml =
      modeloML
        ? preverConversaoMLLead(modeloML, lead)
        : null;

    if (ml) {
      lead.ml_leads = ml;
      aplicarMLAoScoreLead(lead);
    }

    let analise =
      gerarAnaliseIAOuroLead(
        lead,
        lead.ml_leads || null
      );

    let usoIA: any = null;

    try {
      usoIA =
        await gerarAnaliseIAOpenAI(
          lead,
          lead.ml_leads || null
        );

      if (usoIA?.analise) {
        analise = usoIA.analise;
      }
    } catch (err) {
      console.error(
        "OPENAI IA LEAD FALLBACK:",
        err
      );
    }

    await registrarUsoIA(
      Number(user.id),
      "analise_lead",
      "lead",
      lead.id,
      usoIA?.custo_estimado || IA_CUSTO_ESTIMADO_PADRAO,
      Number(usoIA?.usage?.input_tokens || 0),
      Number(usoIA?.usage?.output_tokens || 0),
      usoIA?.provider || "openai"
    );

    return c.json({ analise });

  } catch (err) {
    console.error("ERRO IA LEAD:", err);
    return c.json({
      error: "Erro ao gerar analise de IA"
    }, 500);
  }
});

// Corpo compartilhado de atualização de status/observação de lead — usado pelo
// PUT /leads/:id (corretor arrastando card / editando no drawer, origem
// 'manual') e pelo classificador automático que lê a conversa do WhatsApp
// (processarClassificacaoStatusLeadIA, origem 'ia_conversa'). Mesmo SQL e
// mesmos efeitos colaterais nos dois casos — só o texto do histórico muda
// com a origem.
async function atualizarStatusLeadBackend(
  leadId: string | number,
  usuarioId: number,
  dados: { observacao?: string | null; status: string; motivo_perda?: string | null; score_manual?: string | null },
  origem: "manual" | "ia_conversa" = "manual"
) {
  const { observacao, status, motivo_perda, score_manual } = dados;

  // 🔥 busca lead atual
  const leadAtual = await client.query(
    `
    SELECT
      status,
      observacao
    FROM leads
    WHERE id = $1
    AND usuario_id = $2
    `,
    [leadId, usuarioId]
  );

  const statusAntigo =
    leadAtual.rows[0]?.status || "";

  const observacaoAntiga =
    leadAtual.rows[0]?.observacao || "";

  const result = await client.query(
    `
    UPDATE leads
    SET
      observacao = $1,
      status = $2,
      motivo_perda = $3,
      score_manual = $4
    WHERE
      id = $5
    AND usuario_id = $6
    RETURNING *
    `,
    [
      observacao,
      status,
      motivo_perda,
      score_manual,
      leadId,
      usuarioId
    ]
  );

  // 🔥 HISTÓRICO STATUS
  if (status !== statusAntigo) {

    let descricao =
      `Lead movido de "${statusAntigo}" para "${status}"`;

    // perdido
    if (
      status === "perdido" &&
      motivo_perda
    ) {

      descricao =
        `Lead perdido: ${motivo_perda}`;
    }

    // fechado
    if (status === "fechado") {

      descricao =
        "Lead marcado como FECHADO";
    }

    if (origem === "ia_conversa") {
      descricao += " (decidido por IA com base na conversa do WhatsApp)";
    }

    await client.query(
      `
      INSERT INTO lead_historico (
        lead_id,
        usuario_id,
        tipo,
        descricao
      )
      VALUES ($1,$2,$3,$4)
      `,
      [
        leadId,
        usuarioId,
        "status",
        descricao
      ]
    );
  }

  // 🔥 HISTÓRICO OBS
  if (
    observacao &&
    observacao !== observacaoAntiga
  ) {

    await client.query(
      `
      INSERT INTO lead_historico (
        lead_id,
        usuario_id,
        tipo,
        descricao
      )
      VALUES ($1,$2,$3,$4)
      `,
      [
        leadId,
        usuarioId,
        "observacao",
        observacao
      ]
    );
  }

  const leadAtualizado =
    result.rows[0];

  // RETURNING * só traz dados crus (nicho_id como FK, nada de WhatsApp) —
  // sem isso a pontuação/ML por nicho/conversa nunca dispara ao editar um
  // lead direto, só na listagem (GET /leads, que já faz os JOINs).
  await enriquecerLeadParaInteligencia(leadAtualizado);

  const scoreData =
    calcularScoreLead(leadAtualizado);

  leadAtualizado.score =
    scoreData.score;
  leadAtualizado.score_base =
    scoreData.base;
  leadAtualizado.score_pontos =
    scoreData.pontos;

  avaliarEEnviarQualificacaoLead(leadAtualizado, usuarioId)
    .catch(err => console.error("ERRO avaliarEEnviarQualificacaoLead (atualizarStatusLeadBackend):", err));

  return leadAtualizado;
}

app.put("/leads/:id", authMiddleware, async (c) => {

  try {

    const user: any = c.get("user");

    const id = c.req.param("id");

    const {
      observacao,
      status,
      motivo_perda,
      score_manual
    } = await c.req.json();

    const leadAtualizado = await atualizarStatusLeadBackend(
      id,
      user.id,
      { observacao, status, motivo_perda, score_manual },
      "manual"
    );

    return c.json({
      success: true,
      lead: leadAtualizado
    });

  } catch (err) {

    console.error("UPDATE LEAD ERROR:", err);

    return c.json({
      error: "Erro ao atualizar lead"
    }, 500);
  }
});



// 🔹 excluir lead
app.delete("/leads/:id", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const id = Number(c.req.param("id"));
    if (!Number.isFinite(id)) return c.json({ error: "ID inválido" }, 400);

    const result = await client.query(
      `DELETE FROM leads WHERE id = $1 AND usuario_id = $2 RETURNING id`,
      [id, user.id]
    );

    if (!result.rows.length) return c.json({ error: "Lead não encontrado ou sem permissão" }, 404);

    return c.json({ message: "Lead excluído com sucesso" });
  } catch (err) {
    console.error("ERRO AO EXCLUIR LEAD:", err);
    return c.json({ error: "Erro ao excluir lead" }, 500);
  }
});

// 🔹 agendar data de contato do lead
app.patch("/leads/:id/data-contato", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const leadId = Number(c.req.param("id"));
    const body = await c.req.json().catch(() => ({}));
    const dataContato = body.data_contato ?? null;
    const observacaoAgendamento = body.observacao_agendamento ?? null;

    // busca o lead e o dono para checar permissão em JS
    const leadRow = await client.query(`SELECT id, usuario_id FROM leads WHERE id = $1`, [leadId]);
    if (!leadRow.rows[0]) return c.json({ error: "Lead não encontrado" }, 404);

    const leadOwnerId: number = leadRow.rows[0].usuario_id;
    const ownerRow = await client.query(`SELECT id, admin_id FROM usuarios WHERE id = $1`, [leadOwnerId]);
    const leadOwnerAdminId: number | null = ownerRow.rows[0]?.admin_id ?? null;

    const uid = Number(user.id);
    const temPermissao =
      Number(leadOwnerId) === uid ||           // lead é do próprio usuário
      Number(user.admin_id) === Number(leadOwnerId) ||  // corretor acessando lead do seu admin
      Number(leadOwnerAdminId) === uid;        // admin acessando lead de um corretor dele

    if (!temPermissao) {
      console.error("PERMISSAO NEGADA data-contato:", { leadOwnerId, userId: user.id, userAdminId: user.admin_id, leadOwnerAdminId });
      return c.json({ error: "Sem permissão para editar este lead" }, 403);
    }

    const res = await client.query(
      `UPDATE leads
       SET data_contato = $1,
           observacao_agendamento = $2,
           lembrete_1dia_enviado = FALSE,
           lembrete_dia_enviado  = FALSE
       WHERE id = $3
       RETURNING id, data_contato, observacao_agendamento`,
      [dataContato, observacaoAgendamento, leadId]
    );

    if (!res.rows[0]) return c.json({ error: "Falha ao atualizar" }, 500);
    return c.json(res.rows[0]);
  } catch (err: any) {
    console.error("ERRO DATA CONTATO:", err);
    return c.json({ error: "Erro ao salvar data de contato", detail: String(err?.message || err) }, 500);
  }
});

