// criar campanha manual (não-Meta) com dados do nicho
app.post("/campanhas/manual", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const body = await c.req.json();

    const {
      nome,
      nicho_id,
      // campos de imóveis
      tipo_imovel,
      finalidade,
      valor_min,
      valor_max,
      regiao,
      // campos de saúde
      operadora,
      tipo_plano,
      faixa_etaria_min,
      faixa_etaria_max,
      cobertura,
      acomodacao,
      // campos de suplementos
      produto,
      objetivo,
      marca,
      publico_alvo,
      // campos de higienização
      tipo_servico,
      frequencia,
      area_atendida,
      // campos de telecom
      porte_empresa,
      situacao_atual
    } = body;

    if (!nome) {
      return c.json({ error: "Nome obrigatório" }, 400);
    }

    if (!nicho_id) {
      return c.json({ error: "Nicho obrigatório" }, 400);
    }

    const nichoRes = await client.query(
      `SELECT slug FROM nichos WHERE id = $1`,
      [nicho_id]
    );
    if (nichoRes.rows.length === 0) {
      return c.json({ error: "Nicho inválido" }, 400);
    }
    const slug = nichoRes.rows[0].slug;

    const habilitado = await client.query(
      `SELECT 1 FROM usuario_nichos
       WHERE usuario_id = $1 AND nicho_id = $2`,
      [user.id, nicho_id]
    );
    if (habilitado.rows.length === 0) {
      return c.json(
        { error: "Você não tem esse nicho habilitado" },
        403
      );
    }

    const campRes = await client.query(
      `INSERT INTO campanhas (usuario_id, nome, status, origem, nicho_id)
       VALUES ($1, $2, 'ACTIVE', 'manual', $3)
       RETURNING id`,
      [user.id, nome, nicho_id]
    );
    const campanhaId = campRes.rows[0].id;

    if (slug === "imoveis") {
      await client.query(
        `INSERT INTO campanhas_imoveis
           (campanha_id, tipo_imovel, finalidade, valor_min, valor_max, regiao)
         VALUES ($1, $2, $3, $4, $5, $6)`,
        [campanhaId, tipo_imovel ?? null, finalidade ?? null,
         valor_min ?? null, valor_max ?? null, regiao ?? null]
      );
    } else if (slug === "saude") {
      await client.query(
        `INSERT INTO campanhas_saude
           (campanha_id, operadora, tipo_plano, faixa_etaria_min,
            faixa_etaria_max, cobertura, acomodacao)
         VALUES ($1, $2, $3, $4, $5, $6, $7)`,
        [campanhaId, operadora ?? null, tipo_plano ?? null,
         faixa_etaria_min ?? null, faixa_etaria_max ?? null,
         cobertura ?? null, acomodacao ?? null]
      );
    } else if (slug === "suplementos") {
      await client.query(
        `INSERT INTO campanhas_suplementos
           (campanha_id, produto, objetivo, marca, publico_alvo)
         VALUES ($1, $2, $3, $4, $5)`,
        [campanhaId, produto ?? null, objetivo ?? null,
         marca ?? null, publico_alvo ?? null]
      );
    } else if (slug === "higienizacao") {
      await client.query(
        `INSERT INTO campanhas_higienizacao
           (campanha_id, tipo_servico, frequencia, area_atendida, publico_alvo)
         VALUES ($1, $2, $3, $4, $5)`,
        [campanhaId, tipo_servico ?? null, frequencia ?? null,
         area_atendida ?? null, publico_alvo ?? null]
      );
    } else if (slug === "telecom") {
      await client.query(
        `INSERT INTO campanhas_telecom
           (campanha_id, tipo_servico, porte_empresa, situacao_atual, area_atendida)
         VALUES ($1, $2, $3, $4, $5)`,
        [campanhaId, tipo_servico ?? null, porte_empresa ?? null,
         situacao_atual ?? null, area_atendida ?? null]
      );
    }

    return c.json({ id: campanhaId });
  } catch (err) {
    console.error("ERRO POST /campanhas/manual:", err);
    return c.json({ error: "Erro ao criar campanha" }, 500);
  }
});

// duplicar uma campanha existente
app.post("/campanhas/:id/duplicar", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const campanhaId = Number(c.req.param("id"));
    const body = await c.req.json().catch(() => ({}));

    const origRes = await client.query(
      `SELECT c.*, n.slug AS nicho_slug
       FROM campanhas c
       LEFT JOIN nichos n ON n.id = c.nicho_id
       WHERE c.id = $1 AND c.usuario_id = $2`,
      [campanhaId, user.id]
    );

    if (origRes.rows.length === 0) {
      return c.json({ error: "Campanha não encontrada" }, 404);
    }

    const orig = origRes.rows[0];
    const novoNome = body.nome?.trim() || `Cópia de ${orig.nome}`;

    // Destino (Lead Ads vs WhatsApp) pode ser trocado no duplicar — é o único
    // jeito de "converter" uma campanha já rodando, já que a Meta não deixa
    // editar destination_type de um Ad Set em atividade. Sem escolha explícita,
    // mantém o destino original.
    const destinoEscolhido = body.destino !== undefined
      ? resolverDestinoCampanha(body.destino)
      : resolverDestinoCampanha((orig.configuracoes_avancadas || {}).destino);
    const configuracoesNovas = {
      ...(orig.configuracoes_avancadas || {}),
      destino: destinoEscolhido
    };

    const novaRes = await client.query(
      `INSERT INTO campanhas
         (usuario_id, nome, status, origem, nicho_id, daily_budget, configuracoes_avancadas, conta_anuncios_id, plataforma)
       VALUES ($1, $2, 'PAUSED', 'manual', $3, $4, $5, $6, $7)
       RETURNING id`,
      [user.id, novoNome, orig.nicho_id ?? null, orig.daily_budget ?? null,
       JSON.stringify(configuracoesNovas), orig.conta_anuncios_id ?? null, orig.plataforma || "meta"]
    );
    const novaId = novaRes.rows[0].id;

    await copiarDadosNichoCampanha(
      client,
      campanhaId,
      novaId,
      orig.nicho_slug
    );

    return c.json({ id: novaId });
  } catch (err) {
    console.error("ERRO POST /campanhas/:id/duplicar:", err);
    return c.json({ error: "Erro ao duplicar campanha" }, 500);
  }
});

// buscar detalhes do nicho de uma campanha
app.get("/campanhas/:id/nicho-dados", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const campanhaId = Number(c.req.param("id"));

    const campRes = await client.query(
      `SELECT c.id, c.nicho_id, n.slug, n.nome AS nicho_nome, n.cor AS nicho_cor
       FROM campanhas c
       LEFT JOIN nichos n ON n.id = c.nicho_id
       WHERE c.id = $1
         AND c.usuario_id = $2`,
      [campanhaId, user.id]
    );

    if (campRes.rows.length === 0) {
      return c.json({ error: "Campanha não encontrada" }, 404);
    }

    const camp = campRes.rows[0];
    let dados: any = null;

    if (camp.slug === "imoveis") {
      const r = await client.query(
        `SELECT * FROM campanhas_imoveis WHERE campanha_id = $1`,
        [campanhaId]
      );
      dados = r.rows[0] ?? null;
    } else if (camp.slug === "saude") {
      const r = await client.query(
        `SELECT * FROM campanhas_saude WHERE campanha_id = $1`,
        [campanhaId]
      );
      dados = r.rows[0] ?? null;
    } else if (camp.slug === "suplementos") {
      const r = await client.query(
        `SELECT * FROM campanhas_suplementos WHERE campanha_id = $1`,
        [campanhaId]
      );
      dados = r.rows[0] ?? null;
    } else if (camp.slug === "higienizacao") {
      const r = await client.query(
        `SELECT * FROM campanhas_higienizacao WHERE campanha_id = $1`,
        [campanhaId]
      );
      dados = r.rows[0] ?? null;
    } else if (camp.slug === "telecom") {
      const r = await client.query(
        `SELECT * FROM campanhas_telecom WHERE campanha_id = $1`,
        [campanhaId]
      );
      dados = r.rows[0] ?? null;
    }

    return c.json({
      nicho_id: camp.nicho_id,
      nicho_slug: camp.slug,
      nicho_nome: camp.nicho_nome,
      nicho_cor: camp.nicho_cor,
      dados
    });
  } catch (err) {
    console.error("ERRO GET /campanhas/:id/nicho-dados:", err);
    return c.json({ error: "Erro ao buscar dados do nicho" }, 500);
  }
});

// 👁️ preview real do anúncio (como aparece na Meta) para exibir no drawer de detalhes
app.get("/campanhas/:id/preview-anuncio", authMiddleware, async (c) => {
  try {
    const user: any = c.get("user");
    const campanhaId = Number(c.req.param("id"));
    const adFormat =
      String(c.req.query("ad_format") || "DESKTOP_FEED_STANDARD");

    const campRes = await client.query(
      `SELECT c.id, c.usuario_id, c.ad_id, c.adset_id, c.campaign_id, c.status, c.conta_anuncios_id
       FROM campanhas c
       WHERE c.id = $1
         AND c.usuario_id = $2`,
      [campanhaId, user.id]
    );

    if (campRes.rows.length === 0) {
      return c.json({ error: "Campanha não encontrada" }, 404);
    }

    const campanha = campRes.rows[0];

    const conn = await client.query(
      `SELECT access_token
       FROM meta_conexoes
       WHERE usuario_id = $1
       ORDER BY id DESC
       LIMIT 1`,
      [campanha.usuario_id]
    );

    const token = conn.rows[0]?.access_token || null;

    if (!token) {
      return c.json({
        error: "Meta não conectada para esta campanha"
      }, 400);
    }

    let adId = campanha.ad_id;

    // Campanhas sincronizadas direto da Meta (criadas fora da plataforma)
    // podem nunca ter tido o ad_id gravado localmente. Antes de desistir,
    // busca o anúncio direto na Meta usando o campaign_id.
    if (!adId && campanha.campaign_id) {
      try {
        const adsRes: any = await fetch(
          `https://graph.facebook.com/v19.0/${campanha.campaign_id}/ads?fields=id,adset_id&limit=1&access_token=${token}`
        ).then(r => r.json());

        const primeiroAd = adsRes?.data?.[0];

        if (primeiroAd?.id) {
          adId = primeiroAd.id;

          await client.query(
            `UPDATE campanhas SET ad_id = $1, adset_id = COALESCE(adset_id, $2) WHERE id = $3`,
            [adId, primeiroAd.adset_id || null, campanha.id]
          );
        }
      } catch (errBuscaAd) {
        console.error("ERRO BUSCAR AD_ID POR CAMPAIGN_ID:", errBuscaAd);
      }
    }

    if (!adId) {
      return c.json({
        error: "Esta campanha ainda não tem um anúncio publicado na Meta"
      }, 400);
    }

    const previewRes = await fetch(
      `https://graph.facebook.com/v19.0/${adId}/previews?ad_format=${encodeURIComponent(adFormat)}&access_token=${token}`
    );

    const previewData: any = await previewRes.json();

    const previewHtml = previewData?.data?.[0]?.body || null;

    if (!previewRes.ok || !previewHtml) {
      console.error("ERRO PREVIEW ANUNCIO META:", previewData?.error || previewData);
      return c.json({
        error:
          previewData?.error?.error_user_msg ||
          previewData?.error?.message ||
          "Não foi possível carregar o preview deste anúncio na Meta"
      }, 400);
    }

    // 🔗 link real do anúncio (post publicado) para abrir em outra aba — cada
    // rede tem seu próprio permalink (effective_object_story_id no Facebook,
    // instagram_permalink_url no Instagram); usa o da rede pedida em ad_format
    // e só cai pro link da outra rede se o pedido não tiver um disponível
    // (ex: anúncio nunca rodou no Instagram), pra nunca linkar Instagram
    // selecionado com uma URL do Facebook (ou vice-versa) sem avisar.
    let linkAnuncio: string | null = null;
    let linkRede: "facebook" | "instagram" | null = null;
    const formatoInstagram = adFormat.toUpperCase().startsWith("INSTAGRAM");

    try {
      const creativeRes = await fetch(
        `https://graph.facebook.com/v19.0/${adId}?fields=creative{effective_object_story_id,instagram_permalink_url}&access_token=${token}`
      );
      const creativeData: any = await creativeRes.json();
      const storyId = creativeData?.creative?.effective_object_story_id || null;
      const linkFacebook = storyId ? `https://www.facebook.com/${storyId}` : null;
      const linkInstagram = creativeData?.creative?.instagram_permalink_url || null;

      if (formatoInstagram && linkInstagram) {
        linkAnuncio = linkInstagram;
        linkRede = "instagram";
      } else if (linkFacebook) {
        linkAnuncio = linkFacebook;
        linkRede = "facebook";
      } else if (linkInstagram) {
        linkAnuncio = linkInstagram;
        linkRede = "instagram";
      }
    } catch (errCreative) {
      console.error("ERRO LINK REAL ANUNCIO META:", errCreative);
    }

    if (!linkAnuncio) {
      const actId = String(campanha.conta_anuncios_id || "").replace(/^act_/, "");
      linkAnuncio = actId
        ? `https://adsmanager.facebook.com/adsmanager/manage/ads?act=${encodeURIComponent(actId)}&selected_ad_ids=${encodeURIComponent(adId)}`
        : null;
      linkRede = null;
    }

    return c.json({ preview_html: previewHtml, link_anuncio: linkAnuncio, link_rede: linkRede });

  } catch (err) {
    console.error("ERRO GET /campanhas/:id/preview-anuncio:", err);
    return c.json({ error: "Erro ao buscar preview do anúncio" }, 500);
  }
});

// atualizar detalhes do nicho de uma campanha
